/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120227-8","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"建設委員会","time":"午前１０時００分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件抜き出しています。","topics":[{"id":"topic-01","title":"上、審査の順序を変更いたしまして、(2)から(5)までを先に行い、議案審査の最後に本件を行いますので、よろしくお願いいたします。 それでは","agenda":"上、審査の順序を変更いたしまして、(2)から(5)までを先に行い、議案審査の最後に本件を行いますので、よろしくお願いいたします。 それでは","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今回の改正で、今までだと東京都の同意を得なければならないということで、東京都の計画のそこからはみ出したような、東京都を受けて景観計画をつくるというところにおさまっていたわけですけれども、これから品川区として、そんなに東京都とかけ離れたものではないとしても、品川区独自で設定をするということが可能になるのか、どのくらいまでそういった範囲が広がるのかということはどうなんでしょうか。","respondent":"藤田水とみどりの課長","answer":"個別具体のものについては、同意は必要はないというものの、これまでも東京都が景観計画をつくってずっと進めてきておりますので、その範囲をやはり大きく変えてしまうような形のものはなかなか難しいのかなと思ってあります。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"以前この景観計画をつくるときに、もう全然品川区としての独自性ではなく、東京都のその範囲を上回ることは絶対やりませんよというところで、だったら区がやる意味は何だろうということがあったのですが、協議の内容においては、もう少し力強く品川区のものが出せるというふうに思っているのか、それとも協議という名前があるけれども、そんなに大した変化は望めないという判断なんでしょうか。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"あくまでも景観計画をつくるときの手続きとしてのお話ですので、既に私どもは景観行政団体になって景観計画をつくっているわけで、その中でのことですから、東京都とはもう全然別に。現在の中では、例えば政令指定都市とか中核市、こういったものについては一定の権限を付与していこうという考えだったわけですけれども、もともと市町村が行う事務と都道府県が行う事務が大きくかけ離れるということは。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"もう一つは、そこのところは厳しいというか、自主性が出せるように、これからもこの条例を使っていければいいと思うんですけれども、２つ目の工作物の「新築」と「新設」なんですけれども、これを変えるに当たる理由、今まで見直してきて、何か課題が見えてきたから変えるんだろうと思うんですけれども、そこのところはどういうふうでしょうか。","respondent":"藤田水とみどりの課長","answer":"工作物の場合、言葉としては「新築」とも「新設」とも、両方の言葉を使いながら、工作物の場合は使っておりますけれども、東京都の景観計画のほうが「新築」という言葉でなく「新設」という言葉を使って記載をしていますので、それに単純に合わせたほうが。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"この言葉はただ言葉のことだけで、どこかに変わった意味合いを持つということではないということでいいんですか。","respondent":"藤田水とみどりの課長","answer":"委員のお話のとおりです。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"今、お話を伺って、ほとんど変わらないよというお話なんですが、実際、品川区の所管の作業的には、今まで東京都の同意を得なくてはいけないということで、今回も協議はしてくれよという話なんですが、その辺のところで実務上少しスピーディーにできる、もしくはあまり時間をかけずできるという点はあるのかどうか。","respondent":"藤田水とみどりの課長","answer":"ちょっと説明の仕方が悪くて申しわけございません。景観行政団体になるときに協議、同意が必要であったということで、品川区の場合は既に景観行政団体になっておりますので、この手続きはこれから区が行うものではないので、特にその部分については変更はございません。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"そうすると、ほかの自治体で、まだ自治体独自の景観計画をつくっていないところもあるという中で、今回のこの法律の地域主権一括法の改定で、これを機につくっていないところはつくりなさいと。そのときは、協議はするけれども同意は得なくていいということになったということですか。","respondent":"藤田水とみどりの課長","answer":"委員お話のとおりで、これをきっかけに景観行政がさらに進んでいくものと考えています。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"確かに法律が変わってしまいましたから、それに合わせて条文を変える必要があるんでしょうけれども、これを機会に区としてはどういうことを考えているのか、今後考えたいと思っているのか、趣旨そのものは変わらないというお話でしたけれども、そこの今後の見通しをどんなふうに考えていらっしゃるのか、そこを伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"一部それを緩和したものが都道府県の力によって統治していくことになる。この統治国家論の中の物の考え方で、法体系ができているわけです。地方自治法は、地方公共団体が住民の自治と福祉を守っていくというような明文規定が書かれているわけです。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問","question":"そこについてもう少し伺いたいのは、内容については変わりはないと。ただ、手続きがちょっと変わるんだというところで、今まで協議と同意が必要だったものが、同意が必要なくなったと。この点をどうとらえていらっしゃるのか、伺いたいと思います。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"そういった面では、区がしっかり物を考えて、しっかりやると言っていることを、やはり東京都にも早く認めていただきたかったみたいなところは非常に感じておりますので、今回のような形で、地方公共団体。今回、それをしなくてよくなったということは、これはもう権限委譲の権化みたいなものですから、実は同意があるないは小さなように見えますけれども。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"意見","question":"やはり品川区自身の主体性であったり独自性であったりが、今後より厳しく問われていくのだなと思うんです。今回の中身はそこが出ているものではありませんから、ちょっと別の話にはなりますけれども、今後景観についてもどういうスタンスをつくっていくのか、ここはやはり厳しく見ていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"意見","question":"賛成ですけれども、この法律の流れには危険性もあります。品川区の景観に対する考え方も住民の暮らしや目線に立った景観に切り替えるべきだと思いますので、その点は厳しく見ていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"第３６号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"第３６号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"武内委員","kind":"質問","question":"これもちょっとさっきとまた重複してくるかもしれないんですけれども、こういうふうに品川区に供給計画の事務が移ってきたことで、いろいろ入居者の資格ですとか、資金計画とか、３番に書いてあるようなことで、品川区のほうで決められると、区長が認定というふうになるということだと思いますけれども、それを受けて具体的に何か今までと考え方を大きく変えて、例えば入居者の資格ですとか。","respondent":"柏原住宅担当課長","answer":"入居者の資格等々につきましては法律で厳密に決められておりますので、その部分については何かできるという部分ではないんですけれども、例えば供給計画について、例えば廃止であるだとか用途を変更するであるとか、特優賃住宅でも若干種類がありますので。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今までいろいろなところで出ていた借り上げ型の中でも、いろいろなかなか入居しないようなところとかの更新、するかしないかという話も、今までは一応東京都にお伺いを立てて承認をもらわなくてはいけなかったと、それが品川区の判断でできるようになったという理解でいいんですか。","respondent":"柏原住宅担当課長","answer":"委員がおっしゃるとおりでございまして、今まで東京都に必ずこの供給計画に係る部分については認定、変更等々お願いをしていたんですが、その部分が全くなくなりますので、区の判断でそちらのほうはできるです。","id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問","question":"供給計画の認定について、今まで東京都が認定していた意味というか役割は一体何だったのか、それが今回区に来るということでどういう変更となるのか、その理念というのか、そこの意味合いをもう一度お伺いしたいと思います。","respondent":"柏原住宅担当課長","answer":"そういったところについてオーナーとの話し合いで、この部分は用途廃止しましょうということが得られれば、区の認定でその供給計画を変更できるというところもありますので、法律の範囲内ではありますけれども。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"今までは東京都がバランスをとりながら、この中間所得層の住宅の供給を見ていたと。直接条例とはかかわりませんけれども、やはり住宅というのであれば、家賃の安い区営住宅こそと私は思いますけれども、今後のこの住宅供給について、何かこの変更に伴って、今、考えていることがあるのかどうか伺いたいと思います。","respondent":"柏原住宅担当課長","answer":"問題のある部分もありますので、この供給計画の認定事務が区に来るということで、先ほど申した個別の用途廃止であるとか、いろいろな部分で自由度が出てきたと思われますので、その区民住宅の今までの課題といったところを、どういった部分が解決できるかどうかについては。","id":"exchange-014"}]},{"id":"topic-03","title":"第３７号議案 品川区建築審査会条例の一部を改正する条例","agenda":"第３７号議案 品川区建築審査会条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"いたずらにこれは何か変更だけを求めたに過ぎないと思うんですけれども、そこのところ、今後いろいろな部分の条例を変更するにおいて、どのようなスタンスでやっていかれるのか。ちょっと部署が違いますけれども、その辺、まちづくり事業部においては、この建設委員会にかかわる所管においては、そこのところをどのように考えていらっしゃるのか伺いたい。","respondent":"山崎マスタープラン担当課長","answer":"第５条と第７条につきましては、本条例につきましては昭和５８年に条例を制定してございまして、経年をしてきております。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問","question":"これまで防災まちづくり事業部に品川区建築審査会があったわけで、それを今回、組織改正によって都市環境事業部になるわけですけれども、そこの趣旨と理由をご説明いただけますでしょうか。","respondent":"松代都市計画課長","answer":"そういった中で、建築審査会、これは都市計画課の中で処理をしております。この都市計画課は、今現在は防災まちづくり事業部ということで組織名称を持っておりますが、今回の４月１日からの組織改正に当たりましては、都市環境事業部という部名に変更することになりました。","id":"exchange-016"}]},{"id":"topic-04","title":"第３８号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３８号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"冒頭の説明なんですけれども、確かに都市計画決定を受けたからというわけだけれども、そもそもなぜこの変更なのかというところが冒頭なかったので、そこを伺いたいと思うんです。現状の建物の高さがどうで、それをなぜ５０ｍに制限をしたのか、あわせてご説明いただきたいと思います。","respondent":"中村建築課長、三宅都市開発課長","answer":"当地区なんですけれども、今、品川区の市街地整備基本方針の中で、工業機能の高度化あるいは近代化を促進して活性化を図る、都市型の工業地域ゾーンということで位置づけられているということで。なぜ５０ｍの高さ制限を決めているかというところですが、こちらの地域、用途地域を変更して容積率を１００％アップしておりますけれども、この土地利用に見合った高さということで、５０ｍです。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問","question":"５０ｍにした理由は、その権利者の方からのご意見も踏まえてということですけれども、今回のＡ地区は実際は第一三共がほとんどというか、ほぼすべて持っているわけで、１つ伺いたいのは、なぜこの１企業の要請だけに品川区がこたえるのか、一方で逆に５０ｍに制限をしているわけですよね。その兼ね合いの理由はどこにあるのか、そこを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"すみません、ちょっと説明が不足しておりまして、地区の整備方針を決めているその全体の１７haの中の、今、第一三共がメインにある整備計画のエリアではなく、もうちょっと南のあたりの方からそのようなご意見もございましたので、それも勘案して。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"５０ｍに設定したことは、私はよいことだなと思っているんです。ただ、今のやりとりの中で、その１７haの中の方々から、またさらにその周辺からどういうご意見・ご要望が出されて、それをこの計画に反映されたのか、そこの内容を伺いたいと思います。にもかかわらず、そこを制限をかけているわけですから、この理由をしっかりとご説明いただきたいと思います。","respondent":"三宅都市開発課長","answer":"研究棟ですので、例えばものすごく高いものが効率がいいかというと、決してそういうことではございませんで、やはり地上になるべく近いところで研究施設があったほうが、要するに基準階が広いほうがいいという考えですので、それに合った形の高さで設定しております。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"１点だけ。これはちょっと直接条例と関係ないので申しわけないです。Ａ地区・Ｂ地区以外の南側のところも一応地区内に入っているんですか。ここは何かこういう制限とか緩和とか、何かあるのか、それともないのか。","respondent":"三宅都市開発課長","answer":"こちら、その他の地区として出ているんですが、ここは条例の範囲外でございまして、規制はございません。地区計画のほうで全体の大まかな方向だけ決めているです。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問","question":"賛成です。周辺の再開発の基準を見ますと、その中でこの５０ｍの制限というのは非常に低いですから、そういう意味では理解したいなと思います。だったら、ほかの開発についてもしっかり高さを制限すべきだと意見を添えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-05","title":"議案第１８号 品川区手数料条例の一部を改正する条例","agenda":"議案第１８号 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今、東京都と手数料は変更がないということで説明があったんですが、もしこれからいろいろな手数料の変更を検討するということになれば、東京都だと２３区横並びでということがあったと思うんですが、これからはその辺は何か変更があり得るのか、それとも全然そういうことではないということなのか、どっちでしょうか。","respondent":"柏原住宅担当課長","answer":"全く新しい事務ですので、東京都から、今、事務を引き継いでいるところですので、４００円ということで設定をさせていただいているんですが、他区の状況を見ますといろいろ考えているところもありますので、今後もその事務の申請の具合であるとか、それから効率化等々を考えて。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"最初の外国人登録関係のほうで、今度は通常の住民基本台帳のほうに外国人の方たちも一緒に組み入れられるということになるんですか。その辺のいわゆる事務的な部分でどうなのか、大丈夫なのか、準備はされていると思うんですけれども、その辺のところが一つと、それからマンションのほうは、今、いろいろありましたけれども、これに関しては、いわゆる事務作業量が区のほうでちょっと増えますよね。","respondent":"梶戸籍住民課長、柏原住宅担当課長","answer":"それをもとに、また変更等といったものを、手続き、いろいろ調査をいたしまして、７月９日からこちらのほうを住民票に移していくです。ただ、現在進行形で、品川区でマンション建て替えという中では、今、ございませんので、今すぐ何かというのはないんですけれども、そういったところで事務は増えることが見込まれるということになります。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"今のはいわゆる財調算定で上乗せされるという考えでいいんですか。違うの。まだ決定じゃないの。","respondent":"岩田都市環境事業部長","answer":"やはりいろいろ難しいんですね。特に財源とかいろいろ、皆さん方の持ち出しのお金をどうするかとか、いろいろ大変で、実績はありません。１件、数年前にいきそうだというのがあったんですけれども、やはり内部分裂でとまってしまっているということで。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"マンションの建て替えのことについて、先ほど、新たな事務というのはこの発行にかかわる事務だけだというお話がありましたけれども、冒頭にご説明があったとおり地域主権一括法の関係で、例えばこのマンション建替組合の法人に対して、資格がありますよという行為そのものも区に来るのか、その基準というのも区の考え一つで変わるものなのか、いやいや別に定められているものなのか。","respondent":"梶戸籍住民課長、柏原住宅担当課長","answer":"ただいまのご質問です。こちらの条例改正のほうは、外国人の登録原票の写し等の交付手数料の文言がありますので、そちらの３本が今後７月９日からなくなりますので、それの削除という形です。事務の部分です。ちょっと細かなお話をしますと、今まで、平成１４年にこの法律ができたときに、区のほうでもマンションの建て替えがあった際には受け付けをして、都に書類を流すという手続きをしていたんです。","id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"マンションのほうの確認だけですけれども、区のほうに事務は来るけれども、その基準が変更がないというか、できないといいますか、今のそこだけ、もう一度ご説明いただきたいと思います。","respondent":"柏原住宅担当課長","answer":"委員がおっしゃるとおりでございまして、特に区のほうで何か事務の判断とかいうことになると、法律に決まった内容で判断していくということになります。","id":"exchange-026"}]},{"id":"topic-06","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"武内委員","kind":"質問","question":"これはたまたま連日で続いてしまったわけですけれども、例えば交通事故もそうでしょうけれども、こういうのが起きたときに、一応どういうふうな徹底をするのか。そもそも大きさによってやるのか、それからあと、直接の職員ではなくて、いわゆる傭上車両で来る方たちもいますよね。そういう方たちにも徹底とかはできるものなのか、その辺の徹底はどうなっているんですか。","respondent":"太田品川区清掃事務所長","answer":"それから翌日、毎朝朝礼を実施していますので、朝礼の中でこういう事故があったということで、十分気をつけるようにということでの注意喚起をしています。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"車両持ち込みで来る方たち、そういう方たちにも同じように徹底できるということでいいんでしょうか。","respondent":"太田品川区清掃事務所長","answer":"これは基本的には操作は区の収集職員が圧縮をかける操作等はやりますので、いわゆる交通事故の場合については、当然会社、あるいは傭上会社、当該運転手等を含めて、注意をするということで徹底をしています。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問","question":"やはりそこも含めて考えていかないと、今回これで済みましたけれども、一番怖いのはやはり清掃車の中でスプレー缶に火がついて、車ごと火がついてしまうこともたまに報告されているわけですから、そういうものというのはどんなふうに対応をお考えなのか、ご説明いただけますでしょうか。","respondent":"太田品川区清掃事務所長","answer":"ご指摘の部分は、今、冬ですので、簡易コンロとかいいますか、そういった分のガス缶の部分が出てまいります。","id":"exchange-029"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"どうしても冬の季節になりますと、カセットコンロを使うことも多くなってきて、なかなか、正直言うとあまり捨てる機会がないですから、どう捨てていいのかというのもよくわからないというのが正直なところなんですよね。ただ、それが事故につながりかねない問題もありますから、引き続きどのように安全に捨てる方法があるのか、そういう周知もあわせて進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-07","title":"平成２３年度目黒川水質改善対策検討のまとめ","agenda":"平成２３年度目黒川水質改善対策検討のまとめ","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"目黒川の水質改善対策、最終的なまとめというお話ですけれども、これで終わってしまうのか。今、いよいよぶくぶくをつけているわけですよね。それ自体は、今後どういうことになっていくのか伺いたいと思います。東京都の要請の中で「抜本的な水質改善への取り組みを進めることを約束した」とあって、どういう中身なのか、ちょっとご説明いただきたいと思います。","respondent":"藤田水とみどりの課長","answer":"それからしゅんせつを行った結果水質がどう変わるか、そういったこともひとつ東京都と品川区、目黒区、世田谷区共同していろいろ調査を進め、その後のここに書いてあります、短期・長期に向けた対策を実施していきたいと考えておるものです。","id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"目黒川をきれいにしたいというのは、近隣の方々を含め長年の期待と強い要望で、いわばこの間、品川区は主体的に何とかできないのかと取り組んできたと思うんです。つまり川底を一回きれいにしてみよう、そこのところで、この間苦労と研究のテーマでもあったわけで、東京都がどういうことと方法を考えているのか、それから今後の見通しも含めてご説明いただけますでしょうか。","respondent":"岩田都市環境事業部長","answer":"これは行政、役所だけではなくて、地域住民と一体となった大運動が起きないと、なかなか東京都が足を一歩前に出せないということがありますので、今後品川区としては３区と足並みをそろえながら、地域の住民と一緒に手をつないで、東京都のお尻をつつくということに。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"その明言の話なんですけれども、ちょっと勉強不足で申しわけないんですが、平成２４年度の東京都の予算の中に、今、明言したとありますけれども、具体的に何かわかる形で公表されているのでしょうか。","respondent":"藤田水とみどりの課長","answer":"先般、担当課長のほうとちょっとお話をしましたけれども、もし可能であれば今年度の予算の中でやりたいということで話がありましたので、今年度の予算、来年度の予算等の中に明確な形で、おそらく目黒川としてやるというような形ではなく。","id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"全体のパイというのは、今、部長がおっしゃったような川全体のということで、あと平成２４年度に数字的に何かというのはあるんでしょうか。","respondent":"藤田水とみどりの課長","answer":"全体のパイというのは、東京都全体の中でしゅんせつ作業はずっとやっておりますので、その中でやっていくということで聞いてあります。そういう面で言うと、目黒川用ということで、平成２４年度の中に明確に記載があるというものではないと考えております。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"今後の取り組み（案）のところで、住民協力による河川監視というのがあるんですけれども、これはどういうイメージなのか、ちょっとこれ、監視というところだけよくわからないんです。何を住民に求めているのでしょうか。","respondent":"藤田水とみどりの課長","answer":"そういったものを目黒川のほうでも来年度についてはやっていこうということで考えておりますので、そういった機会も使いながら、地域の方々と目黒川を見守っていくためのことを進めていきたいと考えています。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"そうすると、先ほど部長が住民の動きが大事だとおっしゃって、その中でやはり住民がどういう動きをすることがいいのかというののメニューを示すとか、そういうことも必要だと思って、今、１つはそういう案だということなんですけれども、具体的には分流式になれば汚水とかそういったものがなくなるんだけれども、それは長期的にはすぐには対応できないということで。","respondent":"岩田都市環境事業部長","answer":"行政もいろいろな種まきはしてきたんですけれども、数年前に五反田を中心に、目黒川を考える地域の方たちが出てまいりまして、ついにＮＰＯがつくられました。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"いろいろなところから川を使っていくというところで、身近に感じていただくということで進めていただきたいと思うんですが、ここのところの住民協力による河川監視という言葉よりも、これは（案）ですから、やはり台所と川が随分離れてしまっているようなところをもう少し身近にするとか、今、おっしゃった啓発も必要なんですけれども、そういうところで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-08","title":"温暖化対策実行計画の実績報告及び品川区環境計画等の改定","agenda":"温暖化対策実行計画の実績報告及び品川区環境計画等の改定","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"何点かあるんですが、初めに平成２１年度と平成２２年度については、この報告が大体１２月ごろ出てきたと思うんですが、今回ちょっと２カ月くらいおくれてしまったんですが、その辺の理由が何かあれば教えていただきたいのと、それから、今、見通しについてはお示しいただいて、平成２３年度は６％は大丈夫だと予測されるんですが、そうすると例えば平成２４年度、今。","respondent":"野呂瀬環境課長","answer":"３点のご質問だったかと。大体１２月ごろにご報告しているというのが、このくらいになったというのは、１つは庁内検討委員会というのに諮って、それから委員会にご報告をしたというのが一つと、もう一つは報告するときに、やはり来年度の見通しをある程度立ててからとなります。","id":"exchange-038"},{"speaker":"武内委員","kind":"意見","question":"そうすると、その上で、この品川区の環境計画、また新たな品川区地球温暖化防止対策実行計画、これから平成２４年度中に策定することになるわけですけれども、この地域推進計画自体もできてしまっているのであれですけれども、この２５％という大きな目標、国全体もそういう話なんでしょうけれども、その目標設定が一つあるわけですけれども、そこを踏まえて、この第二次の品川区環境計画。","respondent":"野呂瀬環境課長","answer":"ですから来年度、その環境計画を策定するに当たって、その次の計画をどのくらいの削減ができるかどうか、その中で国の動向とか今後の動きとかも含めながら考えていきたいと思っているところです。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今の段階ではもう限られたご答弁になってしまうのだろうけれども、国の動向によっては、一応、今、決まっている２５％という地域推進計画の目標設定を下げるということもあり得るという判断なのか、それともその辺はまだ見通しが立たないんでしょうけれども、あくまでこれはもう目指していくんだという姿勢なのか、今の段階でその辺の区の実際のところはどうなんだという。","respondent":"岩田都市環境事業部長","answer":"こういう急激な原発事故があって、これからエネルギー需給がどう変わっていくか、非常に見通しがわからない段階であっても、将来的な目標が今の段階でぶれてしまいますと、すべての計画が水の泡と化してしまいますから、あくまで２５％をきちんと見据えた上で。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"一つ行政として、区の区有施設に限って温暖化防止対策をしましょうということのような、地域推進計画と区の地球温暖化防止対策実行計画というのは横の位置だと思うんですけれども、その中で、品川区環境計画の中にこの第三次を一緒に整理、幾つも計画があることは避けたほうがいいと思うので、わかりやすくなると思うんですけれども、あまりそういうところに力を入れ過ぎると、品川区環境計画というものに。","respondent":"野呂瀬環境課長","answer":"環境計画といいますのは、環境全体を網羅したものです。これにつきましては、当然外部の方から委員を募りまして、例えば事業者、それと町会とか区の商店街連合会とか、それから区民の皆様からも公募を募って、その中で１年間かけて策定していく。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"品川区環境計画と品川区温暖化防止対策実行計画を一括して改定し、というところが同時並行で同じようにつくっていって、内容だけを整合性を持たせるというイメージでいいんでしょうか。","respondent":"野呂瀬環境課長","answer":"品川区環境計画という上位計画に沿った温暖化防止の趣旨があって、それに基づいて品川区役所として、１事業者としてどういう形で進んでいくかという品川区温暖化防止対策実行計画を一緒につくっていくということです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"そのときに、地域推進計画に定められたものが、今度第三次になっていくと思うんですけれども、そこの３つの計画を、区は区のこういう報告をしながら着実に進めることはできるんですけれども、地域推進計画なんかも、どういうふうに進めていくかというのをもう少しチェックをしながらする仕組みが必要なんですけれども、その辺がどういうふうに動いているか、なかなか見えてこないんですが。","respondent":"野呂瀬環境課長","answer":"今、これから委員を募集しまして、それから顔合わせというのを新年度の５月、６月ぐらいを予定しています。","id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"排出量全体を減らそうとしたのに増えてしまって、何で６％達成が見通せるのかというのがやはりよくわからない。ここの資料１－２を見ると、実績では使用量が増えてしまったわけですね。なのに６％削減が達成可能だと見通すのが何でだろうということなんです。それを一つ伺いたいと思います。その中で、この１m2当たりを出す理由というのは何なのかなというのをあわせて伺いたいと思います。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"先ほど６％達成可能と申しましたのは、平成２２年度はできなかったわけですから、平成２３年度、今年の３月いっぱいまでの使用量がどうかということで、とりあえず１２月までの大規模受電施設の速報値が出ましたので。はいわゆるＰＰＳとかいろいろあります。ただ、全体的な総量から比べると、電気、これは６,０００万Kwhですので、今の時点ではさほど影響はない。","id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これというのは、使用量そのものが増えたということになるのではないでしょうか。３つ目は自然エネルギーのことですけれども、今、いろいろやっているけれども、さほど影響がある範囲ではないという話ですけれども、やはりＣＯ２換算の排出を減らすために、自然エネルギーの活用を広げていくという考え方をしっかり持つことが、目標設定することが、必要ではないかと思うんですけれども、いかがでしょうか。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"ですから、区民の方に誤解のないように、今後これを説明していかなければいけませんので、今日は生データをまず議会のほうに、見方を変えるとこういうふうに見えますよというものを、今日はお出しをさせていいただいたです。それと太陽エネルギー等々も、これは本会議等でもご答弁申し上げていますけれども、やはり可能な限りは当然区の施設にもそういう自然エネルギーのほうも継続して取り入れていく考えはあります。","id":"exchange-045"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"だから１m2当たりで見れば減るのかもしれないけれども、目標の設定そのものは出るものを減らそうというわけですから、そこを見るとやはり増えている。この延長の理由がちょっとまだよくわからなかったので伺いたいんですけれども、その計画を策定するために１年間延長しますよということなのか、それとも違うのか、１年間延長する理由というのは何なのか、もう一度ご説明いただけますか。","respondent":"野呂瀬環境課長","answer":"後段のほうからご回答しますけれども、１年間延長するのは、本来でしたら品川区地球温暖化防止対策実行計画というのは５年ですので、今年度にもう策定をしなければいけなかったものなんですけれども、来年度、平成２４年度に、１０年たちます品川区環境計画。","id":"exchange-046"}]},{"id":"topic-09","title":"休憩前に引き続きまして、報告事項を行います。 (5)地籍調査事業","agenda":"休憩前に引き続きまして、報告事項を行います。 (5)地籍調査事業","exchanges":[{"speaker":"武内委員","kind":"質問","question":"ちょっと何か話が大きくてわからないので、教えてもらいたいんですけれども、今までやってきたものが全部だめというか、もう一回やり直さなくてはいけないということなのか、それとも平成２３年度、変更がありましたけれども、そこだけの影響なのか。何か今のお話だと、全部今までやってきて積み重ねていたものが、その大もとが狂うことで全部影響を、みたいな話だったので、その辺をちょっと教えてください。","respondent":"井浦土木管理課長","answer":"個々の測量についてはそのように言えるところですが、品川区が行ってまいりましたいわゆる国土調査法に基づく地籍調査事業につきましては、品川区内の広範囲にわたって公共測量を実施してまいりましたので、国土地理院あるいは東京都とも協議しまして、補正の必要があるのか。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、この裏のほうにある５６カ所の部分の補正なのか、３５７カ所も含めてなのか、それで、いずれにしても何か手直しが必要だという判断になりそうだということなんでしょうか。","respondent":"井浦土木管理課長","answer":"委員ご指摘のとおりでございまして、５６カ所につきましては、平成２３年度中にすべて改定を実施してまいります。３５７カ所につきましても、すべて測量するか、計算上の改定で済むかにつきましては、専門的な見地から法令にのっとりまして適切に処理してまいたいと考えています。","id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"同じようなことなんですけれども、２７cmずれたということは、例えば私の家の敷地だったらちょうど２７cmずれているという判断なんですか。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"それから２３区でそれ以外のエリアについては、電子基準点という国家の基準点を設定している３エリアにつきましては公表してございまして。今までの２級、３級基準点は、すべて座標値で押さえています。東西方向、ＸＹ軸にあと高さ。だからＸＹＺの座標軸で、世界標準の座標点で押さえています。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、変更前と変更後と、これは当然ながら地籍調査がずれていますよね。すると、大体これは１年おくれたということでしょうか。これはずっと１年のおくれだけで、これが広がるということはないんでしょうか。大丈夫でしょうか。","respondent":"井浦土木管理課長","answer":"これは、国土交通省に提出しております平成３１年度までの計画面積がありますので、１年半程度おくれまして、その後は平成３１年以降の計画の中に盛り込まれると考えています。","id":"exchange-050"},{"speaker":"中塚副委員長","kind":"確認","question":"大きい地震があって、全体的には同じ方向に移動したという話ですけれども、うちの家の近所の西大井四丁目山王銀座商店街で見ると、明らかに２cmとか３cmとかずっとずれているようなところもありまして、要するに土地の大きさそのものが伸びたというか、あらかじめ上と下で確認したものが広がったのか狭まったのか、そういう土地の広さ、大きさそのものが変わっている状況というのは。","respondent":"井浦土木管理課長","answer":"宅地開発等の場合に、測量の図面はどうなのかというようなことにも関連しているかと思いますが、先ほど部長からも答弁しましたように、測量の範囲が一様に同じ方向で移動していると考えられますので、隣り合う座標間の整合はとれておりますので。","id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問","question":"そうすると、固定資産税や何か個々のおうちがやった境界確定そのものの座標軸も動いていってしまうのかなと思いまして、そういう場合というのはどういうふうにしていくんでしょうか。なので、どういう対応になっていくのか。これから測定して国の判断というのもまだあるんですけれども、ちょっとそこをご説明いただけるでしょうか。","respondent":"岩田都市環境事業部長","answer":"ただ、これは一遍全部調査してみないと、多少のゆがみが出ている可能性はゼロではありませんので、これらの結果を見てから判断したいということです。","id":"exchange-052"}]},{"id":"topic-10","title":"次、(6)下神明駅区営自転車等駐車場の収容台数変更","agenda":"次、(6)下神明駅区営自転車等駐車場の収容台数変更","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"この仮道路をつくる関係で、現状の駐車台数が維持できないという関係にあるのでしょうか。この撤去期間は３年間ですよね。その間約４１台を削られてしまうというのは、利用者にとっては不便なことですから、その経過を伺いたいのと、その代替についてはどのようにお考えなのか、伺いたいと思います。要するにここはわりと通勤通学で使っている方も。その経過を教えていただけますか。","respondent":"藤木交通安全担当課長","answer":"東京都のほうでいろいろ警察などと協議していく中で、若干道路の幅員などが調整になりまして、駐輪場にも引っかかってきたというふうに聞いてあります。なお、利用率につきましては先ほどご説明申し上げたとおりですので、特に大きな支障はないものと現在考えおります。","id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"利用については大きな支障はないというお話ですけれども、どうも腑に落ちないのは、初めからここに品川区は駐輪場をつくりましょうと決めたときには、引っかかるということは計画ではなかったわけですよね。どうも何か後からの計画に確かに削られてしまったというのが、その経過、もっと言うと東京都の動きが納得できないと思うんですけれども、そういうのはどうお考えなんでしょうか。","respondent":"藤木交通安全担当課長","answer":"東京都のほうからこのような要請がございましたときに、私どものほうでもどうにかならないかみたいな話はさせてはいただいているんですが、あくまでここは東京都の道路予定区域の上に品川区のほうで駐輪場を設置させてもらっているという立場ですので。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"意見","question":"初めから東京都の道路の上に駐輪場をつくったという、そのときに、とられるかもしれないというのは思えなかったのかというか、頭になかったのか。ということは、今回、減ったけれども元に戻るわけではないわけですよね。減りっぱなしなわけですよね。その辺はどうも腑に落ちないんですけれども。４１台が元に戻るのかということと、何で初めから都の道路の上につくってしまったのということを、最後に。","respondent":"松代都市計画課長","answer":"これの事業者が、ご存じのように東京都でございまして、今の仮設道路につきましては、先ほど担当課長が申しましたようにいろいろと検討してまいったようです。最終的にはここの、今、説明しているところの駐輪場に少しかかるような形の仮設道路ということになりました。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"今のお話のように、ここは一部相互交通なりますよね。そうすると、相当歩道を広くとっていますから、あそこを相互交通するのは相当狭い。歩道を削るということになるんですか。その辺をちょっとまずは伺って。どうでしょうか。","respondent":"松代都市計画課長","answer":"最終的に私どもには細かな図面できちっとしたものは、ちょっとまだ説明が来ておりませんけれども、確かに、幅員自体が決まっている中で車を相互通行されて、歩行者を通さなくてはいけないということですので。","id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"今のに関連して、直接の撤去の話と違いますけれども、この仮道路沿いに、今年の８月か９月に地域センターが先に建ちますよね。そうすると、この仮道路沿いのほうからも入る出入り口が多分設けられるという話になっていると思うので、その辺の、今、おっしゃったような通学路との兼ね合い等含めて、安全対策はしっかり東京都のほうに要望していただきたいなということで。","respondent":"松代都市計画課長","answer":"今、お話のとおり、新たな施設等の利用者の交通のルートといったものも、私どもは十分安全対策という観点から東京都と協議をしながら進めてまいりたいと思っているところです。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"駐輪場の平均利用率２２.６％というところでちょっとお伺いしたいんですけれども、ここを建てて２２.６％を、今、周りでちょっと工事をしているからというようなことなのか、当初計画でその辺のこの利用率の低さというものをどういうふうにとらえているんでしょうか。","respondent":"藤木交通安全担当課長","answer":"ただ、実際ふたをあけて供用開始してみましたら、利用率が平成２１年が３０％、平成２２年度が２５％、平成２３年中が平均２２.６％であまり高くはないということで、別に工事に伴ってというものではないと考えております。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"それは、今回ここの地域センターとか新しくできる施設でも、その施設の駐輪場もつくるんでしょうけれども、ここはそのままにするのか、２２％とか３０％の利用率では、やはり効率的な運営とは言えないと考えたときに、これからその先をどういうふうに考えていくんでしょうか。","respondent":"岩田都市環境事業部長","answer":"ここだけではなくて、がらがらの駐輪場はほかにもありますので、天王洲アイルも少し空いていますし、一番ひどいのはシーサイド、ああいうところはやはりもう自転車需要が今後見込めないのであれば、はっきりもう腹をくくって他への転用。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうふうに考えると、シーサイドもそうなんですけれども、やはりリサーチというか、それが甘かったのではないかという、今、典型的な例だとおっしゃるのは、はっきり言って失敗しましたよということだと思うんです。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-11","title":"公園における飲料自動販売機の設置","agenda":"公園における飲料自動販売機の設置","exchanges":[{"speaker":"武内委員","kind":"提案","question":"ＡＥＤが１台しかない理由というのは、今、大体ご説明でわかりました。の例えば電光掲示板でよく災害時の情報が流れますね。そういう機能はついているのか、それとも単純に自動販売機で、飲み物が提供できますよというのが売りなのかということが１つと、あと入札ではなくて提案型にしたという、その辺の理由についてお聞かせください。","respondent":"稲田道路公園課長","answer":"入札方式ではなくて提案方式としましたのは、このような事業におきましては、ほかのところもあまりやっていないようなところもありまして、いろいろな提案を聞いて、よりよいものを決めていきたいということがございましたので、提案方式で業者からいろいろ聞きまして。","id":"exchange-061"},{"speaker":"武内委員","kind":"提案","question":"その４社の中で、今、やはりどうしてもＡＥＤというのは、そういう事務所とかそういう管理体制がある程度あるもとでないと、なかなかできないという考え方はまだ変わっていないんでしょうか。そういう提案があったところはあったんでしょうか。","respondent":"稲田道路公園課長","answer":"４社とも、やはり屋根つきで温度や風雨等に影響されないところというふうに申しておりました。","id":"exchange-062"},{"speaker":"大沢委員","kind":"質問","question":"他自治体でも自動販売機の横に使用済みの缶を収集するためのごみ箱を設置するやの条例もちょっと出ているというようなことの話を聞いたんですけれども、この２０台についてはどのような形で、要は飲んでしまった後のごみ箱はその横に置くんでしょうか。それとも勝手にどこか公園内に捨ててくださいとか、どういうスタンスでこれを考えていますか。","respondent":"稲田道路公園課長","answer":"これは自動販売機の横に必ず回収ボックスを設置するように要綱それから協定等でうたって、必ず設置させていくと。これがあふれたりしないように常に監視して、常時使用可能な状態にしてくださいとか、そういう条件等も一緒にしております。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問","question":"すみません。ちょっと勉強不足で、これは条例ができているんですか。","respondent":"稲田道路公園課長","answer":"あります。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"事業の開始のところで、「福島第一原発の事故による電力不足の動向を慎重に見定める」ということで、現在電力不足は夏場から、今、改善したという状況ではなくて、引き続き同じような状況だと思うんですけれども、それでなぜ今なのかと。これから来年度に向けて同じような状況があるということで、何ら変わっているという認識はないんですけれども、それについてどのようにお考えでしょうか。","respondent":"稲田道路公園課長","answer":"確かにそのことに注意していくというところで今回も考えておりまして、提案の中でお聞きしました節電対策を十分に実施する機械であるとか、またその辺も考えていくというようなことも言われておりまして、節電ももちろん大切です。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"災害時に４８時間の稼働とか、帰宅困難のああいう事例を見れば、公園を通るかどうかわかりませんけれども、総合体育館とかでも１回イベントがあったらすぐなくなるくらいで、本当に提供ができるのかというのは、一斉に使ったら、あまりそれほど効果があるというふうには思えないと思いますので、別に税収入を探すというところも必要だとは思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"大沢委員","kind":"確認","question":"１つだけ確認で、飲んでしまったもののごみ箱の件なんですが、これは、ごみ箱を置くという内容の条例なんでしょうか。","respondent":"岩田都市環境事業部長","answer":"今、ちょっと手元に条例がありませんが、罰則も何もありませんので、町場のたばこ屋の横にあるような自動販売機のところにはないところが多いということですけれども、今回は公共機関がやりますので、当然のことながらきちんと義務づけているわけです。","id":"exchange-067"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"まとめて言いますが、今、ごみ箱の話がありましたけれども、ちょっと心配するのは、やはり家庭ごみであったり、もっと言うと公園内でいろいろ使ったごみは本来持って帰らなくてはいけないんだけれども、特にお花見の時期も含めて、やはりごみ箱というのは置くのはいいんですが、管理とか維持とか清掃というのはなかなかこれはこれで大変だなと思っているんですけれども。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"公園を貸すということで、その時の料金はどうかということなんですが、一般的に土地の使用料で徴収するんですが。管理を許可する、設置を許可するという都市公園法の手続きと別の、もう一つ契約書を結んで、２本立てでやるということです。それから協定は１年なんですけれども、５年間のスパンでこのジャパンビバレッジ東京と考えております。それからその辺の清掃ですね。","id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ということは契約は５年なので、５年たったらまた一から業者の選定をやっていくという考えなのかということと、清掃のほうはこのジャパンビバレッジ東京がやるんだと。ついでに伺えると、飲み物の種類というのはだれが決めるんでしょうか。別にそれが契約の中に含まれているのか、ぜひ利用者に沿った中身になったらとは思うんですが、何のジュースを置くのかというのはだれがどう決めるんですか。","respondent":"稲田道路公園課長","answer":"自動販売機の業者は実績もございまして、一番どういう商品が売れるか、売れる商品を持ってくるのが事業者でございまして、そういう中でジャパンビバレッジ東京は各種多様な商品を取り扱っているというのも提案の一つでございました。","id":"exchange-069"}]},{"id":"topic-12","title":"宮城県女川町災害廃棄物の清掃工場での受入れ","agenda":"宮城県女川町災害廃棄物の清掃工場での受入れ","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この受入量なんですけれども、清掃工場で焼却をするときに普通のごみと混ぜて燃やすということになっていると思うんですけれども、その１５０ｔというのは純粋にそちらの量なのかどうか、ちょっと教えてください。","respondent":"太田品川区清掃事務所長","answer":"試験焼却のときは、一般の家庭ごみと災害廃棄物の混載物を石巻のクリーンセンターで９月に試験焼却をやったときと同条件で、２０％ということで実施いたしましたが、３月以降の本格受け入れに当たってはより安全性を確保するということで。","id":"exchange-070"},{"speaker":"大西委員","kind":"質問","question":"今の住民説明会のほうですけれども、住民の方々から主に出ている質問というのはどんなことだったかということと、それに対する答えはどのような内容だったんでしょうか。目ぼしいものだけ教えてください。","respondent":"太田品川区清掃事務所長","answer":"東京都のほうでは、焼却灰については国の処理基準にのっとって、灰をやった上にさらに５０cmくらい土で覆って、焼却灰、土を覆ってという管理の仕方をしていますよということと、最終処分場においても空間の線量を定期的に計測をしているというような説明をしています。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/274500?Template=document&Id=4030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":61037,"voices":262}},{"id":"h24-20120227-9","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"文教委員会","time":"午前１０時００分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件抜き出しています。","topics":[{"id":"topic-01","title":"の第３９号議案 品川区立学校施設使用条例の一部を改正する条例","agenda":"の第３９号議案 品川区立学校施設使用条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"３のところなんですけれども、第一グラウンドと第二グラウンドの使用できる曜日・時間帯・団体と書いてありますけれども、学校施設なので、支障のないときに貸し出すということで、学校の授業状況を知りたいんですが、部活は６時半くらいに終わると伺っているんですけれども、学校にお伺いしたいんですが、日曜日とか祝日とか休日に、学校でどのぐらいの頻度で使っているのか、まず１つは。","respondent":"齋藤庶務課長","answer":"委員がおっしゃったとおり、グラウンドの部活につきましては、授業終了後６時半で終了、７時までに必ずあける。土曜日は１日やっております。1)と2)の部分は必ず使うということで設定しています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川に限らずというか、どっちかというと、学校全体のところで、土曜日は昼間、1)と2)を使える。日曜とか祝日は、学校では全く使っていないので貸し出すということなんですか。大もとの基本のところを教えていただきたい。","respondent":"小林青少年育成課長","answer":"日曜・祝日等に限ってのことですけれども、品川学園の校庭について、その取得を含めた現状、広さ等の特殊性から、今ご説明がございましたように、地域に開放していくですので、地域使用、あるいは学校の使用と特殊な例を除いて、原則的には地域開放の対象としている。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"品川学園の場合は、特殊な例を除いては、地域に開放している。ほかの学校で、部活とかですごく活発なところは、よく日曜日・祝日も校庭を使っているような、あんまりはっきりしないんですけれども、その辺の違いがあるのかどうか、基本的な学校の校庭の使い方で、休日とか祝日・日曜がどうなっているのかを、そこの大もとを聞きたかったんですけれども。","respondent":"冠木指導課長","answer":"学校は当然ここの土日については、部活の子がどうしても使いたいときはあろうかと思いますので、そういった場合については、事前に十分調整をした上で、開放のほうと調整しているということになると思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"確認","question":"しつこいようなんですけれども、基本的なところなんです。だから、学校で児童・生徒が使う場合で、部活で使いたいとか、そういうところが特別採用されるわけではない。調節はきちんとして、品川学園だけが一般開放することで、学校に支障があるということはないという受けとめでいいんでしょうか。ちょっと基本的なところなので、そこのところを確認したいと思いますが、いかがでしょうか。","respondent":"小林青少年育成課長","answer":"一般的にスポーツ開放の取り扱いについては、先ほどご説明したとおりですが、品川学園につきましては、同じ少年少女スポーツ団体に開放するものではありますが、特殊な事情を抱えている。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺の利用料がどうなっているのか教えていただきたいのが１つと、あと５の使用調整のところなんですが、少年少女スポーツ団体への開放は、少年野球連盟と少年サッカー連盟が主ということで、でも、ここのところ、団体がどのくらい利用する、連盟の中でどのくらい団体があるのか、わかったら、教えていただきたいのと、(2)の地域スポーツクラブ、スポクラ・しながわは２年くらいたっていて。","respondent":"安藤文化スポーツ振興課長、小林青少年育成課長","answer":"ですから、一応この枠の中では設定させていただきました。そして、使用料ですが、先ほどご説明しました、校庭にはダスト、土の校庭と全天候型があります。そして、全天候型につきましては、グラウンド使用料は１,６００円です。団体育成におきましては、品川区少年野球連盟および品川区少年サッカー連盟がその育成の任を担ってくださっていますので、この校庭の使用につきましては、一括、両団体に使用を許可し、使用承認し、内部の調整に当たり。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"スポクラ・しながわをインターネットで開いたら、５ブロックで、それぞれの学校のところで見ているんですが、ブロックでないところとか、学校で調整するのに担当できないようなところがあるんでしょうか。ちょっとその辺、私は荏原なんですけれども、必ずどこの地域にもスポクラ・しながわができているのかどうか、そこをちょっとお伺いしたい。","respondent":"安藤文化スポーツ振興課長","answer":"今の学校の調整ですけれども、品川大崎については、先ほど言った２年前に総合型スポーツクラブということで、スポクラ・しながわという組織が調整しております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"最後、調整会議が終わった後の窓口というのは、どこになるんでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"とりあえずすべての学校で調整会議の場で調整します。その後は、直接学校に行って、あいているところを学校に申請するという形になっています。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"日野学園は１面当たり１,６００円と数字になっていたけれども、この辺の差はどういうふうにとってもらえばいいのかというのが１点。そうすると、民間へ、サッカーの何だのというところに貸し出す絵を、授業に関係なく使えるという形にしたほうが、まちの人は使い勝手がいいのではないかと思うんだけれども、その２点、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長、齋藤庶務課長","answer":"私から１点目の料金の表についてご説明します。この新旧対照表ですが、新の別表第１のところで、(2)のすぐ、屋内運動場等と書いています。グラウンドの広さのことですが、学校としては、1)2)の第一グラウンドだけではなく、第二グラウンドもぜひ使いたいです。","id":"exchange-008"},{"speaker":"木村委員","kind":"質問","question":"何か少し覆すようなことで申しわけないんですが、会派でいろいろ話をしたときに出たんですが、学校の子どもたちは、ふだん土曜とか、休日に遊ぶ場所がほかのところにあればいいんですが、学校側がオーケーであれば、4)のところを貸し出す、開放するということですけれども、地域の子どもたちが今どのような遊びをしているのか、よくわかりませんけれども、本来ならば、そういう子どもたちのために。","respondent":"齋藤庶務課長","answer":"先ほど申し上げたとおり、品川学園は、説明がありましたように、多くの学校は校庭の面積は３,０００平方メートルから４,０００平方メートルのところが多く、平日は大変充実した施設の利用ができるということで、広く区民、品川区のお子さんたちに。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"小さいことなんですけれども、トイレなんですが、地図のここのところで、誰でもトイレ、なにか中止に見えるんですけれども、トイレに関しては、学校の１カ所を皆さんが使えるということでしょうか。それを１つだけお伺いしたい。","respondent":"齋藤庶務課長","answer":"ご指摘は倉庫・トイレ棟でしょうか。これは地域開放の方のためにも使えるというトイレです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"確認","question":"少年少女スポーツ団体にかかわるところなんですが、今の木村委員の質問で、品川学園校庭少年少女スポーツ開放、ここのところで、今までＰＴＡにお願いしていた校庭開放は、当然そのまま残ると思っていたんですが、今のご答弁だと、ＰＴＡにお願いしていた校庭開放は、平日充実しているので、地域に開放するということですか、そこのところをもう一回確認したい。","respondent":"齋藤庶務課長","answer":"少年少女スポーツ団体の方たちが使うので、ＰＴＡの方たちにお願いして、校庭開放をやる予定はございません。","id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"ちょっと確認なんですけれども、もし、聞き漏らしていたらすみません。土曜日に部活等で使用するということで、１、２、３番とも、基本的に土曜日は、逆に少年少女スポーツ団体の開放はなしと考えていいんですか。要は、第１・第３土曜日は午前中授業をやって、午後もばっちり部活、要するに、平日という感じのとらえ方で、第２・第４土曜日に関しては、どういうとらえ方を今考えられているのか。","respondent":"齋藤庶務課長、小林青少年育成課長","answer":"今のご指摘は、多分、第１と第３土曜日は、授業のときは、午前中はいつもと全く同じ使い方になります。ちょっと確認しますけれども、日曜・祝日・休日につきましては、第一グラウンドは使うわけですけれども、逆に土曜日については、第二グラウンドのみ終日、ただし、授業の日は、今ご説明のあったとおりですけれども、学校のほうで。","id":"exchange-012"},{"speaker":"渡部委員","kind":"意見","question":"もうちょっと具体的にといいますか、第１・第３土曜日の１時以降、どういう扱いになりますかというところ、それと第２・第４土曜日、例えば、部活等が、とっていいですという言い方は変ですけれども、ある程度学校側に意思を持たせて、もしくは日曜日と第２・第４土曜日というのは、もうある程度地域活動ができますというような考えでなさっているのか、全面。","respondent":"小林青少年育成課長","answer":"それで、第１・第３土曜日、授業が行われる日については、第二グラウンドも午前中は学校使用、午後は授業がなくなりますので、ここは原則どおり、少年少女スポーツ団体で使用するということです。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"自分の中で整理して、違ったら違うで教えてください。第２・第４土曜日というのは授業がありません。日曜日と同じ扱いなのかどうなのか、だけれども、部活をやるから、第一グラウンドは何時から何時まで実は学校が使いますみたいな規定があるのか、もしくは、今の段階では、地域活動で第２・第４土曜日は使いますというイメージなのか、そこがちょっとわからないんですけれども。","respondent":"齋藤庶務課長","answer":"第１・第３土曜日も部活で使います。土曜日は使います。3)の第二グラウンドは、土曜日だけお貸しします。午前中は授業で使いますから、今までは午前・午後お貸しするという予定だったんですけれども、授業がある関係で、午後しかお貸ししませんということです。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"わかりました。では、第１・第３土曜日に関しては、地域開放があるのは、第二グラウンドの午後だよ、第２・第４土曜日に関しては、地域開放があるのは、第二グラウンドが終日、第一グラウンドは貸さないというところでよろしいでしょうか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"の第４０号議案 品川区幼稚園条例の一部を改正する条例","agenda":"の第４０号議案 品川区幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今回この３つのモデル実施ということでの中身の変更ですね。ちょっと伺いたいのは、給食の関係で、新たに６００円ができたということなんですけれども、第一日野幼稚園の幼稚園と台場幼稚園は６００円に該当するということですよね。北品川のすこやか園の御殿山幼稚園はどうなっているのか、幼保一体のところで違いができている中身を具体的に教えてください。","respondent":"吉岡保育課長","answer":"第一日野幼稚園、台場幼稚園は、いわゆる幼保一体施設ではありますけれども、こちらは平成２２年度に待機児対策ということで、今まで０歳から３歳の保育園、プラス４、５歳の幼稚園という年齢区分型の幼保一体施設でありましたものを、保育園も０歳から５歳までの。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、年齢区分型のところであれば、４、５歳でも給食が提供できる。この辺は、選択性なんですか。お弁当がいいという方はお弁当なのか、その辺、あまりよくわからないので、教えていただきたいのと、おやつのところ、市販のものと書いてありますけれども、この部分においては、預かり保育をやっているところはどこも同じなんですか、そこのところ、おやつは幾らぐらいなんですか。","respondent":"吉岡保育課長","answer":"こちらは、値段が幾らと、毎回同じ値段でそろえてはございませんけれども、１００円から２００円の間、１００円前後ぐらいかなと考えております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"今伺ったら、給食が出ているところは皆さん給食ということで、お仕事をしながら、０歳、１歳、２歳、３歳でお預けになって、幼保で幼稚園ですよと言われても、やはりお仕事をしていたら、給食のほうがいいなと私なんかも思いますけれども、キャパシティーの問題という段階なので、就労支援という部分もあるので、今後においては何とか給食の検討は必要であると思います。これは意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"平成２４年陳情第４号 保護者夜勤時の子どもショートステイ利用に関する陳情","agenda":"平成２４年陳情第４号 保護者夜勤時の子どもショートステイ利用に関する陳情","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"今、理事者からの説明の中で、当区のショートステイの状況の中で、突発的ということを伺ったんですけれども、仕事の出張の場合は認められるということなんですが、その場合は、証明書みたいなものを出すということなのかどうかということと、ちょっとまとめてほしい。それをちょっとお聞きしたいと思います。","respondent":"安井子育て支援課長","answer":"出張の場合につきましては、事業所から証明書をいただくという形で確認しています。それから、ほとんどと申し上げて、申しわけございませんけれども、私が調べました限りでは、定期的なものは認めておりません。そういったことで、全部という形になります。","id":"exchange-019"},{"speaker":"阿久津委員","kind":"質問","question":"ですから、そういうこともちょっと考えられるのではないかと考えているんですけれども、そういうお考えが、そういう利用法があるかどうか、ニーズがあるから、そういう供給も必要だと思うんですけれども、それについてちょっと伺えればと思います。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"確かにニーズはあるとは思うんですけれども、夜まで１泊というような形での保育のニーズというのは極めて限られていて、夜型も、セキュリティーであるとか、先ほど新宿の話については、そういうことが多いということなのですけれども。保育ママとの関連で、夜間の保育ママを希望されている方もいらっしゃるので、可能だろうかということだと思うんですけれども、現在、保育ママにつきましては、いわゆる認可保育園の補完的な機能を果たして。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"夜間とか、宿泊が必要なケースに対して、区はどういった考えを持っていらっしゃるのかということを１つお伺いしたいのと、現在ショートステイは実施されているわけですけれども、読んでみると、スタートが在宅支援で、就労支援ではないというところにおいては、さっきのご説明だと、今の状況では就労まで支えられないというところなんですけれども、私は本陳情からすると。","respondent":"安井子育て支援課長","answer":"そういった形で、現在の段階では、一般的にどこもそうなんですけれども、ショートステイというものについて、そもそも就労支援に切りかえるというようなことは考えていないというところになっております。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"意見","question":"かなり厳しく、何でも同等にやれないと、仕事が続けられないという状況、厳しさの中に、特にこういった母子家庭の方なんかも置かれているので、支援が大事であると思うんですけれども、その辺、２４時間保育をやれというわけではないですけれども、何らかの対策がないと、どうにもならないといった現状をどう受けとめているのか、ちょっともう一回そこを聞かせてください。","respondent":"金子子ども未来事業部長","answer":"その中でも、確かに２４時間保育というのは検討の一つとして考えていたことはあります。現在の社会状況の中で、それを私ども品川区として、区として実施することがどうかと、社会情勢と絶えず照らし合わせながら考えてきているところがあります。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現在のショートステイの拡大、さっきのご答弁からすると、量的な問題、可床数を増やしていくとか、内容をちょっと拡大していけば、現制度でやっていけるのではないかという感触を私は受けたんですけれども、いかがでしょうか。今、子どものショートステイがあるので、ここをぜひ拡大して、受けとめていただきたいと思うんですが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、先ほども申しましたとおり、社会情勢との関係がありますが、こういうものと照らし合わせながら、なおかつ公的な保育として提供すべきものなのかどうか、慎重に検討していく必要があると考えています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この方が学校を出て、特に新卒の看護師が日勤と夜勤両方でいろいろな経験をして磨いていくことが大事、初めの段階でそれが十分できなくて、お子さんを育てた後に取り戻せるのかなと、私はここの１行を読んでいて、学校を出た後の最初のところがすごく重要であるという思いで受けとめたので、ここを何とか支えることができないのかなという受けとめ方をしたんですけれども、子どもにとっての影響。","respondent":"金子子ども未来事業部長","answer":"現在の段階では、私どもとしては、先ほど申しましたとおり、一時的、臨時的なものを除いて、実施する考えはありませんけれども、時間はかかるかもしれませんが、慎重に検討していく必要はあるかなとは思っております。","id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"先ほどの説明で、他の自治体で、港区も聞いてみたけれども、消極的にちょっと違うというお話をいただいたんだけれども、港区、目黒区、葛飾区、荒川区とやっていますという区があるんだけれども、このやっていますというのは、どのあたりをどういうふうに、ちゃんとショートステイの形の仕組みをこの区はやっていらっしゃるんですか。","respondent":"安井子育て支援課長","answer":"まして、葛飾区では、制度を当て込んで、夜勤の仕事を探すのは、基本的には認めていませんというお話とか、仕事の定期的な夜勤などというのは、原則対象外であると、荒川区とか、それぞれのセクションで確認していますので、インターネットとかで。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"そういう承諾を得て、子どもを産みますというような、病院なんかでもそういう話を伺っているので、そういうところでお産をされて、お子さんのうちはという仕組みで、現時点ではいくべきだろうと思うので、これでは困るから、そっちのほうを改革しなさいというのはちょっと違ってくるので、社会情勢が、みんなでお子さんを育てようという仕組みがあれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問・要望","question":"これからいろいろな就業形態が出る中で、例えば、この医療業務、これから大変盛んになるといいますか、労力を必要とするところだと思うんですけれども、実際病床を持っているような病院、大型の病院ですとか、臨床をやったりするような病院は、相当大きい事業所だと思うんですけれども、例えば、事業所内保育を区として積極的に働きかけるとか、現に持たれている病院があるのかどうなのか、その辺がわかれば。","respondent":"安井子育て支援課長","answer":"そういう形で、看護師を確保したいということだろうと思うんですけれども、そういうところは、転職の情報サイトで、９００件とか、ぱあっといろいろな形で、それは日本全国だとは思いますけれども、そういったものが出てきているというのは。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区は、ほかの所管になりますけれども、そのようなサービスも始めてきていますので、積極的に働きかけていただきたいと思います。一つ一つの業種ごとに見ていきますと、業種の比較といいますか、この業種だから、あの業種だからというところでは、行政としてやっていいのか、これはやってはならないことだと僕は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、これを受講したい人も、では、そういう職場があるのなら、仕事を一生懸命やって子どもを育てて、安心して両方できると思うので、この先を連絡しておいてあげていただきたいというのを、ひとつお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"浅野委員長","kind":"質問","question":"私から質問なんですけれども、今回このような陳情が出てきましたけれども、過去において、２４時間ですとか、特異なケースというんでしょうか、今まで区があまり、まあ、検討はされているんでしょうけれども、予想もつかなかったようなこういう陳情というのは、過去に出たことがあるのかどうか、２４時間はいろいろ考えた経緯はあると伺っていますけれども、もし、前例があって、また、やっていないけれども。","respondent":"吉岡保育課長","answer":"私の経験の中では、２４時間保育について直接実施を要望されたという記憶はないんですけれども、さまざまな就労形態の方がいらっしゃいますので、中にはそういう希望を持っていらっしゃる方もいらっしゃるかとは思うんですが。","id":"exchange-030"},{"speaker":"須藤委員","kind":"意見","question":"私も先ほどお話ししたとおりなので、採択はなかなかとり切れないよと。ただ、今言ったように、連携先を担当先がお伝えしておいていただいて、いろいろな懸念があるだろうと思うので、それとうまく連携をとってあげて、品川区でお子さんを育てていくような仕組みをしっかり考えてあげたいと思っています。よろしくお願いします。この陳情については不採択。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"阿久津委員","kind":"意見","question":"先ほど、ほかの委員からも、るるお話がありましたけれども、本当に単純な不採択よりは、お子様の成長に与える影響があることはもちろんですが、区で、行政で、しっかり社会情勢を受けとめていただいて、先ほど私からも保育ママの制度について、関心のある保育士がいらっしゃるというお話を参考にさせていただきましたけれども、研究調査、また前向きに考えていただくことを前提に、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"ただし、この陳情者もまだ来年卒業ということなんですけれども、今すぐ結果を出すということは、私は反対だったものですから、継続にしたわけですけれども、これからまたあらゆるパターンの方々も出てくると思います。そういうことを考えまして、この方の一生懸命やろうとする姿、会派としてはこれを採択という形にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"どのような形で世の中が動いていくかわからないので、何か一つやるにしても、さまざまな方がいるわけですから、この一個人の方というよりも、多くの区民の皆様にとってどのようなことがいいのかというのを、区はしっかり考えていかなければいけないんだと思います。時間がかかるかもしれませんが、研究を続けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"共産党としては、社会が今厳しい状況になっている中で、女性の就労を支えていく施策の拡充が大事であると思っています。今日のやりとりの中でも、ショートステイという制度があるので、キャパシティーの問題であると思うので、努力して、ぜひ拡大していって、早急に対策をとるべきことと思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"３歳のお子さんがいらっしゃると、この時期というのは、お子さんは親御さんの手で育てていただけたらという願望もありますけれども、親御さんの気持ちも考えますと、これから一生懸命働こうということを考えますと、行政側も少し長い目でかもしれませんが、こういう方々のためにも、ショートステイを考えていったらいいなと私は思います。","respondent":"浅野委員長","answer":"平成２４年陳情第４号保護者夜勤時の子どもショートステイ利用に関する陳情を採決していきたいと思います。本件は挙手により採決を行います。本件を採択することに賛成の方は挙手願います。","id":"exchange-036"}]},{"id":"topic-04","title":"平成２４年陳情第７号 戸越台中学校優先入学に関する陳情","agenda":"平成２４年陳情第７号 戸越台中学校優先入学に関する陳情","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今まで陳情として来たのは、いわゆる、抽選に外れたという話になっていたんだけれども、今年はちょっと伺うと、お子さんを私学に入れる数が少なくなっていると、震災の後なのでという状況なんだけれども、今までこういう話があったのか、それともいろいろな課題があったので、今年こういう問題が生じてきたのか、クラスも３５人学級制とか、形もいろいろ変わってきていますよね。","respondent":"和氣学務課長","answer":"まだ最終結果ではないので、何とも結論は出せませんけれども、そんな状況と、あと小学校は３５人学級になったということで、中学校は東京では３７人ということで規定がありますので、全体に受け入れ枠がどうしても減ってしまったということもありまして、その両方の相乗で。","id":"exchange-037"},{"speaker":"須藤委員","kind":"意見","question":"そのためには、我々としてももう少し資料をもらいたいなと思っているので、まず１つは、さっき学区域を取り入れたらわかりにくくなるというお話があって、こちらはこう出ているんだけれども、１つは、京陽小学校だけではなくて、ほかでもそういう状況があるのかどうかという点を資料にして、次回までにまとめてもらいたいのと、先ほどお話があったように、兄弟。","respondent":"和氣学務課長","answer":"そういう意味で、そういった資料につきましては、また改めて次回にご提出させていただきたいと考えています。","id":"exchange-038"},{"speaker":"阿久津委員","kind":"質問","question":"最初の学務課長からのご説明の中で、本区としての施設分離型連携校ということで説明が、こういう考え方でという図面があったと思うんですけれども、こういう考え方というのは、まずそもそも入学する前に、小学校に入学する前、小学校を選ぶ前に保護者に説明する機会があったのかどうか、また、入学してから、通常は、普通は自分で調べてわかるかもしれませんけれども、連携校だから。","respondent":"和氣学務課長","answer":"説明の際、基本的に必ず行けるわけではないという話はしているのと、例えば、ここの資料にもありますけれども、３校と連携していれば、必ずしもその中学校の学区ではないということもあります。","id":"exchange-039"},{"speaker":"阿久津委員","kind":"質問","question":"今ご答弁いただいたとおり、多分今までも問い合わせとか、疑問等はたくさんあったと思うんですけれども、先ほどご説明の中で、今後品川区もいろいろお考えがあるようなんですが、議会でももちろんこの問題は取り上げていきますけれども、一定の考えみたいなものは、大体どのくらいまで考えられているのかを伺います。","respondent":"和氣学務課長","answer":"反映するとすれば、夏前までには結論を出さないと、次の学校選択に反映できませんので、ただ、どの程度、制度も含めまして、先ほど申し上げたとおり、大変深い中身がありますので、直ちにどうということはございませんが。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"本陳情は今、品川区が進めています学校選択制と連携のあり方の矛盾が本当にはっきり出たんだなと思って、受けとめています。このきれいな図を出していただいたので、読み方を教えていただきたいんですけれども、まず、４色に分けられていますけれども、これは小学校の学区ですよね。この厳しさをこれからどう改善するのかなと思うんですけれども、連携校の学校の選び方とか、基本的な考え方も教えてください。","respondent":"和氣学務課長","answer":"連携校ですが、これは実際小中一貫教育が始まった時点で、各学校がまさに自主的にそれぞれ好きな学校を決めていただいて、進学者が多いとか、いろいろありますけれども、先ほど言ったように、どうしても１対１にはなりようがありませんので。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"この連携校の問題点、矛盾が出たのは、それぞれの学校の責任ということなんですか。だから、そういったことでは、早急に対策をとらなければいけないし、さっきちょっとほっとしたのは、戸越台中学校は全員が繰り上がったということなので、あきらめてしまったお子さんはいないんでしょうか。起こった後で改善しますではいけないと思うんですが、そこの大もとのところはいかがでしょうか。","respondent":"和氣学務課長","answer":"といいますのは、いろいろな形の連携をしながら、子どもたち全体が９年間というスパンで、品川区の中でどう育っていくかということを考えているわけで、そのことはあらかじめわかった上でということでございまして、そういう説明をさせていただいてきたところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"この間、ずっと同じ答弁ばっかりなんですけれども、答えていないから、同じ質問を繰り返しているんです。今の答弁で、区民の方が納得するかどうか、私はそこであると思うんです。次の質問をしますけれども、連携校がありながら、その連携校に行かれないというところで、連携校の意味がどこにあるんだというところを改めてお伺いしたいと思います。","respondent":"和氣学務課長","answer":"それで、新しいカリキュラムで、品川区全体の小学校、中学校でいろいろな教育を展開していって、質の高い教育を、品川区全域の子どもたちにどれだけちゃんとそういう環境をつくっていくかということでやっているものですので、委員の指摘には当たらないと考えています。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日示していただいたタイプ別の地図を見ると、かなり距離が遠い学校が多いですよね。どのくらいの距離があるかわかっていたら、最長のところはどのくらい距離が離れているのか、教えていただきたい、そこを１個お伺いしたいと思います。本当にこれから見直すというところなんですけれども、早急に見直していただかないと、問題がいっぱいあると思うんですけれども、距離的な問題を教えてください。","respondent":"和氣学務課長","answer":"学区との距離でどこが一番遠いのかとは考えてございません。何よりも、学校の配置を変えない限り、距離の問題は解決しませんので、既存の学校がどう連携するというかという問題ですので、その距離を云々されても、ちょっと解決しようがない問題であると考えています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これから第４ステージで検討されるということは、もちろん検討してもらわないと困るわけですけれども、本当に距離をはかっていないんですか。小学校と中学校の先生が行ったり来たりして、子どもも行ったり来たりして、より効果的にと言っておきながら、距離をはかっていないんですか。質問をしなければいけないんですが、でも、今の答弁はひど過ぎますよ。私は怒っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問に入る前に１つ確認させていただきたいのが、この際、小学校のことは置いておいて、一体型の小中一貫校の小学校６年生から中学校の７年生に上がるとき、例えば、仮に日野学園の６年生で、学区域にいらっしゃらないお子さんが、日野学園の７年生に無条件で進学できるんでしたっけ。そこだけ１つ確認させてください。","respondent":"和氣学務課長","answer":"日野中学校の学区域であれば、無条件で。","id":"exchange-046"},{"speaker":"渡部委員","kind":"意見","question":"すみません、聞き方が悪かったですね。日野学園でも、伊藤学園でも、例えば、何らかの選択制で日野中学校の学区域でないお子さんが、小学校に選択制を利用して入られていた場合、無条件で中学校に行けているのか、行けていないのか。","respondent":"和氣学務課長","answer":"一貫校の小学校に在籍している方は、全員無条件で行けます。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"今まで調べていましても、実はその仕組みはないですね。ですから、今後品川区が小中一貫教育を推進していく、これからまた第４ステージに向けて、こういう組み合わせでいくんだ、こういう形でいくんだというビジョンが、来年以降若干出てくるんだとすれば、それに合わせた制度設計、制度というのは、よりいいものに直してしかるべきものだと思います。どのような形になっていくかわからない。","respondent":"和氣学務課長","answer":"連携につきましても、やはりこれまでやっている組み合わせの変わり方もあると思うんですが、どういう形を敷いていくかと考えております。そういうものも含めまして、さまざまな保護者と子どもたちの希望がどうかなえられるかという観点で検討させていただきたいと考えております。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当にこの陳情に対して採択という気持ちはあるんです。ただ、今採択したから、今直せる、これはもう物理的に無理です。ただ、そのような中で、少しでも変えられるところ、見直せるところで、いい形にもっていけるのであれば、手をつけられると言ったら変なんですけれども、今、見直しを始めていただきたいなという思いがありますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須藤委員","kind":"意見","question":"さっき資料を要求しましたけれども、この件は京陽小学校と戸越台中学校だけではないと思いますので、１回区の実態を見させていただいて、先ほどからいい知恵を行政からやるというのではなくて、逆に僕らが行政に、我々は区民の代表はこう思っているんだと伝えていかなければいけない使命があると思うので、それを一緒になって議論しながら、この問題について対処していきたいと思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"渡部委員","kind":"意見","question":"プラン２１が成熟期に入る中で、いい方向に制度改定はしていくべきだと思います。やはり前向きに継続をしていって、話を続けたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"吉田委員","kind":"意見","question":"私は継続で、子どもたちのために大いに議論していくべきだと思いますので、継続でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"保育園の待機児童対策について、公明党の武内議員の代表質問と、一般質問の無所属の藤原議員の質問に関連して、特に武内議員のところでは、今後の待機児対策について、認可外との連携、基準の見直しを図るというような答弁、書きとりなのではっきりしないんですけれども、その辺の問題と、藤原議員は、財政的なことも含めて今後の見通しについての答弁をもうちょっと深めていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/852886?Template=document&Id=4752#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":37818,"voices":159}},{"id":"h24-20120227-5","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"総務委員会","time":"午前１０時００分～午後０時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","topics":[{"id":"topic-01","title":"の第１０号議案、品川区職員定数条例の一部を改正する条例","agenda":"の第１０号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"清掃は先ほど説明がありましたけれども、この８名減というのはすべて粗大ごみの収集、運搬にかかわる作業だけなのか、現状をちょっと改めて、現状がどうなっていて委託になるというふうになるのか、その辺を教えていただきたいと思います。","respondent":"堀越人事課長","answer":"それから用務についてですが、１校１名の定数という形にしておりますので、そういった考え方から７名の定数減をしたということで、どの学校で減という形ではなく、全体の中での定数減をしたということで考えているところです。","id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"保育園の、この１０年間でもいいんですけれども何人減になっているのか、そこが知りたいところです。もう一度です。この東京も、首都直下型地震を含めて東南海とか南海とか大きな災害が短期の間に予想されるという状況の中で、これだけの減員をして、さらに２６名の減員をするわけですけれども、そういう防災対策上は大丈夫と見込んでこういう判断をされたのか、その辺のことを伺いたいと思います。","respondent":"堀越人事課長","answer":"保育園ですが、先ほどご説明いたしましたとおり定数は１３名増という形にしております。保育園の定数は６３０名で、そこについては増やしてきているということで、平成２２年度についても約９０名ほど採用したということで、今年度も約６０名の採用を予定しています。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"保育園のところでいうと、現在が６３０名だというご紹介でしたけれども、それはそれとして伺っておきたいと思いますが、１０年前から比べて何人減って、それで今年度６０名採用してトータルで６３０人という数なのかというのを認識したいので、減らしてきている数も含めて教えていただきたいと思います。それから児童センターも伺ったんですけれども、教えていただきたいと思います。","respondent":"堀越人事課長","answer":"減らしてきている数ということですが、保育士につきましては先ほども説明したとおり増やしてきておりますので。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"そして図書館についても何人いるのか、児童センターについても何人いるのか、その３つの職場でいいですから、教えていただきたいと思います。それから防災の関係で今の課長のご答弁では、非常勤の方々の災害時の使い方については、そういった中でというふうなことはおっしゃったけれど、明確に状況がわからないままで終わってしまったんですけれども、もう一度その点について伺っておきたいと思います。","respondent":"堀越人事課長","answer":"当然のことながら、我々職員が中心になってやっていくというふうに認識をしています。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"質疑に必要な、賛成したほうがいいのか、反対すべきなのかという判断をするに当たって質問をしているわけですので、できるだけ数字というのは準備をしていただきたいと思っています。ぜひ具体的な数字を教えていただきたいと思います。","respondent":"堀越人事課長","answer":"ちょっと今、記憶が定かではないのですが、保育園につきましては先ほど言いましたさまざまな形態がありますけれども、保育園だけの非常勤という形でいうと大体５００名ぐらい、年間の頭数だけを数えたところ５００名ぐらいだと記憶しております。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"必要だということで採用しているわけですよね。しかも災害が起きたときには、すべての子どもの命を守るということが求められているわけですね。当然、日常業務以外の業務をこの非常勤やそういう方々にもしていただかないと、子どもの命は守れないということになるわけですから、そういうところも含めて雇用しているのかどうかということを、最後に確認したいと思います。","respondent":"堀越人事課長","answer":"今後のいろいろな活用の仕方については、防災の位置づけの中でどのような形でやっていくかということになると思いますが、基本的には正規職員のほうでしっかりと対応していくという形になろうかと考えています。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"ただちょっとお聞きしたいのは、品川区は人口がそんなに減っているわけでもなく、ここのところ何年か増えてきている中で、職員をこういうふうに減らすことによって、区民サービスとか区民の利便性に関して大丈夫なのかなということで、その点についてお話しください。それは問題ないんでしょうか。","respondent":"堀越人事課長","answer":"それから職員に対して負荷がかかるかどうかですが、工夫を図る中で、年間を通して残業はある程度やらざるを得ないというふうに考えておりますが、全体的にはいろいろな工夫を図りながら効率的にやっていくということですので。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"本当にご努力は敬意を表しますが、どうか職員、管理職の皆さんに負荷があまりかからないように、それで区民のほうにもっと積極的に、今以上に区民サービスの利便性を考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"阿部委員","kind":"質問","question":"二、三お伺いします。被災地に長期の職員の派遣をされる、これは定数の中で行うんだろうなと思うんですけれど、その出ていったもとの職場みたいなものは、この中に手当てはされているんでしょうか。１点、それを教えてください。","respondent":"堀越人事課長","answer":"今ある職員の中で対応できるというふうに見ています。ただ、職種によっては欠員が生じるという部分もあるかもしれませんので、そういう部分についてはいろいろ職場の工夫の中で、対応していきたいと考えているところです。","id":"exchange-009"},{"speaker":"阿部委員","kind":"質問","question":"要は、幾つかの職場で欠を出したままということでいいんですか。","respondent":"堀越人事課長","answer":"本年度、４月に採用する職員がおりますので、それから減した中で工夫を図りながら配置していくということですので、長期の派遣を予定しておりますけれども、そういった派遣をした所属には補充をするという考えです。","id":"exchange-010"},{"speaker":"阿部委員","kind":"質問","question":"付則でプラス７０人という、この付則というのは毎年書きかわって維持されている形だと思うんですけれども、いろいろな経緯はあるんでしょうけれども、この本体の定数を年々減らしていって、かつ付則でプラスを補い続けているというのは、これはどういう考え方によるものなんでしょうか。この枠を減らせばいいだけのような気もするんですけれど、どうでしょうか。","respondent":"堀越人事課長","answer":"この定数に対して、その７０名の分がオーバーする可能性がありますので、１年に限りこれを定数外とするような形にしているです。条例で１年間だけ、１年以内に解消する予定の職として定めているという考えで、付則を規定しているということになっております。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"今のご説明は、すぐに首にするわけにいかないから１年に限って残すということですと、付則の上限というのは変化をしながら毎年、特にここ数年間７０名ということですが、要は１年間のうちにそれを減らすというより、その方々の自然減を待っていらっしゃるという、実態としてどうなんでしょうか。","respondent":"堀越人事課長","answer":"年度ごとにいろいろ検討を行って定数を定めていくという形ですので、平成２４年４月１日現在に関しては、定数外として付則で７０名を規定し、今後１年間のうちにこの解消を図っていくというものです。","id":"exchange-012"},{"speaker":"阿部委員","kind":"質問","question":"詳しくはまたいろいろな機会で伺いたいと思いますが、これは年度内削減目標値みたいに聞こえたんですけれど、そういう理解でもよろしいんでしょうか。","respondent":"堀越人事課長","answer":"その場合はほかの、例えば今後１年間、平成２４年４月からのいろいろな人員の検討の中でまた改めて整理をして、その中でどういう形での定数、上限を定めるかということで、必ずしもこの１年間だけですべてが解消できるという形ではないと思いますけれども。","id":"exchange-013"},{"speaker":"阿部委員","kind":"質問","question":"最後に１つ、ちょっと漠然とした質問なんですけれども、民間の人事の方に聞くと、最近かなり定年延長等々で上が重たくなっている分、新規採用がしにくいというような構図を伺うことがあります。品川区の場合は、再任用ですとか定年延長はそんなに多くなかったと思いますけれども、そういったことも定数を減らそうという方向の一因にはなっているんでしょうか。","respondent":"堀越人事課長","answer":"退職者数、採用者数を見込んで、人員の数というのを出しております。そういう形ですので今年度、今度の平成２４年４月に関しましても、定年等も含めて大体普通の退職者は１００名を超える人数、百三、四十という形です。","id":"exchange-014"},{"speaker":"阿部委員","kind":"意見","question":"定数を減らすというと、結局は採用数から減っていくことになるわけで、若い人、中途採用なども含めてそこにどんどんしわ寄せが来ると、組織の活力と今、課長がおっしゃったみたいな問題も出てきますし、あまり定数を減らし続けるということはどうなんだろうと、マイナスの面もかなりあるような気がしますが、バランスなどにも十分留意して、あまり減らし過ぎないように考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問","question":"２点聞きたいと思います。最初に、先ほどの阿部委員の話にちょっと関連するんですけれど、この付則の人数は年々、一番多いときで１４４という数字もあるんですけれども、これは上限みたいなものはあるんでしょうか。","respondent":"堀越人事課長","answer":"特に上限というものはございません。毎年毎年の人員の見直し、算定の中で、どうしても定数を超える可能性があるものについて、付則として定めさせていただいているという形になります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"今までの付則に関する議論を聞いていて、例えば平成２１年までは付則が３０で、平成２２年から７０に４０名アップしているんですけれど、このときのアップの内容というのは、定数そのものは前年と比べて３０名前後の減り方をしている中で、最初に平成２１年度３０名の付則で、これは年度内に解消するという思いで３０としたんだけれども。","respondent":"堀越人事課長","answer":"そうではございませんで、このときに保育士の採用を大量に増やしているという経緯がありますので、その分定数を削減しましたけれども、実際にオーバーしてしまう可能性があるということで、保育士の大量採用をした結果、付則が７０という形で増えたという流れです。","id":"exchange-017"},{"speaker":"塚本委員","kind":"確認","question":"そうしますと、確認なんですが、基本的に付則というのは年度内に解消するものであって、繰り越していくというか、そういったたぐいの性格で設けられる数字ではないんだということと、そうであるのだとすれば、今年７０として、この７０の付則が達成できないということがあるのかないのか、あった場合にどういうような対応となるのか、というところをちょっとお伺いします。","respondent":"堀越人事課長","answer":"この付則は１年間限りという形ですので、１年以内に解消をする予定の職として設定させていただいているということです。","id":"exchange-018"},{"speaker":"塚本委員","kind":"質問","question":"では２点目の質問ですけれども、定数の削減がこの一覧表に出ていまして、本当に毎年、平成１２年度には清掃事業で増えたということですので、基本的に区としては毎年、リストラというか定数削減を進めていらっしゃるんですけれども、この定数について基本的な目指すべきところというか、適正な値と言ったらいいんですか、何を目指して進んでいらっしゃるのか、毎年毎年、来年度の予算。","respondent":"堀越人事課長","answer":"４月１日の時点がこの定数ということですので、そういった観点で決めてまいりますので、最初から何人という目標を立ててやっているものではございません。","id":"exchange-019"},{"speaker":"塚本委員","kind":"意見","question":"そういう意味におきましては、毎年毎年さまざまなトライをされる中で、より削減できることであれば削減していったほうが、私はもちろんそれはいいことだと思いますので、区民サービスはあくまでも低下しないという前提のもと、今言われたような観点で毎年毎年チェックをされて削減していくということで、大変に大事なことだなと思いますので、その点今後についてもしっかりやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"そういう点でもう一度確認したいと思うんですけれども、先ほどの人事課長のご答弁では、防災のときは正規の職員で対応すると、非常勤は役割が違うというふうにおっしゃったんですが、非常勤は災害対策のときはどういうふうに働かなければいけないのか、どういうふうになっていくのかということをちょっと確認したいと思います。","respondent":"堀越人事課長","answer":"そういう中で正規職員が中心になってやっていきますが、もちろん発災時には非常勤職員も安全の確保等の対応をすることになろうかと思います。その辺につきましては、所管において適切に対応をしていくという形で考えているという認識をしております。","id":"exchange-021"},{"speaker":"南委員","kind":"確認","question":"人事課長ですから全域的に掌握しておられるという前提で、あまり具体的、個別的なところには入っていないつもりですので、よろしくお願いしたいと思います。最後にちょっと確認をしたいんですが、資料の２ページの作業IIというのは学務課でマイナス１となっているんですけれども、これは職場はどこなのか、ちょっとここを確認したいと思います。","respondent":"堀越人事課長","answer":"こちらは学務課の日光林間学園が平成２４年度から民間貸し付けという形になりますので、こちらの作業に当たっていた職員についての部分です。","id":"exchange-022"},{"speaker":"原委員","kind":"質問・要望","question":"先ほどの塚本委員のお話にあったように、まず根本的に品川区としてはどのぐらいという基本的なところのお話が、やはりもう一度お話をいただきたい、人数はどのぐらいなのかというところ。結局法によって守られているわけですから、その辺も含めて２点、お話をもう一回いただきたいと思います。","respondent":"堀越人事課長","answer":"合わせていろいろな時代背景等を見まして、民間の企業等がサービスを担えるという形になった場合、それからもちろん我々職員が一生懸命仕事をして、工夫をして、２人でやっていたところが１人でするようになる、最大の能力を図っていくという意味で。","id":"exchange-023"},{"speaker":"原委員","kind":"質問","question":"非常に心強いご答弁をいただいたんですけれども、そういう形で基本を決めて、そのときそのときの年度によって考え方が変わっていくという形、考えというか人数でも、そういうことなんでしょうけれど、品川区にお願いをしたいのは、品川区は少数精鋭だよという、逆に品川区の職員だという誇りとかプライドが持てるように、それが今度は逆に言うと採用面において非常に大きく影響してくると思うので。","respondent":"桑村総務部長","answer":"最初のほうに戻りますけれど、職員の数が幾つになるか。これは区によっては一定の数の目標を定めておりますが、品川区はこの昭和５８年からずっとそうなんですけれど、毎年一定の考え方で見直していこうです。","id":"exchange-024"},{"speaker":"南委員","kind":"質問","question":"反対です。その理由をちょっと言いたいんですけれど、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"１つは、先ほどからちょっと私も強調している１,３１８人の職員を削減し続けてきた、そのことは、サービスは維持していくというふうにおっしゃるけれど、現実的にはサービスは低下している、そういう現状はいっぱいあるということを率直に見ていただきたいと思います。先ほどもずっと指摘してきましたけれども、保育園は、５００人の非常勤を採用してようやく成り立っている仕事だということですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"のが当委員会の目的でありますので、そのことを踏まえた上でご協力いただければと思っておりますので、よろしくお願いいたします。 それでは改めまして","agenda":"のが当委員会の目的でありますので、そのことを踏まえた上でご協力いただければと思っておりますので、よろしくお願いいたします。 それでは改めまして","exchanges":[{"speaker":"阿部委員","kind":"確認","question":"下部工の工事も随分長いことやっていたと記憶しているんですが、下部工はこことは全く関係のない会社が工事しているのでしたっけ。それとも少しかかわっていたりするんでしょうか。確認させてください。それから工期が１年間重なっているんですけれど、下部工側で１年間工期を残して、上部工というのは始められるものなのですか。","respondent":"阿部経理課長","answer":"これは先ほど第３回定例会と申し上げましたけれど、実は平成２１年第４回定例会で議決をいただいて工期延長と金額の変更、増額をしています。それで今回の平成２４年度までの下部工ということになってあります。この４０ページの３の工期のところに下部工と上部工があります。","id":"exchange-027"},{"speaker":"原委員","kind":"質問・要望","question":"総務委員会ですので、とにかく橋はなかなかどこの建設屋ができるわけでもないですから、特殊なものですから、まずは安全に交通を含めて、金額だけではなくて交通の関係もありますので、その辺も含めてとにかく第一に安全にお願いをしたいです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"意見","question":"ですがまあ、上部工は上部工でないとここはできないから、こういうふうになったのか、その辺についてちょっとご回答というか、見解をください。","respondent":"阿部経理課長","answer":"もう一方で、こう２つに分けているというのは、先ほども申し上げましたけれども、区内企業への受注機会の拡大、これは当委員会でも申し上げていますけれど、そういう機会の拡大を図るというのも区としては重要な施策ですので、こういう契約をしているです。","id":"exchange-029"}]},{"id":"topic-03","title":"の第４２号議案、山手線大崎駅構内百反歩道橋架替事業に伴う工事委託契約","agenda":"の第４２号議案、山手線大崎駅構内百反歩道橋架替事業に伴う工事委託契約","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それが１つです。それから契約金額が１４億９,０００万円ということですが、この内訳というか、このお金の出所というか、公費がどのぐらい入ってとか、民間の開発組合のほうからも出ているというふうに聞いたことがあったので、その辺の情報も教えていただきたいと思います。２点です。","respondent":"阿部経理課長、三宅都市開発課長","answer":"これは自治法、自治法施行令にもそういう場合には随意契約できるというような規定がありますので、そういう規定に従いまして随意契約としているというものです。２点目のご質問ですが、こちらの財源をご説明いたします。","id":"exchange-030"},{"speaker":"阿部委員","kind":"確認","question":"今のことでちょっと確認したいんですけれども、区単独ではお金は入っていないという理解でよろしいんですか。","respondent":"三宅都市開発課長","answer":"委員がおっしゃるとおりです。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"それを聞くと、この１４億円という金額も少し気が楽になるんですけれども。ただ一般論として、大変答えにくい質問かもしれませんが、今回高いのはわかるんです、かなり特殊な場所にありますし、ただこのぐらいの規模で、かつエレベーターなどを備えた歩道橋をつくる場合に、大体どのぐらいの金額でできるものなんでしょう。","respondent":"三宅都市開発課長","answer":"具体的に試算したことはないんですけれども、おそらく５億円ぐらいあれば、今おっしゃったようなスペックのものができるのではないかと考えています。ちょっと自信がないんですが、そのように考えております。","id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"いろいろな意味で特殊な場所であり、工事の方法等々、工期も相当、電車も、かかるでしょうから、その分どんどん押していくというのはわかるんですが。まあ、いろいろ努力された結果だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"そのうち、単純に見ると３分の１ずつ持つのかなみたいな感じになってしまうんですけれども、開発事業者のほうから５億円という金額が先にあるので、その２分の１というふうになるんだろうとは思うんですけれども、考え方として、こういう場合の積算の根拠というのか、数字をはじいていくところの考え方をもう一回確認したいと思います。","respondent":"三宅都市開発課長","answer":"そういう作業時間などの制約も全部想定でやっておりますので、今後具体的な作業をやった中で、最終的には精算ということを行ってまいりますので、内容については妥当かと考えております。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"そうすると、その返金については開発事業者のほうにも戻っていくと、そういう考え方なんですか。開発事業者の５億円というのは、出せる範囲がありますので、単純に３分の１ずつの負担ですよというふうに頭から決めるのでなくて、５億円ぐらいでつくってくださいと出してきたんだろうと想像するんですけれども、その辺の考え方というのはどうなのか、この際教えていただきたいと思います。","respondent":"三宅都市開発課長","answer":"もし余ったとしても、そういうもともとの趣旨を生かせるような形で、お戻しするのではなくて、大崎の発展のために使っていきたいというふうに考えております。","id":"exchange-035"},{"speaker":"阿部委員","kind":"質問","question":"所管にかかわってという部分もあって恐縮なんですけれども、この歩道橋は１５億円出してどのぐらいの通行量、要は引き寄せがあっての１５億円なのかというところを伺いたいです。それからちょっと大きな話になりますけれど、そもそも大崎駅東西は非常に横断の動線が悪くて、これはこれで一つの動線になるわけですけれども、決定的なものではないわけですよね。","respondent":"三宅都市開発課長","answer":"今、百反隧道のほうを自転車で通行されている方もいらっしゃいますので、４００人プラス自転車が通れるようになった人数ということになりますので、必要性は十分あるというふうに考えております。","id":"exchange-036"}]},{"id":"topic-04","title":"の第４３号議案、国文学研究資料館跡地整備工事請負契約","agenda":"の第４３号議案、国文学研究資料館跡地整備工事請負契約","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"先ほどの第４１号議案でもそうだったんですけれども、入札の受け皿というんですか、共同企業体ということに全部なっているんですけれど、これは漠然とした聞き方ですが、なぜですかという話になってしまいますけれども。","respondent":"阿部経理課長","answer":"そうすると、例えば今回なら２社が請け負うことができますので、そういう意味では多くの業者が建設工事の請負ができるということで、建設共同企業体となっているというものです。","id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"単独で受けられないからということではなくて、より多くの企業に受注機会を増やすためという理解でよろしいですか。","respondent":"阿部経理課長","answer":"ですから工事の規模によりまして、考え方、技術が必要なものについては区外の業者も利用するという場合もありますし、今回の場合については先ほど申し上げた理由で、２社が参加できるということで建設共同企業体を組むです。","id":"exchange-038"},{"speaker":"南委員","kind":"質問","question":"契約そのものではなくてちょっと恐縮ですが、工事概要の４のところに便益施設工が１棟で、災害用のトイレも１基しかないということが、これだけの避難場所になっているスペースでいいのかなと思ったので、その辺１点だけ伺いたいと思います。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘の工事の内容につきまして、特にトイレの数のご指摘ですけれども、今回の国文学研究資料館跡地整備におけるトイレなんですけれども、通常、平常時に利用できるトイレは１基設けさせていただいています。","id":"exchange-039"}]},{"id":"topic-05","title":"平成２４年陳情第３号、自治体臨時・非常勤職員の一時金・退職金を求める陳情","agenda":"平成２４年陳情第３号、自治体臨時・非常勤職員の一時金・退職金を求める陳情","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"それと、先ほど私も示しましたけれども、この募集の状況を見ると時間給が多種多様にあるようなんですが、大体年収にすると幾らぐらいになるのか、これは平均的なものでいいと思うんですけれども、職ごとに本当は伺いたいところですけれども、もし教えていただければ紹介をしていただきたいと思います。","respondent":"堀越人事課長","answer":"ただ１年間の勤務という形ではございませんので、それぐらいの数だということでとらえていただければと思います。それから先ほどご説明いたしましたとおり、さまざまな勤務形態がありますので、年収という形について把握はしてございません。不定期な勤務等もあります。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"今、臨時職員のことをご答弁いただいたのかなと思って伺っていたんですけれど、非常勤職員についても同じように教えていただきたかったので、改めて教えていただきたいと思うんですけれども。賃金については見ればわかるので、とりあえず今はいいです。雇用契約も１年ということで。それでよろしくお願いします。","respondent":"堀越人事課長","answer":"先ほどの相談員ですとか保育士ですとかは、非常勤職員についてのご紹介をさせていただいたものです。勤務形態等いろいろありますけれど、全体で大体４０種類ぐらいあるかなというふうに認識しています。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"年収にすると平均的に幾らぐらいになるのか、それを伺ったつもりなんですけれど、それを教えていただきたいと思います。","respondent":"堀越人事課長","answer":"年収についても先ほどご答弁させていただいたんですが、時間単位等もありますので、特に年収は把握してございません。それから４分の３以上はないかというご質問ですが、４分の３以上を行っているものはございません。","id":"exchange-042"},{"speaker":"南委員","kind":"質問","question":"４分の３を超えないでぎりぎり働いたにしても、そういう状況ですよね。そういう生活に置いておいていいのかということが問われているというふうに思うんですけれども、一般論として、そういう年収２００万円に満たない方々が１,０００万人という状況の中で、品川区もそういう条件で採用しているということについてはどのように考えているのか、その見解を伺いたいと思います。","respondent":"堀越人事課長","answer":"先ほどの４分の３につきましても、この陳情に書いてあるところで、裁判の判決の争点がどうなのかというところでご説明させていただいたものでございまして、４分の３という形には区ではなっていませんというご説明をさせていただいたものです。","id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"私が問題にしているのは、年収２００万円以下で、先ほど一、二紹介しましたけれども、年収１８０万円の保育補助は、１週間５日働いて１８０万円にしかならないわけですね。そういう点で、年収２００万円以下で雇用している、そういう方々の生活をどういうふうに考えているのか、ほかの仕事もやれるときはやれと、そういう考え方でこういう雇用形態でいいというふうに考えているのか、その辺について伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"今、本当に社会問題になっているじゃないですか。その辺を私はもう一度質問させていただきたいと思います。委員長が先ほどこの陳情と私の質問はちょっと違うんじゃないかとおっしゃったんですけれども、これは品川区に退職金支給が行えるようにしてくださいという陳情内容なんですけれども、その背景には年収２００万円以下のこういう現状では暮らせない、そういう状況があるのではないかと思うんです。","respondent":"桑村総務部長","answer":"直接答えられるかはちょっと別なんですけれども、１つは区の非常勤職員、ここに有期雇用と書いてありますけれども、私どもの非常勤職員というのは、いわゆる労働基準法の直接適用になるんです。これは１年以下でないと雇用ができないということになります。","id":"exchange-045"},{"speaker":"南委員","kind":"質問・要望","question":"陳情事項としては退職金・一時金ということですけれども、上段の陳情趣旨のところに「何年働いても年収は２００万円以下」と、こういうことがあるわけです。したがって、今、私が質問したようなこともぜひ伺っておきたいということで質問しているわけです。そういうことを求めるのではなくて、やはり働かせ方、そこが今の現状は、品川区もそうですけれど一般的に違うのではないかと思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"須貝委員","kind":"質問・要望","question":"それも自治法にない中で、さらに今どうこうしろというのは、私はそれはちょっと行き過ぎではないかなと。それよりもやはり国全体が景気対策、雇用増の対策をするということに私は尽きると思いますので、今回の陳情に関しましては、お気持ちはよくわかりますが、やはりこれを要望するということまでには、私はそれを受けるということは、今の区の自治体として考えた場合には私はできないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"阿部委員","kind":"質問","question":"非常勤も臨時職員も、雇用の質、量ともかなり多様であって、なかなか全体を把握するのは難しいなと思って伺いましたが、この陳情の中でも「すべての」と陳情事項で言われているので、これもまたちょっと難しいところがあるかなと思うんですが。先ほどご説明のあった計１,０００人ぐらいの非常勤、臨時職員の中で、専門職と非専門職の割合というのはざっくりでもおわかりでしょうか。","respondent":"堀越人事課長","answer":"専門の非常勤の割合は１,０００人のうちのどうかということで、保育園の部分については、先ほど５００人という形でご説明させていただきましたので、その１,０００人の残りが専門的な形というふうにご理解いただければと、大体の数字です。","id":"exchange-048"},{"speaker":"阿部委員","kind":"質問","question":"１年だ、２カ月だというのは有期の比較的短期の雇用形態であるということが、多分法の意図するところであると思うんですけれど、実態として何年間も契約を繰り返して働いていらっしゃる方というのはいるのか、あるいはどのぐらいいらっしゃるのかということについてお伺いします。","respondent":"堀越人事課長","answer":"非常勤職員については一定数いらっしゃると思います。具体的な数字はちょっと今持っておりませんが、一定数が引き続き、１年ごとに採用選考をやらせていただいて、採用させていただいて仕事におつきいただくという方が一定いらっしゃると認識しております。","id":"exchange-049"},{"speaker":"阿部委員","kind":"質問","question":"１,０００人の中の相当なボリューム層が保育園の非常勤職員の方々で、臨時職員が２カ月、実態として２カ月ごとでかなり入れかわりをしているんですか。そうも見えない部分が。どうなんですか。","respondent":"堀越人事課長","answer":"保育園で主にやっていただいているのは、非常勤職員として短時間のご勤務をいただいているということで、１,０００人の中に臨時職員は入ってございません。","id":"exchange-050"},{"speaker":"阿部委員","kind":"質問","question":"保育園は非常勤で１年ごと、でも先ほどのご答弁だと繰り返しというわけではないという実態だとすると、この「何年働いても」というのは制度の問題であって、何年間も継続して働いているわけでは、ほとんどの方はないと理解してよろしいんですか。","respondent":"堀越人事課長","answer":"１年ごとに採用して、結果としてまた採用されて働いているという方がいらっしゃるというふうに認識しております。","id":"exchange-051"},{"speaker":"阿部委員","kind":"質問","question":"その意味では、契約を何度も繰り返すということについて、雇用者としては一定の考え方、方針を持っておくべきであろうかと思うんですけれども、時間としては４分の３ではあっても、その職場に対するお互いの依存性みたいなものは、継続とともに高くなるわけですから、そこは雇用者として何か一定の歯どめを持っておくべきであろうかと思うのですが、その辺はいかがですか。","respondent":"堀越人事課長","answer":"きちんと適正に、法令等にのっとって採用行為を行っていると認識をしています。","id":"exchange-052"},{"speaker":"阿部委員","kind":"質問","question":"役所の場合は、まだ短時間正規みたいな雇用のあり方が制度としてないので、実態と制度がどうしても合わない部分もあるかと思うんですけれども、やはり働き方の形としては、今は制度よりも働き方自体のほうがよほど多様なものですから、そういう意味でも、ある程度方針があってしかるべきではないでしょうかということです。ですので、現行に問題があると言っていることではないです。","respondent":"堀越人事課長","answer":"この非常勤職員に関しては、やはりこれも繰り返しになりますけれども、民間等いろいろな形でそういった力をおかりしながら、いろいろ正規と一緒になって働いていただくという形で、一定の時間について民間の力をおかりするという形でやっていくと、そういう考え方です。","id":"exchange-053"},{"speaker":"阿部委員","kind":"意見","question":"今日結論を出すということでいいと思います。この陳情事項については、今の人事院のルールからいって残念ながら合わないということです。ただ、臨時職員、非常勤職員の労働条件、働き方などについては、実態に即した形でと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"南委員","kind":"質問","question":"私も結論を出すことは反対にはしません。私の態度としては、採択ということです。一緒に意見も言っていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"南委員","kind":"質問・要望","question":"例えば保育園などは、採用の状況を見ると「保育資格を持ち」というふうになっているんですね。笑顔で接して、子どもたちに何の不安もなく接してくださっていると思いますけれども、しかし精神的、身体的な状況は相当厳しいのではないかと思ったとき、やはり働く条件を改善させるというのは、いい保育に、子どもが健やかに育つ、そこにかかってくるわけですから、やはり改善をさせていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/777073?Template=document&Id=1906#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":42020,"voices":165}},{"id":"h24-20120228-6","meetingId":"h24-cm02","date":"2012年2月28日","dateIso":"2012-02-28","committee":"区民委員会","time":"午前１０時００分～午前１１時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この大井第三の自動ドアのことはすごく前から、住民の皆さんから要望が出ていたと思うんですけれども、大変皆さん喜んでいました。ちょっと自動ドアのことではないんですけれども、関連して、駐車場も少ないという声もすごくあるんですけれども、あそこって何台おけるんでしょうか。設定は何台になっているのか。","respondent":"武内地域活動課長","answer":"地域センター所有の軽自動車がありますので、それを１台置くというのが原則でありまして、大井第三地域センターにつきましては、住宅地もありまして、道路も非常に狭いもので、基本的には地域センターの利用者、または集会所の利用者につきましては。","id":"exchange-001"},{"speaker":"大倉委員","kind":"確認","question":"１カ月間の休館に伴う、例えば利用されている方たちがどこにこう、別途違うところを使いたいといえば使えるように工夫されたりとかというのはするのかだけ、ちょっと確認。","respondent":"武内地域活動課長","answer":"今お話ししたとおり、夏場につきましては利用者の方も大分減るということもありますので、その辺は周辺の、今言ったウェルカムセンター原とかというところで利用していただければというふうに考えております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"このパトロール隊は、どういった単位でつくられていくのかなと思ったのと、あとほかにも安全パトロール隊みたいなのがあって、そこに指導を受けてという感じで事務事業概要には書いてあったように思うんですけれども、どんどん細分化されていく感じがするんですが、細かに町の中で地域の皆さんが連携して助け合うというのは大事なことだと思うんですけれども、何だかどんどん小さくして。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"それが区内に５つ団体があるんですが、その団体の方々を再構築するという意味合いを持っているです。細分化するというのではなく、新たにまた防犯パトロール活動を継続していただき、町の犯罪抑止に寄与していただこうというものです。これはご案内かと思いますが、事務事業評価でＣをいただいていまして、地域の自主的防犯活動に対する支援の仕組みを検討するようにということで、そういった中で、この人たちにだけ特別扱いするというのは、課長も先ほど説明しましたが。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしたらそれは、呼びかけて集まった方が自由につくるという感じなので、既存の何かくくり、町会なり、商店街なり、自主的に集まってくる、事業概要にも結構な方が集まっているなと思ったんですけれども、それをさらに再構築していくということでは、また同数ぐらいの方が集まられる予定でしょうか。","respondent":"川崎生活安全担当課長","answer":"当方の５つの団体としてやっていたところですが、さっき地域振興事業部長がおっしゃったように、現在町会でもパトロールをしてくださっているところもありますし、そして当時、平成１６年の話になるんですけれども、町の防犯をもっとさらに高めようということで。","id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"この自主的な防犯というのはすごく大切なことだと思うんですけれども、まず我が町パトロール隊を再編するということは、一度これは解体というか、終わりにして新たに団体をつくる、自主的な防犯団体に助成を出すのかというところが１点目と、例えば今お話しされていた町会とか、防犯協会とか、今そういう独自にやっている団体との連携というか。","respondent":"川崎生活安全担当課長","answer":"そして警察署と区の連携のパトロール隊として、非常に役割が大きゅうありますので、引き続き、引き続きというか、このパトロール隊をもう一度警察署との連携を続けていく考えで、これを存続させたいですので、一旦は解散しますが。","id":"exchange-005"},{"speaker":"沢田委員","kind":"質問","question":"もう一つちょっと思ったんですけれども、この設立時１０万円、以降３年継続するたびに５万円というのは、必要な物品というのは、例えば町会にもいろいろ、こういう何というんですかね、ライトとかあったり、こういう防犯の上着があったりとかあるわけですけれども、それを借りるのではなくて、独自にまた自分たちでつくれということなんですか。","respondent":"川崎生活安全担当課長、中川原地域振興事業部長","answer":"その物品購入費ですが、我が町パトロール隊の移行も考えておりますが、そのほかにもさっき言いました、助成を受けていないんですけれども、実質的に小さな活動ですがやってくださっている団体がたくさんありますので。ただし、地域によっては、もう既に防犯協会と防犯部と、それからＰＴＡと、それからこの我が町パトロールと、自主的に活動の組織をつくってやっているところもありますので、今全部調査したところに。","id":"exchange-006"},{"speaker":"山元委員","kind":"質問・要望","question":"１つはこれからいろいろ、今の部長のお話ですと再構築ということで、ある程度予想というか、どのぐらいの予算じゃないんですが、ある程度予算を立てないと、なんでもいいというわけではないと思うんですけれども、どのぐらいグループが企画されるかなということが目安があるのかどうか。その辺ちょっと教えていただきたいと思います。","respondent":"川崎生活安全担当課長","answer":"３点ご質問いただきました。予想されるグループの団体数ですが、現在我が町パトロール隊は区内に５つあります。その存続等含めて、そのほかにプラスアルファということで、１０個以上できればいいなというふうには考えております。","id":"exchange-007"},{"speaker":"山元委員","kind":"質問","question":"もう一つなんですが、そうしますと、今はＰＴＡさんですが、あくまでも、さっきの町会の話もありましたけれども、個人的にグループを組んでパトロール隊をやりましょうということであれば、青少年の団体でやっているけれども、それは別にグループを組んでもいいんですか。","respondent":"川崎生活安全担当課長","answer":"今のご質問については、ＰＴＡの方が個人的にグループを組んで、それで活動をしてパトロールをしてくださる。大歓迎です。","id":"exchange-008"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"車で回っている方たちの車というのは、だれのものでしょうか。個人的な持ち物なのか、区のほうでお貸しをするのか、その辺の仕組みと、あと協働・連携による区民と警察署と区ということで、区のほうも協働の１つとしてこの助成金を出すというのが当初の趣旨なのかなと思うんですけれども、これ具体的に、じゃあ警察署と区と、どのように連携をしていくのかというのがいまいち見えてこないんですね。","respondent":"川崎生活安全担当課長","answer":"例えば声をかけてやめなさいと。１１０番しますよとみんなで取り囲んで、そういうことはやめなさいと。一般の大人の方が大人として当然やるべきことをお知らせする、そのような研修会をする。今までもしておりますし、そういうふうにする予定です。","id":"exchange-009"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えばワッペンにするとか、今、それこそいろいろな団体がもう既に持っていると思うんですけれども、それをちょっと工夫するだけでも、スタート時に非常に低予算でやれるのかなと思うので、できる限りお金はかけずに工夫をしながら、やっぱりセーフティアップ運動だよというのはわかりやすいようにしていただければなというのを、難しいかなと思うんですが、それは要望で終わりにしたいなと思います。","respondent":"川崎生活安全担当課長","answer":"トランシーバーは警察で持っている無線機のことなんですが、これは警察官しか持てませんので、これは一般の方にお渡しするわけにはいかないので、ちょっとそこは考えておりません。ですが、今携帯電話を持っていますので、これで連絡をとり合う。","id":"exchange-010"},{"speaker":"大倉委員","kind":"質問・要望","question":"すみません、１つだけ。警察官の方が一緒にいれば、こうこう回りましたとか、警察署に集まるとおっしゃったのは、そこで確認するとかいう、どういうことをやっているという実態調査というのはやるのかということを聞かせていただきたいと思います。","respondent":"川崎生活安全担当課長","answer":"月に何回、例えば大井町の駅前で、振り込め詐欺防止のチラシを配りましたとか、どこどこ何丁目を本日の参加人員１２名でパトロールをしましたとか、このような、いつどこで何を行ったというふうに記録したものを別途我々のほうへ出していただく予定でおります。","id":"exchange-011"},{"speaker":"本多委員","kind":"質問","question":"今の地域開放のところで、説明を伺っていまして、その管理をするときに青少年育成課が管理をしたりする、少年少女のスポーツ団体ですね。その辺の管理の仕方というのは、庁内で一元化というか、一本化という議論というのはなかったのか、まずそれをお聞きしたい。","respondent":"安藤文化スポーツ振興課長","answer":"ここでは日本美装という民間会社に委託をして管理をしていただくということになります。ですから、巡回指導だとか、施設のほうの施錠管理、それから受付等は、事務分担を委託業者が行うと。そこは少年少女も含めて、登録団体も含めてすると、そんなことになると思います。","id":"exchange-012"},{"speaker":"本多委員","kind":"質問","question":"あいているときがあるので、それが本当に何というんですかね、調整ができていない現状があるので、またこの品川学園でも同じことが起きないかなと、ちょっとその辺を心配するんです。その辺の、何というんですかね、もっと調整、調整会議とか何か、すごくうまく回るのかなと思うんですけれども、あまり分けると、かえってそれが稼働率を悪くするんじゃないか、その辺を心配するんですけれども。","respondent":"安藤文化スポーツ振興課長","answer":"先ほど申し上げましたように、管理自体については私どもがすべてをやる。そして、施設使用の調整については、地域開放については、もうすべて３６５日、年末年始を除いてですけれども、うちのほうで調整会議をしてやっています。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問・要望","question":"最後に聞きますけれども、野球とサッカーとかの組み合わせはすごく、それぞれの団体でうまくいっていると思いますので、そのうまく住み分けて、しっかり支援をしていただくために、これ単年度でいいんですよね。できれば私は、青少年育成課ではなくて、すべて文化スポーツ振興課が一元的に見ていただけないかなとすごく思っているんですけれども、要望ですが、もし何かあったら。","respondent":"安藤文化スポーツ振興課長","answer":"学校の施設管理についても私どものほうで管理します。ただし、調整だとか、そういうものについては、今のように、委員ご指摘のとおり青少年育成課がやっておりますので、委員のご要望につきましては、青少年育成課のほうに申し上げたいと思っています。","id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"質問なんですが、ここにはグラウンド、結局４つあるわけですけれど、この使用料のところ、計算するとこの使用料の全面というのは、4)番の低学年用庭は別になっているのか。それから、もし違っていたら言ってください。土日の学校と土日の校庭開放とかあるんですが、これは、ここで聞いていいのかちょっとわからないんですが、もし答えられるのであれば教えていただきたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"それとあとの土日の開放につきましても、委員のご質問が遊びや稽古だと思います。それについては教育委員会が所管しておりますので、申しわけありませんがわかりません。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"スポクラ・しながわ、これはどういった団体なのか、少し調べてみたんですけれども、もう一つわからなかったのでお聞きしたい。この開放の予約は、一応８月と４月からということなので、一月前ということなのか。","respondent":"安藤文化スポーツ振興課長","answer":"そういう中で、品川区においても２年前にスポクラ・しながわという組織を設立いたしました。これは設立したといっても、地域の利用の団体の方々を中心にして、皆さんのご意見をいただきながら、協働しながらつくっていったものです。それが、スポクラです。","id":"exchange-016"},{"speaker":"石田（慎）委員","kind":"質問","question":"第一と第二と同等に低学年用の庭をその団体等に貸し出しをするのか、そこは１点お聞きをしたいと思います。その対処策として、僕は低学年用庭を地域に開放するというような話を小耳に挟んでいたので、ちょっとそこだけ、その使い方を。","respondent":"安藤文化スポーツ振興課長","answer":"第１点目も第２点目もリンクしておりますので、答えします。この低学年用の庭につきましては、委員ご指摘のとおり、この少年少女のスポーツ団体は、少年野球、少年サッカーが主です。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"開設についてですが、まずこれだけの資料に目的が書いてないんですけれども、改めて目的を教えてください。それと４番で職業紹介と書いてあるんですけれども、相談も含めた職業紹介と就業支援の違いを教えてください。それと、サポしながわの括弧のところに、行政がやるのは基本的に無料と思っているんですけれども、あえて無料職業紹介所と、無料と入れているのは何かあるのか、まずそこから教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"この目的ですけれども、この事業概要とほぼ重なってしまうんですが、こちらでハローワークによる職業相談・職業紹介を行うということと、こちらの品川区が行っている就業支援策と連携させるということによりまして、両者の機能を強化させていくというのが一番大きなものです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問","question":"あえて目的はというのを伺ったのは、これ相当期待されると思うんですよね。ということは、この連携するということの最大のメリットというのはどこにあるのかということと、あと連携することによってこういうふうにやるわけですから、その投資対効果といいますか、どの辺の効果というのを区として考えているのかということなんですけれども、その辺についてはいかがでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"その連携を今回さらに強めることができましたので、その相談、今までは品川区の就労自立支援相談員が本人を連れてハローワーク品川のところまで行って、そこで相談をさせていたと。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"だから、その辺も期待していますので、費用対効果の期待する部分の効果はわかったんですけれども、最後に、これに関する費用というのはどういう形になるか、例えばハローワークが来ることとか、そういうことに関してかかる費用、入る費用、その辺のお金の部分について教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"こちらのほう、費用ですけれども、平成２４年度の予算ですと、この全体ですが、就業支援事業という形で新たな予算を組ませていただきました。これが２８４万６,０００円です。この中にはハローワークが来るということだけではなくて、独自で行う費用への支援も含めてです。","id":"exchange-020"},{"speaker":"石田（ち）委員","kind":"質問","question":"この周知のほうは、どういった方法で行うんでしょうか。","respondent":"福島ものづくり・経営支援課長","answer":"周知ですけれども、まず区報の『広報しながわ』のほうに載せると同時に、今度私どものほうで『産業ニュース』を発行しますので、その３月号の一面に載せるとともに、中折り込みでＡ４のチラシをつくってそれを配布すると。","id":"exchange-021"},{"speaker":"石田（ち）委員","kind":"質問","question":"どれだけ利用されるかという想定。私もすごく期待しているんですけれども、目標、事業目標なんかも、掲げる予定はあるんですか。","respondent":"福島ものづくり・経営支援課長","answer":"ハローワークと協定というか事業計画を結んでおります。これから結ぶんですけれども、その目標としまして、平成２４年度としまして月間延べ８００人の求職者に対して相談等を行い、年間５００件を就職できるということで目標を立てております。","id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりなかなか仕事につけないというところでは、私たちもずっといっていましたが、若い世代から、それからサポしながわにもありました５５歳以上の方からと、すごく今、幅広くなってしまっていると思うんですけれども、やはり若い世代と高齢の世代を合わせて、一定に周知をしていただきたいなと私は思うんですね。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"山元委員","kind":"質問","question":"今、ものづくり・経営支援課長のお話にありました、月間延べ８００人の相談等を想定されていらっしゃるようなんですけれども、あの入り口、中小企業センターのところの入口では、かなり込み合うんじゃないかと。その辺の対応というか、今さっきのお話だと４人の方が常駐なさっているということでしたけれども、その辺の流れというか、どのように考えていらっしゃるのか、その辺ちょっと教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"確かにあの場所、それほど広いということではないので、混雑も予想されております。したがいまして、受付要員を１名配置するようにしました。その受付ではカウンターといいますか、ナンバーを出して、何番というのを渡して、それで待合で待ってもらう。","id":"exchange-024"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"先ほど答弁の中で生活保護受給者の方たちの就業支援にも積極的に活用していきたいという答弁がありましたけれども、私も以前から区役所にぜひハローワークを持ってきていただきたいと、かねてから言っていて、実現をして非常に、本当に期待をしている中、やはり以前、おととしでしたっけ、品川のほうのハローワークに区の職員の方たちが出向いて。","respondent":"福島ものづくり・経営支援課長","answer":"まさに委員おっしゃいましたように、総合的に行っていくというのが、ハローワークと連携し、また、私どもの部署だけではなく、生活福祉課、あるいは母子家庭を所管します子育て支援課、そういったところ、あるいは障害者になりますと少し専門的になるんですけれども。","id":"exchange-025"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それともう１点、支援対象者の中でこの区内の事業者、事業主のほうも協力をということですけれども、せっかくこういったシステムを構築するわけですから、ぜひ区内の中小企業の方で、新たな人材を確保したい方たちにおいては、今までも一生懸命やっていただいていると思いますけれども、こういった新たなシステムの中で、よりさらに支援の輪を広げていただきたいなと思います。","respondent":"福島ものづくり・経営支援課長","answer":"区でいう人事課みたいなものがなかったりしますので、そういう方々向けにどういうふうな人材を集めたらいいのか、あるいはどういうことをすれば人材が集まるのか、そういったようなセミナーをやるとともに、コンサルタントを派遣して、その企業は、企業で、事業所は。","id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"こんな気合い入れているわけですから。大体の協働・国際担当課長が考えている、このフェスタに来てくれる人数というのをどう把握しているのかということと、ものすごい人数が来ると思うので、その交通整理等というのがあると思うんです。その辺の含みにおいて、どういうふうな予定をなさっているのかお伺いします。","respondent":"今井協働・国際担当課長","answer":"協働推進室だけではなく、こみゅにてぃぷらざ２階の講習室にも場を広げたり、あと八潮太鼓の方には体育館で演奏していただくことも考えております。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/119261?Template=document&Id=2630#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":27228,"voices":102}},{"id":"h24-20120228-7","meetingId":"h24-cm02","date":"2012年2月28日","dateIso":"2012-02-28","committee":"厚生委員会","time":"午前１０時００分～午前１１時２９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","topics":[{"id":"topic-01","title":"第五期品川区介護保険事業計画骨子案パブリックコメントの結果および高齢者一般調査","agenda":"第五期品川区介護保険事業計画骨子案パブリックコメントの結果および高齢者一般調査","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"パブリックコメントについてお伺いしたいのですが、これは説明会の開催についてということで、広報紙、ケーブルテレビ、区ホームページ等のメディアを通じた意見公募を実施しましたということで書いてあるんですが、区からこのパブリックコメントを求めますということで行ったことは、この３つだけなのか、ちょっとそこら辺の、あと説明会とかそういうのは。","respondent":"原高齢者福祉課長","answer":"パブリックコメントの関係ですけれども、多くの方からご意見をちょうだいするです。そういった意味では、多くの方が目に触れていただける場所に事業計画を置くということと、それから、今回、初めての取り組みですけれども、骨子案の後ろにはがきをつけさせていただきました。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２４名というのは、私はちょっと随分少ない数だと思っているんですけれども、この２４名という意見の数に対して、区はどうとらえられているかということと、それから骨子案のパンフレットもいろいろ今回は、地域センターですとか、文化センターですとか、いろいろなところに置いていただいたと思うんですけれども、骨子案のパンフレットは何部ぐらい印刷されて、どれぐらい区民に届けられたのか。","respondent":"原高齢者福祉課長","answer":"そういったところと比べますと、７名の方が少なくなっているというところと、それから、介護保険は６５歳以上の方で考えますと、約７万１,０００人の方が対象になるわけですから、そういった中でパーセンテージでとらえますと、非常に少ない意見です。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それともう一つは、このパブリックコメントの期間が、私は短すぎると思うんです。多分、他区の状況とか何かも見てみますと、１カ月とかそれ以上やっているところも結構あるんです。そういうところでは、ちょっと１４日は短すぎるのではないかと思うんですけれども、これをぜひ延ばしていただいて、もっと区民が意見を言えるような、そういう方向にぜひしていただきたいと思うんですが、いかがでしょうか。","respondent":"原高齢者福祉課長","answer":"第六期に向けてさまざまな検討を踏まえ、また、この時期でしか意見をお受けできないということではなく、日ごろの中でも十分意見をいただきながら、それをまた次期の計画に活かしていく、こういったところも引き続き進めてまいりたいと考えています。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"パブリックコメントの１４日という日程はちょっと短すぎるのではないかと思うんですけれども、それをぜひ延ばしていただきたいということに対してはいかがでしょうか。","respondent":"原高齢者福祉課長","answer":"さまざまな形で検討して、その中でどういった形が意見を十分に吸い上げられるかというところで検討してまいりたいと考えています。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ここの中で出てきたところで、２ページ目のにこにこ訪問事業の終了ということが書かれていたんですけれども、ちょっとこれも、私も３月末で終わるというのをつい最近お聞きしたのですけれども、見守り、孤立死防止というところで、健康福祉事業部長もにこにこ訪問や緊急通報システムはそういうふうな制度で品川区としても今までやってきましたというのは。","respondent":"原高齢者福祉課長","answer":"このにこにこ訪問事業は、平成２年１１月から実施してまいりました。平成１０年から社会福祉協議会の事業ということで、その後継続しています。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"しかも、それほどの莫大なお金がかかるというわけでもないですので、なぜ廃止をしたのかが今のご説明ではよく理解できないんですけれども、緊急通報システムがそれにかわるのはなかなか難しいと思いますし、緊急通報システムも数としてはまだまだ本当に少ない数になっていますし、また、緊急通報システムやそういうにこにこ訪問とかの重層的な見守りの中で。","respondent":"原高齢者福祉課長","answer":"先ほどご説明したところですけれども、平成２年からこういった事業をしてまいりました。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところでは、ぜひにこにこ訪問は、３月３１日ということで、まだ廃止はされていないので、継続していただきたいと要望させていただきたいと思います。それとあと、緊急通報システムも前から言っていますけれども、ぜひ低所得の方に対しては無料でというところもご検討いただきたいと考えています。","respondent":"原高齢者福祉課長","answer":"そこについては、冒頭にご説明させていただきましたように大きな違いはないということで、こういった品川区というところでは、この圏域というところは、今、私ども６圏域と１３圏域というところの圏域で進めておりますけれども。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今回のアンケートは、この骨子案をつくるためということで、３年にいっぺん、こういう形でやるというアンケートということでとらえていいでしょうか。","respondent":"原高齢者福祉課長","answer":"そういう意味では、さまざまな形での調査、それからご意見等を通じて、次の介護保険事業計画、あるいは途中でできることを含めて、ご意見をいただきながら今後も進めてまいりたいと思っているところです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"一般調査のほうです。そこに反映する、活かしていくというのは、当然、おっしゃっている意味は重々わかるんですけれども、この調査の結果に対して、これは１０設問なのですかね、これ、グラフの数で拾っていくと。ちょっと調査票がないので、(1)から(10)までなのか、もっとあるのかわからないのですが、そこの意味、設問の数と、それから、この調査結果をした、こういう若干の分析があります。","respondent":"原高齢者福祉課長","answer":"先ほどの説明の中でもご案内させていただきましたけれども、やはりひとり暮らし高齢者の方ですと、日常生活の中で不安な事がいくつかある、それから、緊急時の対応です。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"ということで、そういうオープンな場でやりますので、ぜひ高齢者福祉課長のご説明にもあったように、ここで何行かでご説明していますけれども、今、区ではこういうことにも取り組んでいますというようなことも積極的にアピールというか、お答えを返す意味でも、そこら辺のところはまだまだ緒についたばかりで、これから本当にどんどん来てくださいというわけにはいきませんが。","respondent":"原高齢者福祉課長","answer":"数字といたしましても、区民の皆様がこういった在宅の介護だけではなく、医療との連携も非常に意見として高いところがあるということで、国の考え方、あるいは区が今までとってきた考え方も、さらにこれから進めていきたいと考えているところです。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"私はやることは大切だけれども、それぐらいの気持ちでやってほしいと思います。これでよく７０歳以上の人がぱっぱとこれが書けたかな、とちょっと不安に思っている私がいるのだけれども、７０歳以上のひとり住まいの方を悪く言っているわけではないのだけれども、すごく理解がしがたいのではないかと思うのだけれども、そこら辺はどう思っていらっしゃるんですか。","respondent":"原高齢者福祉課長","answer":"そういう中で、私たちは保険と医療は国の流れ、区の考え方ということで当たり前に思いつつ、こういったアンケートをとらせていただく中で、少し書き手のところをもう少し配慮した形がここの部分を含めてほかの部分もあったかどうかというところをもう１回点検しながら。","id":"exchange-011"},{"speaker":"鶴委員","kind":"質問","question":"特にそういう具体性を持ったようなところですね。設問の配置だとか、どうしても目的に沿った答えをしてほしいという部分が、やっぱり私などがぱっと見て、マーケティングをいくつかいろいろ見る中で、何となくそういうところも伺えるので、その辺の工夫、もっと幅広くお声をいただくというその工夫、そこら辺も含めてお願いします。","respondent":"原高齢者福祉課長","answer":"アンケートの目的は、計画に活かしていける、それから、ひとり暮らしの方に今回はしましたけれども、その方々のニーズ、あるいは困り事等がどこにあるのかというところでまた地域の状況がどうだろうかという、圏域という。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"１つ聞き忘れました。当然、経費の問題もあるんでしょうけれども、その辺のもう少し回答率、５０％以上もあるので、あれなんですが、ちょっと訪問で配るとき、集めるとき、回収、この辺の意図をちょっと教えてください。","respondent":"原高齢者福祉課長","answer":"そういう中で、ぎりぎりの数字ですけれども、中身、それから回収率、こういったところでの工夫というものがさらにできないかというところでは、今後の検討課題としていきたいと考えています。","id":"exchange-013"}]},{"id":"topic-02","title":"品川区バリアフリー住まい館の閉館","agenda":"品川区バリアフリー住まい館の閉館","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回、閉館するということなんですけれども、この来館者というのはどれぐらいいらっしゃるのか、また、その変遷がどうなってきていたのか、ちょっとその実態だけ教えていただきたいと思います。","respondent":"原高齢者福祉課長","answer":"今年の６０６名の内訳を見ますと、区外の方、それから中学校の社会科見学であったり、外国からの方の見学でありましたり、それから、都立の訓練校の方の見学であったりというところで数値としては４０％近い部分が、全部がそういった方というところではございませんけれども。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問","question":"この後、ここはどうなるのかというのが１つ。それから、例えばよくわからないんですけれども、あそこへ行かせていただいて、傾斜があって車いすの体験とかもさせていただいたりしたけれども、今はずっと忘れていたけれども、これが閉館になるというので思い出したことなんですけれども、ああいうことはふくしまつりとか、例えば住宅フェアとか、そういうときにやるという考えはないのですか。","respondent":"原高齢者福祉課長","answer":"今後もこういった取り組みを広く、援助職である者は当然ですけれども、区民の皆様にも何らかの形で体験いただくような工夫をしていきたいと思っているところです。","id":"exchange-015"},{"speaker":"若林委員","kind":"質問・要望","question":"事業の見直しの中で、下段のほうですけれども、この閉館後ということでバリアフリー住まい館での専門的な施工手法や云々と。テキストとしてまとめ、区内ケアマネジャーへ配付していくというんですけれども、何か新しい印刷物をつくってということの理解なんでしょうか。","respondent":"原高齢者福祉課長","answer":"それを毎年つくるということではなくて、この間の取り組みということでテキストにまとめたものを配るということで、平成２４年度限定でするということで考えているところです。","id":"exchange-016"}]},{"id":"topic-03","title":"小規模事業所の受託健診","agenda":"小規模事業所の受託健診","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"私が大変不勉強だったと思うんですが、これをいただくまで、こういう事業をやっていること自体が知らなかったです。それで、今回初めてわかったのですが、料金も普通の医療機関に頼むより、ここのほうが安い。うちの不勉強さが一番悪いのだろうけれども、だけれども、これはもともと広報をどういうふうにやっていたんですか。それだけちょっと教えてほしいですね。","respondent":"矢野品川保健センター所長","answer":"そういう中で、保健所でやるべきかというところで、かなり迷いながら実施していたというところで、あまり大々的な周知はしてございません。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"１４６カ所ということなんですが、トータルすると何人くらいの方の健康診断をされていたのかと、それから、料金が安いということなんですが、一般と比べると何割ぐらい安いのか。それとあと、ここ、かなりの人手も要する事業だったと思うんですけれども、そういうところでは、それによる人手は今後どういうふうに何かほかのところに充実させていくとか、そういうふうな考え方についてもお聞かせください。","respondent":"矢野品川保健センター所長","answer":"この事業をやめて、その後、どういうことに力を注いでいくかですが、月２回ということで、常勤職員の人手に関して２回分ということで、大したことではございませんが、地域の健康づくり、あるいは普及啓発活動、それから母子の健診等もかなりきめ細かく実施していますので。","id":"exchange-018"},{"speaker":"向委員","kind":"質問・要望","question":"わかればなんですが、教えていただきたいのが、こうやって保健センターで健診すると、もうその後の、その方が例えば病気が見つかったとかだと、すぐ区のほうで把握できると思うんですけれども、外部で一般の機関で健診したときのそういう情報は、区に来るまでどれぐらい、例えば乳児健診を外部でするのと保健所でするのとでは、ちょっと時差があるのかということを伺ったことがあって。","respondent":"矢野品川保健センター所長","answer":"この健診でも、結構血圧が高かったり、糖尿病の方とか見つかることがあります。緊急に医療機関へ行ったほうがよいというような方については、本人をお呼び出しして、なるべく紹介状をお渡しすることにしておりますので、結果日は２週間後ということで対応しております。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"大井林町の高齢者住宅の二次募集なんですが、単身世帯がたしか３戸だったと思うんですけれども、世帯用が７戸でしたか、それに対してどれぐらい応募があったのか、そして、公開抽選はもう既に終わったのか、そこのところをちょっとお聞かせください。","respondent":"間部高齢者いきがい課長","answer":"２月の募集の件ですが、単身用３戸につきまして１１戸の申し込みがございました。２人用７戸については９戸です。なお、第１回目の募集につきましては、６１件の募集があったわけですが、先般、資格審査を経た公開抽選で６０名の方の入居については決定をしています。","id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/452893?Template=document&Id=3318#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":24949,"voices":70}},{"id":"h24-20120228-8","meetingId":"h24-cm02","date":"2012年2月28日","dateIso":"2012-02-28","committee":"建設委員会","time":"午前１０時００分～午後１１時５１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","topics":[{"id":"topic-01","title":"の１、報告事項を行います。 初めに、(1)東品川橋架替工事（上部工）の着手","agenda":"の１、報告事項を行います。 初めに、(1)東品川橋架替工事（上部工）の着手","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"工事を始めるということですけれども、１点ここにかかわって津波の対策を伺いたいなと思っていまして、今被害想定そのものの見直しが進んでいますので、なかなか現時点でということは難しい面もあるのかなと思うんですけど、まず伺いたいのは、海面からの高さというのは、満潮時と干潮時と、例えば橋はどれぐらいになるのかということと、あと想定される、また想定以上の津波に対してなんですけど。","respondent":"稲田道路公園課長","answer":"橋の高さなんですけれども、これは航路との関係がございまして、大まかに言うと、平均満潮位のレベルがＡＰ２.１ｍという高さなんですけれども、ＡＰ６.０ｍまで空間をとりなさいということがあります。","id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問","question":"この前、宮古市長の話を伺って、やっぱり津波の力というのはすごいなと改めて思ったわけですけど、橋げたとともに、橋自体に加わったときの力というのは、今後やっぱり考えていかなければいけないのかなというふうに思うんですよね。そこについて、実際既に進んでいる工事ではありますけども、どんなふうに考えていらっしゃるのか、課題についてはどう検討していくのか、ご説明いただけますでしょうか。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"この高さにおきましても、今詳細な、〔「津波」と呼ぶ者あり〕津波なんですけれども、防潮堤よりは今高い位置に設置してあるということで、防潮堤を超えるような津波が来るとした場合なんですが。あくまでも橋というのは、上に２５ｔのトレーラーのような車が目いっぱいつながった場合でも十分な強度を持てるような設計しかしていませんから、ですから、横方向から波がドーンと押し寄せるようなものが来るなんていうことは。","id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問","question":"いわゆる科学的に示された橋への影響をちゃんと調べて対応を考えていくと、そういう検討というのは必要ではないかと思うんですけども、その点はどんなふうにお考えですか。","respondent":"岩田都市環境事業部長","answer":"例えば、過去世界で起きた最も大きい地震が東京直下で起きたときでももつようなビルをつくれと言われますと、できるんです。コンクリートの真四角なやつで、人間が１人で中に座れる程度のものしかできないんです。","id":"exchange-003"}]},{"id":"topic-02","title":"大崎駅西口地区および周辺地域におけるまちづくりの現況","agenda":"大崎駅西口地区および周辺地域におけるまちづくりの現況","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"それと、西品川一丁目地区ですけれども、環境アセスメントが今進んでいるわけですが、環境影響評価書、調査計画書を見ると、高さ１１４ｍのオフィスビルと高さ１０４ｍの住宅、４０６戸、これをつくる計画ですけれども、なぜこれが必要なのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"それから二つ目の西品川一丁目地区ですけれども、こちらは必要性ですが、これにつきましては、昨年、都市軸整備構想ということで当建設委員会でもご報告を差し上げておりますけれども。","id":"exchange-004"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"あわせて、広町一丁目周辺地区のことですけども、その他の地区、特に北側のほうですけれども、ここで中小企業の方々が仕事をされたり、そこで生活をされている方もいらっしゃるわけで、そうした方の生業と生活の場についてどう位置づけていらっしゃるのか、やはり引き続きそこでものづくりができるようにしていくことが大事だと思うんですけれども、そこの位置づけについてはどうお考えなのか。","respondent":"三宅都市開発課長","answer":"そのような中で、企業を経営されている方が継続しやすいような形で、どのような形がよろしいかということで話し合いを継続していく考えです。","id":"exchange-005"},{"speaker":"中塚副委員長","kind":"質問","question":"そのニーズは一体どこにあるのか。そこを伺いたいと思うんですね。それがなぜ大きくなるのか。そこを伺いたいと思います。ニーズはあると言いますけど、どこにあるのか、今後の需要をどう考えているのか、たびたび伺いますけど、あわせて伺いたいと思います。だから、保育需要についての責任は、品川区は責任を果たすつもりなのか、どうお考えなのか伺いたいと思います。","respondent":"三宅都市開発課長","answer":"１点目ですが、副都心だとなぜ建物が大きくなるかという件ですが、やはり利便性が高い場所ですし、それだけのニーズは確実にあると見込んでおります。そういう人がたくさん集まる場所ですので、より道路ですとか公開空地ですとか、そういった公共的な空間が必要になってくるです。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"意見","question":"結局まちづくりと言いながら、そこに住んでいる方々の地域への思いやまちへの思いや、そういうものは置いといて、区のほうからここはこういう地域だから大きくしようと、それはとても住民本位のまちづくりとは言えないと思います。しっかりと行政の責任とまちづくりというのであれば、保育園に対しても区が責任を持って行うべきだと思いますので、こうした事業は見直すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"武内委員","kind":"意見","question":"１点だけなんですけど、大崎駅の西口地区と西品川一丁目地区の百反坂を挟んだ間の地域の方々、ほかが再開発のような感じで来ていますけども、そういう中で、もちろん反対の人もいるんだろうけども、逆に周りがそうなっているので、自分たちのところも、みたいな気運というのはあるのかどうか。これはわからなければ結構ですけど。","respondent":"三宅都市開発課長","answer":"実は、少し動きがございまして、そういうことを勉強したいという声がございまして、ご相談を最近受けたところです。","id":"exchange-008"},{"speaker":"井上委員","kind":"質問","question":"線路のところで、補助１６３号線の、自転車なんかが通っていても、一方でイルカの絵がかいてある、あそこですよね。すごく危険な地域だと思うんですけど、あれはどういうイメージでこれから広げて、ここに一体化というのがかいてあるんですけど、それはどういうふうにイメージをしたらいいんでしょうか。","respondent":"三宅都市開発課長","answer":"実は北品川、今度駅の東側ですが、こちらでも帰宅困難者の受け入れをどうするかということでお話し合いをしておりまして、今後これから動いていく、あるいは動いている地区につきましても。","id":"exchange-009"},{"speaker":"井上委員","kind":"意見","question":"コミュニティといいながら、コミュニティのないところにこういう大きなまちをつくっていこうと覚悟してやっていくんだからと、こんなに高くしなくても、床面積とか、採算を合わせようとするとこうなるかもしれないけれども、住んでいる人たちのことというのは、これから入ってくる人たちというところを本当に慎重に考えなくちゃいけないということだけは、考えてはいらっしゃると思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-03","title":"百反ずい道付近道路整備事業","agenda":"百反ずい道付近道路整備事業","exchanges":[{"speaker":"松澤委員","kind":"質問","question":"百反ずい道歩道整備ということで、下の(2)ですけれども、一方通行にする、そして歩道を新設するということですけど、この歩道の広さ、ここに自転車も通すんですか、その辺を１点聞いておきたい。","respondent":"三宅都市開発課長","answer":"歩道は、全体の幅員を変えずに２.５ｍを確保する予定です。今のところ、自転車も通す想定でおります。","id":"exchange-011"},{"speaker":"松澤委員","kind":"質問","question":"２.５ｍなら当然自転車ですから相互に通すわけですよね。これは一方通行になっていますけど、自転車も一方通行という考えなんですか。そこをちょっと聞きたい。","respondent":"三宅都市開発課長","answer":"自転車につきましては、一方通行ではないというふうに考えております。","id":"exchange-012"},{"speaker":"松澤委員","kind":"意見","question":"それを気をつけてもらいたいというのと、あとこっちから一方通行にして、ここはバスが通りますよね。このときに相当大きく曲がっているので、歩道が邪魔にならないのか、その辺は当然検証してあるんでしょうね。","respondent":"三宅都市開発課長","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"それと、今まで右折できた部分、こちらのほうに工場なんかがありますよね。その人たちへの説明というのは十分にしているんですか、これからしていくんですか。その辺を聞いておきたい。","respondent":"三宅都市開発課長","answer":"その中に、やはりお二方から遠回りになって、役所側といいますか、第一三共のところに入ってくるときに不便になるということでご意見をいただいておりましたが、百反ずい道の安全向上のためにちょっとご不便をおかけしますが、ご理解いただきたいということで。","id":"exchange-014"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"そう言いながら、この裏は会社関係の人しか、個人の住宅の方もいらっしゃるのか、権利関係はどういう状況なのか伺いたいのが一つと、それと、これが完成しますと、今ある百反歩道橋はとってしまうことになるんでしょうかね。そうすると、中に残る中州みたいなところというのは、その後将来どうなっていくのか、ご説明いただきたいと思います。","respondent":"三宅都市開発課長、岩田都市環境事業部長","answer":"もう一点、補助１６３号線の中州部分、現在の百反歩道橋の階段があるところですが、こちらは新しい百反歩道橋ができた後に壊しまして、そこは立体的に飛び出すものはない形には考えております。これはずい道のところの図面を見ていただければわかるんですけど、これは一般的な交通島というやつで、ここは自由に車が行けるようになると、上ってくるのと下ってくるのがふくそうしますから、非常に危険ですから、今の交通島の状態で。","id":"exchange-015"},{"speaker":"武内委員","kind":"質問","question":"自転車はここを基本的にというお話なんですけど、例えば私が行くときは車道を通っていく、車道というか、歩道がないから車道を通っているんだけど、両方自転車は通っていいという考え方なんですか、それとも基本的には危ないので、歩道が新設されたらそっちを徐行するのか、その辺は、ちょっと警察との話し合いもあると思うんだけど。","respondent":"三宅都市開発課長","answer":"歩道につきましては、今は段差をつけるという形で考えております。２点目の自転車の通行の方向ですが、警察と今まさに、特にトンネルの部分ですね、あそこは自転車通行禁止ができないかということで、警察にその方向で協議をしております。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"ここを通って役所に行くというそこが危険で、補助１６３号のところをどこをどう、反対側を通っていけばそのまま行かれるということなんだけど、百反に行くほうには怖くて行かれないなみたいなところもあるんですけど、そういう利用者はいますが、そこはどういうふうにここを通って役所のほうに行くルートが、自転車の場合にはあるんでしょうか。","respondent":"三宅都市開発課長","answer":"次の報告になるんですが、次の資料の裏面をご覧いただきたいんですが、新しい百反歩道橋の階段は真ん中がスロープになっていて、自転車を押しながら上れる形になっているのとあわせて、あと両側にエレベーターがついてありますので、ずい道を通らずに。","id":"exchange-017"}]},{"id":"topic-04","title":"山手線大崎駅構内百反歩道橋架替事業に伴う工事委託","agenda":"山手線大崎駅構内百反歩道橋架替事業に伴う工事委託","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"要望というか、どこまで入り切るかなんですけど、エレベーターは自転車を乗せられるということなんで、第一京浜の大森海岸のところ、大田区側なんですが、エレベーターがあって、あそこは自転車を入れられなくなっているので狭いんですけど、ちゃんと自転車を折らないでも入れるような感じで考えると思うんですけど、自転車も今いろんな種類が出ているので、つくったのはいいけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問","question":"今の自転車のことですけど、一度に何台乗るのか伺いたいと思います。委託金額は約１５億円弱ですけど、内訳ですか、補助金の関係ですけど、だれがどこにどういう負担をするのか、その内訳を伺いたい。","respondent":"三宅都市開発課長","answer":"約１５億円の財源ですけれども、約５億円が国費、そして約５億円が大崎駅西口の開発４事業者からのご負担、そして残りは財政調整交付金などで入ってくるという考えです。","id":"exchange-019"}]},{"id":"topic-05","title":"国文学研究資料館跡地整備工事","agenda":"国文学研究資料館跡地整備工事","exchanges":[{"speaker":"武内委員","kind":"質問","question":"１点だけ、通常、よく防災機能を持たせた公園整備のときに、かまどベンチなんかをやる場合があるんですけど、ここはあえてやっぱり火事とか、そういうのはあれだということでやらなかったのか、そういった声が出なかったのか、その辺だけ教えてください。","respondent":"武藤都市整備下水道課長","answer":"説明の中では省いてしまいましたけれども、かまどベンチも公園の中には設ける予定です。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問","question":"防災井戸を１基つくることになっていますけども、どこなのか。これというのは掘るんですかね。それとも既に井戸があるものを活用するんですかね、ちょっとその辺がわからないので、場所とどんなふうにやるのか伺いたいと思います。そういうものというのは、あわせてここに常備されているのか、それとも別のところから持ってくるとか、どういう仕組みになっているのか伺いたいと思います。","respondent":"武藤都市整備下水道課長","answer":"１点目の井戸の位置につきましては、お手元の資料にありますが、ここに災害用トイレ工と矢印で示しているところがありますけれども、その図で言うと直上のあたりに井戸を新たに設置する形で設ける予定です。","id":"exchange-021"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"今の三井文庫、要するにその建物を何とか活用できないかということなんでしょうか。大きさからすると、いろんなものが入るんだと思いますけれども、どんなふうにそこの活用を考えているのか、全体像というか、概要をご説明いただきたい。","respondent":"武藤都市整備下水道課長","answer":"先ほど申しましたように、災害のいろんな資材とか、いろいろ備蓄するもの、そういったものを今ここに設置することを考えています。それについては、またさらに整理する中で具体的に何をこの中に入れるかというのは、検討してまいりたいと考えています。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問","question":"今、井戸の話が出ましたけれども、水源、つい二、三日前に公開したので見たんですけど、ほんのチョロチョロですよね。ですから、常に水があるようにしてもらわなくちゃいけないんで、自然水が使えればいいけども、本当に使えるかどうかわからないので、その辺は慎重に検討してください。あれも歩道にしてくれるんですか。ここは実際に２６号線が通って、こっちの学校側ですよね。","respondent":"武藤都市整備下水道課長","answer":"ただし、その水量等を引き続き見極めつつ、それを十分に活用できるよう整備に当たってもまずして、まずはそういった自然の形の湧水というものの活用を考えていき、委員のご指摘にあったように井戸の形についても引き続き検討してまいりたいと考えています。","id":"exchange-023"},{"speaker":"武内委員","kind":"意見","question":"そこを場合によっては災害用のものを中に入れたいという考えもあるんだけど、ただ、万が一耐震性がないので崩れちゃったら、せっかく入れていた備蓄品が使えないということも考えられるんじゃないかという気がするんだけど、そうすると、場合によっては広いスペースなので、倉庫を別に設置して、その中に入れたほうがいいんじゃないかという考えもあると思うんだけど、その辺はどういうふうに考えて。","respondent":"武藤都市整備下水道課長、片田防災まちづくり事業部長","answer":"非常に弱いという状況ではないというふうに聞いていますけど、ただし、その辺の耐震性の部分が非常に難しいということなので、現状、人を入れるということは考えていないんですけど、やはり学者の方ともいろいろ意見を交わす中では。東京工業大学の先生なんかに現地を見ていただいたりしながら、建物自体は建築基準法ができる前、昭和２５年以前の、基準というものがない時代に建てられたので。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと一言だけ。備蓄倉庫にということでお話を伺っています。歴史的に非常に重要なのであれば、備蓄倉庫の使い方というのもいろいろな部分で考えていかなきゃいけないと思うんですけれども、どのようにあの三井文庫というのを区では位置づけというか、考えていらっしゃるのか、ちょっと教えてください。","respondent":"武藤都市整備下水道課長","answer":"歴史的価値につきまして、先ほど説明しました東京工業大学の先生とも話す中で、いろいろ調べさせていただいたところ、当時の三井家が資料倉庫として、やはり耐震性のあり方を、当時、大正期に、ほかでは、ほとんど見られないような形で耐震性を検討したということがまず１点。","id":"exchange-025"},{"speaker":"大沢委員","kind":"質問","question":"それで先ほど備蓄倉庫というふうにお話を伺ったんですけれども、単なる備蓄倉庫ではなくて、備蓄倉庫のあり方、要は外からも閲覧できるような、いわゆるそれだけの価値があるんであれば、歴史館じゃないんですが、そういう備蓄のものを展示するような、使い方も考えられるんですが、確かに人の出入りはあまりさせたくないというご意見を伺ったんですけど、何かもうちょっと歴史的な価値があるのであれば。","respondent":"武藤都市整備下水道課長","answer":"まさに委員のおっしゃられるとおり、ただ単に物を置くということだけではなくて、先ほど申しましたように、やはり防災上の観点からも耐震性の補強とか、そういった観点からも非常に歴史的価値があるということで、まずこの公園の整備に当たっては、さくで囲ってしまいますが。","id":"exchange-026"},{"speaker":"松澤委員","kind":"意見","question":"今の件ですけども、実際に今現状、中がどうなっているかというと、中は網の目のようにはりで崩れないようにしてあるという話を聞いているんですね。私は見たことがないんですけど。そういうのから考えると、本当にあれを耐震補強したら相当お金がかかるんじゃないかと思うんですよ。将来的に考えたら、ないほうが公園としてはいいのかな、よっぽどいいと思うんだけど。現実をちょっと、現状を話してください。","respondent":"片田防災まちづくり事業部長、稲川委員長、武藤都市整備下水道課長","answer":"ただ、今の基準に合わないというところもありますけれども、人を入れるということは難しいですが、そういう歴史的なところとか防火性とか。ほかになければ、本件を終了いたします。引き続きまして、これら雨水対策関連事業につきましてＰＲを強化するなど周知の徹底を図り。","id":"exchange-027"}]},{"id":"topic-06","title":"治水対策関係事業の実施状況","agenda":"治水対策関係事業の実施状況","exchanges":[{"speaker":"井上委員","kind":"質問","question":"公共施設の雨水タンクなんですけれども、毎年４カ所ぐらいずつ進んでいると思うんですけれども、最終的にはどのくらいまで可能性があって進めていこうというものなのか、数をどういうふうに見込んでいますでしょうか。","respondent":"武藤都市整備下水道課長","answer":"全体におきまして、浸透施設につきましては、降った雨の約１割を浸透させる計画で進めておりまして、おおむね公共施設につきましては、今ちょっと正確な数字がなくて申しわけございませんけれども、それの７割ぐらいが設置しておりますので。","id":"exchange-028"},{"speaker":"井上委員","kind":"意見","question":"つくって、その後利用しないともったいないんですけれども、そういったメンテナンス、啓発の意味でどういうふうに利用したらいいとか、そういうところの働きかけがちゃんとできているのかどうかが心配なんですけど、その辺はどういうふうにやっていますか。","respondent":"武藤都市整備下水道課長","answer":"活用の状況も今正確に全部ヒアリングしたわけじゃないんですけれども、つけたところにつきまして、幾つか我々としましても確認したところ、十分に使っているところと使っていないところがあるようでして、それは設置の位置だとか、使いにくい場所にあるだとか。","id":"exchange-029"},{"speaker":"井上委員","kind":"意見","question":"資源としては十分に活用できるものなので、推進とともにそういった、つけただけではない、後のフォローもしっかりとお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"中塚副委員長","kind":"質問","question":"なぜなら、この雨水利用タンクだったり、浸透ますだったりは大事な事業だと思っていまして、思い切って進めていく方向が大事だなと、今回も充実をしたわけですけども、そういう意味で１割というのがどういうことなのかなということを伺いたいと思います。なので、増えた要因を区はどんなふうにお考えなのか改めて伺いたいと思います。","respondent":"武藤都市整備下水道課長","answer":"あわせまして、そういった計画なんですけれども、これにつきましては、東京都のほうで定めました総合治水対策という計画の中で将来的に１時間１００mm程度の雨に対応できることを目標とする中で、そのうちの１割、約１時間で１０mm分につきましては。","id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問","question":"一定規模のマンションですと、屋上にかなり雨も降りますし、マンションの震災時を考えると、電気がとまって水が上に上がっていかない、いろいろな問題を抱えるわけですから、建物だったり、そういうものに対しても、別に支援を強めていくとか、そういう誘導策もあっていいのではないかなと思うんですけども、今一律ですけど、建物に応じて上乗せをしていくと。","respondent":"武藤都市整備下水道課長","answer":"そういった促進策につきましては、委員のご意見も含め、今後も検討してまいりたいと考えています。","id":"exchange-032"},{"speaker":"武内委員","kind":"質問・要望","question":"今のに関連するんですけど、３番のところで、平成２３年９月より工事費用の全額を助成する制度を開始したとあるんですが、これについての今の段階での件数をちょっと教えていただきたいのと、あとこれが今、課長のほうで最後にご説明いただいたものだと思うんですけど、そうすると、昨日ご説明いただいた目黒川とか立会川、そういうものの浄化にも役立つわけですね、この新しい事業は。","respondent":"武藤都市整備下水道課長","answer":"ご質問の３番の雨水流出抑制推進事業における宅地内の助成の実施状況なんですけれども、現時点におきまして、実際の申請は残念ながら１件もございません。今１件相談しているところはありますけれども、申請はないような状況です。","id":"exchange-033"},{"speaker":"武内委員","kind":"意見","question":"私が言ったのは、目黒川とか、そういうものの浄化にも役立つのか、その辺だけを手厚くしろという意味じゃないんですけど、それにもし資するんであれば、その辺の方向を踏まえた上で、ちょっと集中的にやったらどうかということなんで、その辺は。","respondent":"武藤都市整備下水道課長","answer":"委員ご指摘のとおり、そういった効果がありますので、特に河川沿いだとか、そういった部分には効果があると思いますので、ＰＲする場合に当たってはそういったところを重点的に行うなど検討していきたいと考えております。","id":"exchange-034"},{"speaker":"大沢委員","kind":"確認","question":"確認をさせてもらいたいんですけど、１番目の雨水利用タンク設置助成で、購入費は４万円から５万円ということなんですけど、設置費用に関しては１万５,０００円の限度額ということで、事務事業概要には載っていますけど、これについては書いていないんですけども、どういうふうに考えているんでしょう。","respondent":"武藤都市整備下水道課長","answer":"現在この制度は事務事業概要に書いてあるとおり設置工事費につきましては１万５,０００円で、今年度拡大してきたところ、一定程度その金額が合えば申請者の申請する額に十分に助成できていると認識しておりますので、引き続きこの形で事業を進めていきたいと考えています。","id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"これは委員会の資料なので、ただし書き１万５,０００円云々というのは必要じゃないんですか。それとも変わったんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"本委員会の資料で、申しわけございません、そこまで詳しく記載していないのは、おわび申し上げます。これにつきましては現状と同じ、おっしゃるとおり設置工事費の助成額は、１万５,０００円が上限です。","id":"exchange-036"}]},{"id":"topic-07","title":"立会川雨水放流管整備事業","agenda":"立会川雨水放流管整備事業","exchanges":[{"speaker":"高橋委員","kind":"質問・要望","question":"要望なんですけれども、この事業については、地域の浸水等で大変効果的な施策なのでぜひお願いしたいというところをやっとできたので大変ありがたいんですが、月見橋周辺は全く住宅地ですので、工事中の安全確保と、あと先ほどの関係のところも含めて地域の方々に十分説明していただいて、十分ご納得いただいた形で進めていっていただきたいと思います。要望で、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"武内委員","kind":"意見","question":"２点あるんですけど、１点は同じようなシールド工事で、この間ほかのところで、何か水が入っちゃって人が亡くなったりした事故がありましたよね。","respondent":"武藤都市整備下水道課長","answer":"２点目の立会川における水門の整備につきましてですけれども、これも委員ご指摘のように立会川については高潮対策が必要となっていることから、東京都のほうで河口部に高潮対策として水門の設置を検討しています。ただし、水門を設置するためには河川の流れ、洪水をまず処理する。","id":"exchange-038"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１点伺いたいのは、月見橋付近の計画のことについてなんですけれども、まず関ヶ原児童遊園の位置が変わりますけれども、面積的には同じなのかどうなのかを確認させてください。あわせて、復旧移転、もとに戻ってくるときですけれども、今と同じ施設を考えていらっしゃるのか、ちょっと大分先の話にはなりますけど、どんなことを今戻ってくるときに考えていらっしゃるのか伺いたいと思います。","respondent":"武藤都市整備下水道課長","answer":"２点目の区の施設の仮移転先なんですけれども、公園としましては、現在移転する施設の状況等を考えながら、鈴ヶ森公園を予定しているところでございまして、今、関係機関の調整をさせていただいているところです。","id":"exchange-039"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この公園の整備と移転にかかわって、周辺の方々のこともそうですけど、住民説明会、工事説明会というのは、いつごろというふうに考えていらっしゃるのか。鈴ヶ森公園のどこにどう移転するのかよくわからないんですけど、例えば広いグラウンドであれば、そこを利用されている方々もいらっしゃるわけで、それへの説明と理解も求めるわけで、そういうのはどういうスケジュールでお考えなのか、１点伺います。","respondent":"武藤都市整備下水道課長","answer":"全体の事業の説明会ですけども、先ほどの説明の中で申し上げましたとおり、この資料５、スケジュールのところに書いてありますけど、３月２７日にこの説明会を開催する予定でおります。","id":"exchange-040"}]},{"id":"topic-08","title":"補助１６３号線整備事業（II期）の完了","agenda":"補助１６３号線整備事業（II期）の完了","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"この事業に商店街の継続といいますか、発展というか、その位置づけは何だったのかと思いますので、その点をどうお考えなのか伺いたいと思います。もともと何店舗あった商店が、道路と隣の開発が完成した後でいいですから、何店舗戻ってくるのか、どう位置づけているのか、そこを伺いたいと思います。過去の交通事故の実際を見ましても、非常に事故が多い。それについてどうか。","respondent":"武藤都市整備下水道課長","answer":"１点目の現在整備区間の商店街につきましてですけれども、これまでも事業に当たっては１０回以上にわたる説明会を開催する中で、地元と意見を重ね道路整備に当たってまいりました。","id":"exchange-041"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その上、整備に伴って交通量が増えるわけですから、やはり歩行者と車のまじわらない、歩車分離の信号機にしっかりと位置づける、そういう歩行者の安全対策が必要ではないかと思うんですけれども、そこをどう位置づけていらっしゃるのか伺いたいと思います。","respondent":"武藤都市整備下水道課長、片田防災まちづくり事業部長","answer":"引き続き整備完了後もこういった都市計画道路の効果を含め、ご理解を得ていきたいと考えています。補助２０５号線の安全の対策の件ですけれども、交通管理者と整備につきまして協議をしていく中で検討してまいりたいと考えています。それとあと、補助１６３号線だけ、あるいは補助２０５号線だけの話ではなくて、大井町のまちづくりのビジョンの中で、区としてもやはりいろんな地域の商店街の連続性の話もありましたけれども、やはり補助１６３号線沿いのところ。","id":"exchange-042"},{"speaker":"高橋委員","kind":"質問","question":"３月に完了というんですけど、本当に３月に終わるんでしょうか。終わらせなければいけないとすると、例えば日曜日に工事をしたり、夜７時、８時、９時、１０時にやったりする可能性が果たしてあるのか。もしある場合は、地域の方にやはりご説明して、年度末に終わらせなきゃという部分も、いろいろあると思うので、その辺についてはいかがなんでしょうか。","respondent":"武藤都市整備下水道課長","answer":"現状も地域の方々の意見も踏まえながら、土曜日だとか日曜日にも施工させていただいているところでございまして、今後やはり工事ですので、どういった事態があるかわかりませんけれども、仮に例えば工事時間帯を延ばす必要があるだとか、土日の工事が連続でつながるだとか。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/274500?Template=document&Id=4032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":34575,"voices":134}},{"id":"h24-20120228-9","meetingId":"h24-cm02","date":"2012年2月28日","dateIso":"2012-02-28","committee":"文教委員会","time":"午前１０時００分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","topics":[{"id":"topic-01","title":"平成２３年度品川区教育委員会事務事業の点検および評価報告書","agenda":"平成２３年度品川区教育委員会事務事業の点検および評価報告書","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"結構詳しくいろいろ載っているので、とても興味深く読ませていただいたのですが、ちょっと幾つかわからない点も含めてお伺いいたします。(2)の5)と6)のところの質問なんですが、５ページの5)の教職員の研修のところで、２行目に「研修の民間への委託化」と書いてありますよね。この辺の中身はどういうことなのか、もう少し具体的に教えていただきたいのが１つです。Ｃですね。","respondent":"冠木指導課長、中元品川図書館長","answer":"研修というのは、もうねらいを絞って、必要なところに必要な研修をというのが基本でございまして、議論の中では、例えば私ども、中堅の教員のスキルアップをするために。私のほうから図書館の運営についてのところですが、まず、こちらの文章にあります低コストでというところにつきましては、大井図書館の窓口業務委託等、従来から窓口業務等委託していますが。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育委員会に寄せられたご意見は、研修のところはこういったご意見がありましたという説明なんですが、今まではあまりそういう部分は拡大されていなくて、これからやっていったほうがいいのではないかというご意見だったのか、今までやられていて、実際どうだったのかというあたりの評価があって「さらに」なのか、ちょっとそこを教えていただきたいのと、あと、図書館のところは。","respondent":"冠木指導課長、中元品川図書館長","answer":"研修の件ですが、これまでもそういったＮＰＯであるとか民間のお力をおかりして、例えば新規採用教員の研修の一コマにそういうような研修の機会をつくって成果を上げてまいりましたので、一応。私どもとしましては、サービスを提供する上で、正規職員が行うよりも、民間事業者によるほうがコストが確かにかからないという部分は、今までの委託の流れの中で検証してまいりました。実際にサービスのレベルも維持しております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"1)と3)のところをお伺いしたいのですけれども、1)はプラン２１の新たなステージアップということで、第４ステージのことが書かれています。義務教育の質の向上を図ってきたし、さらに進めるようにというところでは、ここにおいては共産党と大いに見解を分かつところなんですけれども、この辺は教育委員の皆さんの中に異論はないのでしょうか。その辺をまず先にお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"異論は特にございませんでした。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、教育委員会の、議会もそうですけれども、さまざまな意見が出て、意見をお互いに交わしながら問題点を改善していくことがよりよいことになると思います。明らかに格差はあると思うんです。やはり公教育の中での格差をどうしたらいいのかという議論をやはりこういう場でしていただかないと、よくならないと思うんです。横に首を振っていらっしゃるので、お答えをいただきたいと思います。","respondent":"田村教育次長","answer":"そういう方も含めて、先ほど庶務課長が答えたように、特にこの第４ステージについてはぜひ進めてほしいと。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"一体化のところでやっていること自体を連携校の中で分離型のところに持っていっている困難さは、本当に子どもたちにも、先生たちにも、交流は大事、連携は大事だけれども、今の現状の地理的なことも含めてすごく困難だとおっしゃっていて、あとの健康面にも触れますけれども、ただでさえ忙しい中に新しいことをやっていくということで大変な多忙さを感じていらっしゃるというんですけれども。","respondent":"若月教育長","answer":"先生の会派の方からよく同じ質問を何年も何年も繰り返して何の進歩もないんですが、この前提としてよく考えていただきたいのは、いいですか、小中一貫教育にしても、学校選択制にしても、少しでも子どもたちによりよい学校の場を提供しようということで頑張っているわけですね。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"提案","question":"私たちは、子どもの成長・発達の段階に合っていない改革である、子どもたちの現実をしっかり見た改革をしてほしいということで、この間、提案をしているんです。ただ、やめろ、やめろと言っているのではなくて、提案を繰り返しています。なので、提案しているつもりなので、反対だけの反対という、そういう一方的なとらえ方はしていただきたくないと思います。質問だけじゃないんですよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ご意見があったら、どうぞ。ないんですね、わかりました。教授がこれだけ取り上げるくらい、やはり全体的な状況において先生たちが長時間、私たちは長時間過密労働だと思っているんですけれども、体調を崩されている、本当にゆゆしき事態だという受けとめ方をしているんですけれども、区教育委員会はこの辺をどんなふうに把握して評価をしていらっしゃるのかというところをまず先にお伺いしたいと思います。","respondent":"齋藤庶務課長","answer":"全国のお話を伺いましたので、区の現状をご説明申し上げます。教職員、大体９８０人前後おります。平成２０年度から病気休職をとったもののうち、メンタルヘルスの職員数、平成２０年度１０人、平成２１年度１０人、平成２２年度９人、今年度５人です。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"メンタルヘルスだけだったのですが、病休者の数を教えてください。","respondent":"齋藤庶務課長","answer":"平成２１年度１２人、先ほど申し上げた１２人のち１０人がメンタルヘルス、平成２２年度９人、うち９人がイコールメンタルヘルスでした。平成２３年度が８人おりまして、うち５人がメンタルヘルスだです。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"意見","question":"精神面で体調を崩していらっしゃる方はかなり高い比率ですね。病休者の中で精神面に偏っているあたりでは、どういうふうに評価をされているのか。","respondent":"齋藤庶務課長","answer":"区長部局における職員との比率、他区の教職員との比率で言うと、発現率は低いです。ですから、品川区の教員は他の自治体の教員よりもメンタルヘルスでの発症率は低い、今日は数字は持ってきておりませんけれども、全国との比較においても低いということです。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"新しい教育改革の中で、大変ご多忙の中で低いというのは、すごいなと思いますけれども。学校の先生たちは、時間のチェックは一番には時間の管理が大切と言われているんですけれども、現状はどういうふうになっていて、勤務時間外でどのくらい働いていらっしゃるのでしょうか教えてください。","respondent":"冠木指導課長","answer":"そういうようなところを含めて、月２０時間程度の時間外のお仕事をされている方が多いという状況はつかんです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"質問","question":"特に小中一貫校などはすごく報告の書類も多いという話も聞くのですが、特に多いところはないのかどうか、その点と、あと、教授のところで学習評価の活動とか、部活動とか、個別の指導とか、保護者の対応、増大する事務作業がやはり具体的に改善をされなくてはいけないような書かれ方をしているんですが、この辺の具体的な改善は行われているのでしょうか。","respondent":"冠木指導課長、田村教育次長","answer":"私からは時間の件ですけれども、先ほど申し上げましたように、行事の前だとか成績処理等々で、期間を絞って時間外でお仕事をされる時間があるということは聞いておりますので。で、今議論されている２０時間云々というのは、タイムカードに打刻した時間を言っているのであって、この４項目に該当して超勤命令を出して打刻したのは超勤扱いですけれども、それを前提で議論しても、まずその徹底を。","id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問","question":"それを、何か法令ではどうのこうのと四角四面に、その部分はわかっています。でも、だれもが見ても先生たちは疲れ切っているし、過重で長時間労働があるという認識をどれだけ持っていて、そこを何とかしようという思いがあるのか、いや、２０時間でそんなじゃないんですとはね返してしまうのか、私、そこの違いではないかと、すごく今、今日のお答えを聞いて感じてしまいました。","respondent":"田村教育次長","answer":"ですから、その部分を正規職員ではなく非常勤だとか、そういうものでの対応をしているということでご理解いただきたいと思います。","id":"exchange-012"},{"speaker":"須藤委員","kind":"意見","question":"あれとはまた別の仕組みでこれをやっているのかどうかということが１点と、それから、これを調査・評価するのは、どういった仕組みで、最終的に教授が何か見てアドバイスという話をいただいたんですけれども、どのくらいのメンバーがどういう仕組みでこの事務事業評価をつくってきているのかが１点です。そのあたりはどんなふうにされているのかという思いがちょっとしているので、お聞かせください。","respondent":"齋藤庶務課長","answer":"お一人は長く地区委員を携わられた実業家の方、弁護士、医師、校長のＯＢ、この方々が、事務局が説明させていただいた事務事業について先ほどの識見に従って意見を述べていただきます。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問・要望","question":"そうすると、やっぱり地域と学校が一つの塊になってこようかと思うので、今の「プラン２１」をさらに進展させていって、区民の期待にこたえてもらうようにこの事務事業評価でいろいろやってきて、さらに進展していただきたいと思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"阿久津委員","kind":"質問・要望","question":"何点かお伺いしたいのですけれども、まず、１点目が１３ページの３９番のちょっと個別の評価になってしまうのですが、教職員住宅の維持管理ということで、昨年の事務事業評価もインターネットから引っ張り出して拝見させていただいて、同じくＣ評価ということで２年連続Ｃ評価ということになっているんですけれども、この１年間、事業をされて、どうしてこういう評価になったのかということ。","respondent":"冠木指導課長","answer":"ここに書いてありますけれども、教職員住宅は、今、２棟あるんですけれども、１棟のほうが古くなってきたというようなことも踏まえまして、今後どういうふうにそういった教職員の住宅を確保していくかということで、今、当然。","id":"exchange-015"},{"speaker":"阿久津委員","kind":"質問","question":"教育委員会が把握している部分でもいいんですけれども、職員の方の住宅の耐震化はどうなっているのでしょうか。","respondent":"冠木指導課長","answer":"当然、建築したときの耐震基準はクリアしておりまして、そういう状況ですけれども、当然、老朽化してまいりますと、新しい建築基準ができてまいりますから、それとの照合を、今、図っているところでございまして、古いほうについては古いままですので、そのままということです。","id":"exchange-016"},{"speaker":"阿久津委員","kind":"提案","question":"一般的な話しかちょっとできないんですけれども、本当に教職員の命にかかわることですので、その辺も見直すということでいただいていますので、ご提案いただきたいと思っています。","respondent":"冠木指導課長","answer":"これは、Ｃのとらえ方でございまして、当然、事業の必要性はあると私どもは思っていますし、教育委員方もそういうような認識でございましたので、Ｄ（廃止）と、そういうことではなくて、事業の必要性はあるけれども。","id":"exchange-017"},{"speaker":"阿久津委員","kind":"意見","question":"わかりました。私も今回初めて事務事業評価を拝見させていただいて、思いは一緒ということでご説明があったんですけれども、Ａのほうがやっぱりよくて、Ｃのほうが悪い、そういうイメージでとらえがちだったものですけれども、そういうものではないということが今のご説明でよくわかりました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"ちょっとまた確認させていただきたいのが、教授が６月１４日の教育委員会にてこの教職員の健康管理とＰＴＡの支援事業についてということで依頼があって、この文書を、すみません、先ほど私は聞いていなかったと思いますが、いつこの文書が教授から教育委員会に出されたのかと、それを受けて教育委員会でどのような話し合いがどういうタイミングで持たれたのかというところを先にちょっと教えてください。","respondent":"齋藤庶務課長","answer":"今年の１月２４日にこの文書をちょうだいして、１月２４日の教育委員会の場で委員の皆さんにお示しをしております。で、一定期間、ご議論いただけませんかとか、そんなやりとりをいたしまして、最終的には２月１４日で取りまとめをしたところです。","id":"exchange-019"},{"speaker":"渡部委員","kind":"質問・要望","question":"教育委員会で点検された中で、１つ感想なんですけれども、うれしかったのは4)のところ、「地域への情報発進に努めること」というところを示していただいていて、やはり学校から、いろいろ大変だとは思うんですけれども、地域としてもいろいろ情報発進してほしい、それに対して地域がどうこたえていけるかというのも、地域は地域でこう考えていくのにすごくいい取り組みになるなというところで。","respondent":"和氣学務課長","answer":"これについて省力化するために、私ども、校務システムをつくっておりまして、例えば通知表が毎日の出欠を入れたり、毎日の子どもの記録は全部集約されて通知表に反映するであるとか、その通知表は指導要録に反映するであるとか、そういうシステムを実はつくっておりまして。","id":"exchange-020"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当にいろいろ考えているというか、一生懸命やっていらっしゃるなと、今、思いました。何とか健康診断をしてフォローするのもそうですけれども、物理的に何かできるところ、それで５分でも縮まれば、やっぱりそれはすごい成果だと思いますので、知恵を絞って私たちもいろいろ考えながら、逆にそういうふうにやっていかなければいけないのかなと思いますので、続けていただきたいと思います。","respondent":"齋藤庶務課長、田村教育次長","answer":"例えばまもるっちの例で言うと、今回、機種の切りかえをしますので、システムはどういうシステムになっているか、協力員が１万３,０００人、まもるっちを発報した場合、半径２００ｍの範囲で協力員に連絡がいく。周年行事だとか、卒業式だとか、そういうセレモニーだとか、ＰＴＡ連合会の集まりだとか、そういうのは来賓で行くのですが、なかなか現場の学校へ行けないということで、今、教育委員からも声が上がっていて。","id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"例えばＰＴＡ会費だって、１５０世帯のところと８００世帯のところでは、もう全然異なってくるわけですから、それぞれ学校においてのやり方があるのでしょうけれども、これについては、今後、何か全体的な話として、連合会を通してでも、各小学校に対してでも、これを全部委託事業をやってくださいと言うのではなく、この中でできることをやってくださいですとか、ある程度、単位ＰＴＡといいましょうか。","respondent":"田村教育次長","answer":"小学校ＰＴＡ連合会のほうからも要望があって、おととしからスタートしたのが、せめても区長と教育長と直接お話しする場を設けてほしいと、これは小学校ＰＴＡ連合会から出たんですが、で、もう今年度で３回目を実施した経過があります。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区の教育、いろいろな委員、保護者はいろいろな考えを持つけれども、昨日の陳情、あのような陳情が出るということは、少なくともあそこに署名された方は品川区の教育を理解されている方で何とかしてくれというような陳情が上がっているわけですから、やはり期待していると思います。どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"３点ほどちょっとお聞きしたいのですけれども、いろいろな学識経験者の中で例えばこちらの教授にお願いするとき、教授が品川区に深くかかわっている方なのかどうかをちょっと教えていただきたいということと、それからあと、先ほどお話があった品川区の９８０人の先生の中で、メンタルヘルスでお休みなさっている先生が平成２０年から平成２３年まで教えていただいたのですが。","respondent":"齋藤庶務課長、冠木指導課長","answer":"もう一つは、日本経済新聞の月曜日に教育欄がありますが、毎週、月曜日にコラムもお持ちの方で、この道では大変大家の方で、お願いできるということは品川区の教育に対してのご理解も十分あるということだと考えています。３つ目のご質問ですけれども、小中一貫の中の英語教育およびもう一つ友好都市の関係ですけれども、友好都市の件につきましては、私どもも友好都市を提携している都市から英語の先生をお呼びして。","id":"exchange-024"},{"speaker":"渡辺副委員長","kind":"質問","question":"学識経験者のこのご意見の終盤に、ＰＴＡ活動と学校教育のみならずという視点で地域との兼ね合いの中で教員の評価という点で伺いたいと思います。その点で、今後もこの評価は、逆に私個人とか議会ではなくて、地域の方がとっくに認めている点だと思っています。評価を伴えば、またより頑張ろうというモチベーションの高さにもつながってくると思うのですが、その辺の仕組みとお考えを伺えればと思います。","respondent":"冠木指導課長","answer":"副委員長のおっしゃったような教員の取り組みについては、業績評価の中で、学校経営の参画度という項目がございまして、区の教育委員会であるとか、あるいは学校長の経営方針に基づいてどういった学校経営をしていくか。","id":"exchange-025"},{"speaker":"渡辺副委員長","kind":"質問","question":"その評価の位置づけが、ウエートが高まれば、子どもと接する時間を他教員との兼ね合いもある中でもやりやすさのほうが多いのかなと思ったので、そういうものは地域にというわけではなくて、校内で称えられるとか、そういうことは現状でもあるものなのでしょうか。","respondent":"田村教育次長","answer":"当然、学校も入るというので、ここのところ二、三年、やはり今おっしゃったような顕著な取り組みをしたので、今年もそうですが、教員に絞らせてもらいました。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"任意でありますが、予防注射についての統計があったらお聞きしたいのです。","respondent":"和氣学務課長、吉岡保育課長","answer":"実際にどれだけの子が予防注射をやったかという統計は特にとっておりません。あくまで自主的なご判断ですので、私どもでそこまでは把握してございません。職員についても、職業的に、時期になりますと、子どもさんからも感染者が多数出ますので、職員はかなりの数の職員が予防接種をしているものと思われますけれども、こちらも特には統計はとっておりません。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"本当に任意なんですけれども、これは統計をとるというのも必要なのか、それとも私の経験では、たしか学校でインフルエンザの予防接種をしたらいかがですかみたいにして、したほうがいいんじゃないですかみたいな、たしかそういう書類等が保護者に回ったような記憶があるんですが、その辺はどうなっているのでしょうか、もう一度教えてください。","respondent":"和氣学務課長","answer":"一般的に学校医からそれを呼びかけるというのはありますけれども、私どもは直接教育委員会として予防接種をぜひ受けなさいということは特に言ったことはございません。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問","question":"ここで学校でインフルエンザにかからない小学校、かかっていない、閉鎖になっていない中学校があると思うのですけれども、そういうところは何か理由があるのでしょうか。私の出た旗台小学校、荏原第五中学校では、全然閉鎖になっていないので、地域性があるのかどうか。","respondent":"和氣学務課長","answer":"先ほども申しましたように、単独小学校では１０校が全然出ていない。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問","question":"ここで聞いても難しいのかな、インフルエンザで手洗いをしましょうとか、よくうがいと言われるのだけれども、手洗いは何秒間洗えばいいのかなというので、というのは、昔、何かそれは３０秒ぐらい手をしっかり洗わないと、菌は除去できない、３０秒以上だよという話を聞いたことがあるんですけれども、どの程度というのは、今年、特に寒かったので、お子さんたち、手洗いしなさいと言っても。","respondent":"和氣学務課長","answer":"それで蔓延させているというのもあるので、必ず５日間は来させないということを徹底しないといけないということですが、医者のほうも勘違いして症状が終わったので出ていいよと言ってしまう、そういうケースがあるということで、学校医から内科医に全部そういう申し合わせて。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"今の消毒液、マスクのことは、できる限りの対策で、本当に今回、自己管理みたいなんですけれども、具体的、私もマスクをしたらいいなと思って、ちょっと学校の子どもたちはあまりマスクをしていないで、ひどいときとかは本当に守るのに必要かなと思うんですが、そういった、最低限こうしたらいいよというような広報とか、何か配るとか、そういうことはあったのですか、今回。全員に注意事項とか。","respondent":"和氣学務課長","answer":"これは日常的にやったもので、風邪がはやるときは養護の先生は困ってしまうので、日常的にこういうふうにしなさい、ああいうふうにしなさい、消毒をしなさいというような、特にはやり始めたら、うちのほうで各学校に警戒警報を出しますので。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"この濃淡の違いは何なのか気になったので、教えてください。後半が濃くなっている。","respondent":"和氣学務課長","answer":"１月に発生したものと２月と分けたものです。","id":"exchange-032"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点目は、武内議員の代表質問の中の「保育園の待機児童対策について」で、特に認可外保育園との連携というところと、あと、あまりはっきり聞き取れなかったのですけれども、基準の認可外施設のことだと思うんですが、基準の見直しを図っていくといったご答弁があったかと思うので、ちょっとそこら辺をもうちょっと具体的にお伺いしたいと思っています。","respondent":"伊崎待機児童対策担当課長","answer":"１点目の公明党武内議員の代表質問での認可外保育園との連携の考え方のお尋ねですけれども、認可外保育施設につきましては、基準を満たしており、子育て支援への熱意がある事業者に対しましては、他事業への転換などにより支援を図ってまいりますと答弁いたしました。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認証保育園でない認可外の保育所の基準といったら、東京都のところにある基準でしょうか。まだちょっとよくわからないんですけれども、視野に入っている具体的な部分があるのかどうか。本当にお子さんがこの品川区でもっと生まれてほしいし、大事に育ててほしいという思いからなんですけれども、その見通しについて率直にどう思っていらっしゃるのかというあたりもちょっと聞かせてください。","respondent":"伊崎待機児童対策担当課長","answer":"しかしながら、なかなか見込みがうまく調整がし切れないというところもございまして、来年度、ちょうど乳幼児人口動向の調査を実施するという話がありますので、それに合わせた形で、保育事業につきましてもいろいろな意味で調査を研究していこうと考えているところです。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問・要望","question":"認可外の保育施設のところにおいては、区内に十四、五ですか、お休みしているところもあって、たまに尋ねたりすると、基準に満たないところを直してほしいとか声をかけられるのだけれども、財政的な支援がないので、全くやりくりが大変だという声も受けるのですが、その辺、基準を上げていきたいという思いがあるところに支援がされるのかどうか、ぜひそこをしていただけると。","respondent":"伊崎待機児童対策担当課長","answer":"２点目の保育の需要動向ですけれども、先ほど申し上げましたとおり、今後、人口動向の調査をするということに重ねて、保育の需要動向調査もいたしまして、その上で少しでも働きやすい社会の構築には貢献していきたいと考えております。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/852886?Template=document&Id=4754#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":35026,"voices":105}},{"id":"h24-20120228-5","meetingId":"h24-cm02","date":"2012年2月28日","dateIso":"2012-02-28","committee":"総務委員会","time":"午前１０時００分～午前１１時４５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件抜き出しています。","topics":[{"id":"topic-01","title":"の債権の放棄","agenda":"の債権の放棄","exchanges":[{"speaker":"南委員","kind":"質問","question":"ちょっと担当課が違うので、どこまで聞けるかわからないですけれども、学童の保育料ということなんですが、１年分３万６,０００円なら月３,０００円ぐらいですよね。学童の保育料については、一律３,０００円という保育料が設定されていて、所得にこうして減免だとか、そういうものというのはなかったのか。ちょっとそのあたりのことをもしわかれば、教えてください。","respondent":"福田会計管理者","answer":"第３項によりまして、「区長が特別の理由のあるときは、減額または免除することができる」という規定がありますが、この２件、いずれともその減免規定の適用はないということであります。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"それで、例えば何というんでしょうか、保育料の部分でなかなか払い切れないという、意識的に払っていないのは別ですけれども、なかなか現実的に払えないというふうなことが、もし現実としてあった場合には、指導員のほうに相談をするだとか、いろいろな形になってあらわれてくると思うんですけれども、その辺というのがどの程度紹介されているのかなというのが。","respondent":"福田会計管理者","answer":"そういうことでございまして、原則はこの条例であろうと、ほかの条例であろうと利用料ですから徴収する。徴収するべきものは徴収する。これが大原則でございまして、例外をことさらアピールするということは、通常私どもはないというふうに考えております。","id":"exchange-002"},{"speaker":"南委員","kind":"確認","question":"こういうふうな債権放棄になるような事態を未然に防ぐということで、どういうふうにその辺というのは考えていったらいいのかなということをちょっと私は思ったので、どのように現場サイドではされているのかということをちょっと最後に伺っておきたいと思います。","respondent":"福田会計管理者","answer":"債権管理、債権というのは千差万別でございまして、それぞれ現場が、適切な対応をとっているということでございまして、一律に何かこうしているということは聞き及んでいないところです。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"この２件は別の家庭と思ってよろしいのかということ、それから、先ほどご説明の中で時効が２０年の１２月、１１月と言ったと思いますが、債権の発生日が全く一緒で、どうして１カ月のずれがあるのかということ、この２点を教えてください。","respondent":"福田会計管理者","answer":"債権者が区の場合に、最初の督促によって一たん時効が中断します。これが民民との違いでございまして、その最初の督促を行った日が違う、したがって、中断事由が終わってから時効が始まるというその始期が、最初のときが違う。このことによってずれるものです。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"この学童保育料、これは１７年のものですけれども、１８年以降の債権が残っていらして、今回処理をしたのが１７年分という考え方でよろしいですか。今持っているのが、当面これだけを持っていて、これを処理されていて、学童保育料についての債権で、放棄しそうな対象というのはもうこれで打ちどめ、現在のところではこれだけですか。","respondent":"福田会計管理者","answer":"今具体的に私どもの把握している学童保育料は、大体これで処理が終了するということになります。ただ、債権は生き物ですので、また２４年度にどういう債権があるか、今調査をかけている、そういう状況です。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"この１年間、さまざまな形で債権放棄のご報告をいただいているんですけれども、当然処理されるボリューム、これからもまた出てくるとは思うんですが、全体としてどれくらい、今処理が進んでいるんでしょうか。ざっくりでいいんですけれども。","respondent":"福田会計管理者","answer":"そのほか、放棄ではありませんけれども、徴収を停止している債権、これも条例の規定に基づくものですが、それらも、若干ですがあります。いずれにしても、今申しましたように、債権は増えたり減ったりいたしますので、これからまた放棄の都度に、この委員会にご報告する予定です。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問","question":"私の見る限り、条例ができてこの処理ができるようになったということで、当初かなりの種類と件数がでてきたと思うのですが、当初たまった分というのは、一たん処理が終わって、今後新たに発生する債権放棄対象の債権について、順次処理を行っていくというような段階に来ているんでしょうか。","respondent":"福田会計管理者","answer":"今後新しく発生する債権、これも当然にあります。したがいまして、なかなか全部、例えば年度末で切って、もう収入未済はないという状況に持っていくには、少し時間が必要かなというふうに思っています。","id":"exchange-007"}]},{"id":"topic-02","title":"の平成２４年度都区財政調整","agenda":"の平成２４年度都区財政調整","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"聞きたいんですが、２ページの基準財政需要額の部分で経常的経費というのが今年度も増加、微々たるものではありますが、収入、財政がきつい、厳しい中で増加ということなんです。この辺の内訳、どの辺のものがやっぱり増えてきているのかというのを教えていただきたいと思います。","respondent":"榎本企画財政課長","answer":"この部分が、全体の配分の中では増えてきたという形になりますけれども、逆に投資的経費を削らないと、全体の枠におさまらないというのが実態でございまして、これは特別区が等しく行うべき事務を遂行するという形で。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"ありがとうございました。この辺が、区の出てくる背景というか、予算上どういうふうに、今回の平成２３年度の補正予算とかでは入らない、入ってこないと思うんですけれども、どういうふうに反映してくるのかということを教えてください。","respondent":"榎本企画財政課長","answer":"この９２億円の出どころというか、その算定なんですけれども、この平成２３年度の当初見込みで、２ページのところで平成２３年度の当初見込みというところでは、この調整税はあくまで見込みですので、見込みよりも上回ったということになると。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"全然、何年議員をやっても財調のことがわからなくて、恥ずかしい質問になるかもしれないんですけれども、１ページのところの都議会定例会に付議するものと書いてあるんですが、今回のような財政上のいろいろな税が減収になって、前年度から見ると少なくなっている、そういう状況なので、都議会に付議するという、そういうものなのか、あるいは、例年都議会で第１回定例会にかけて。","respondent":"榎本企画財政課長","answer":"この１ページに書いてあるのは、例年と同じ方針、ほぼ同じというか、ほとんど何年も変わっていないものでありまして、まず都区協議会で協議が整ったことをもって条例を出せるということになりまして、毎年この条例を出しているという形であります。","id":"exchange-010"},{"speaker":"南委員","kind":"質問","question":"それと５ページのところで、再調整の内容ということで普通交付金については繰上償還に充てるというふうに説明されたんですけれども、こういうふうに一定程度の枠がはめられてくるというふうに理解しちゃったんですが、そういう使い道、使い方というのは、ある程度そういう場面、状況というのはあるものなんですか。","respondent":"榎本企画財政課長","answer":"当初、基準財政需要額と収入額の関係でいくと、当初事業に合ったところに充てるという考え方もあるんですけれども、それに充てるよりも、今回はこの繰上償還に充てて、この繰上償還に充てることで将来的な負担を減らすことができるということで、協議が整ったです。","id":"exchange-011"},{"speaker":"阿部委員","kind":"質問","question":"基準財政需要額、経常的経費というのは多分景気がよくても悪くても、少しずつではあるけれども、年々今後も上がっていくような性質のものかなと思うんですが、その分、投資的経費のところで景気が悪いところはうんと下がって、景気が上がるとちょっと余裕ができるというような構造になるのかなと思って。ちょっとその辺の見通しというか、経年の動きというのを説明していただければ。お願いします。","respondent":"榎本企画財政課長","answer":"そのころの全体の配分の中では、景気動向に左右されるのは、この投資的経費になりまして、投資的経費のところで、やはり全体のフレーム見込みの中で調整せざるを得ないです。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、課長からちょっとお話あったんですけれども、都区協議会があって、都区財政調整協議会、それから幹事会とか、いろいろ会合がありますよね。そういう会合、どれぐらいのペースで時間をつくっていらっしゃるのかなというのが１点気になるんですが。","respondent":"榎本企画財政課長","answer":"大体予定がつかないで時間外にやっているというもので、特に今回は、この調整税の見通しがなかなか東京都で立てられなくて、１２月２８日にも夜にやったというふうな状況でございまして、それから年明けも２回ほど開催して、まとめているというような状況です。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"意見","question":"出てみるとすんなり決まっているように見えてしまうんですけれども、この中での、今回もいろいろな課題が出ていたり、議論もされたと思います。現状によって、今回決まったことに対しての都区の協議の課題、うまくクリアしたもの、クリアできなかったものとあると思うんですけれども、その辺をもう少しご説明いただければと思います。","respondent":"榎本企画財政課長","answer":"それからもう一つ大きなものは、都市計画交付金の話でございまして、都市計画交付金につきましてはこの調整３税には入っていないということで、ほとんど門前払いのような状況になっておりまして、実は過去の経緯を見ますと、都市計画交付事業の拡大とか対象を決めるときに。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どの程度、例えば区側からこういう項目を算定してほしいと思っていて通るものなのか、その辺の状況はどうでしょうか。","respondent":"榎本企画財政課長","answer":"それを幹事会の場で相手方にきちんと説明をして、こういう算定になっているけれどもどうかという形で、やはり区長会事務局の職員と区政課の職員も、事務折衝レベルでは情報交換をしておりまして。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"東京都との折衝事なので大変だと思います。もう一つ、あり方検討会の話になってしまうんだけれども、当然これ、財源的にもいろいろ絡んでくると思うんです。これが、いつ実際に事務が行われているかわからない状況ですけれども、そのときにまず事務配分をきちんと終わらせた段階で、財源問題として財調に絡んでくるという考え方でいいんでしょうか。","respondent":"日下部企画部長","answer":"なぜそういう形で都区のあり方検討を進めているかといいますと、これはかつての例の主要５課題のときに、これは基本的に都区の役割分担に応じた財源配分のあり方についてどうするんだということでずっと協議を積み重ねてきましたが、そのときにやっぱり、いろいろな個々の。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今回１％に満たないということで５５と４５の配分率は変わらなかったということなんですけれども、常にずっとそうやってしまうと、そのままいけばマイナスのままいくわけですね、費用としては。１年たったら０.５だし、２年になったら１％みたいになってくると思うんです。そこら辺は今後どういうふうに考えていくのか。","respondent":"日下部企画部長","answer":"ただ、１％というとかなりの額になりますので、その辺の見きわめはなかなか難しいところなんですが、基本的にはやはりそういう姿勢で臨むべきだと、このように考えています。","id":"exchange-017"},{"speaker":"原委員","kind":"質問・要望","question":"ご説明非常にご丁寧にありがとうあります。ちょっと具体的な細かい、３ページ目の算定改善のところでちょっとご説明いただければなと思うのが、算定改善のところの中で、さっき３３項目があるというふうにおっしゃっていたんですけれども、この議会運営費の見直しのところと清掃費の算定改善、この２点と、あと総務委員会関連で何かもう少しあれば、教えていただきたい。","respondent":"榎本企画財政課長","answer":"それからもう一つの清掃費につきましては、やはりごみ量の減に合わせた、実態に合わせた徴収費という形になって、この間ずっとごみ量がどういうふうに推移するのかというのを、実態を見ながら、割と何年か前からの課題になっておりましたけれども。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"前回は２２年度から２３年度にかけて１.８％、今回２.５％、近々で見ても４.３、５％近く流れとして落ちているんですが、やはりそれだけ毎年区民の収入、区民税ですから収入がやはり落ち込んできているのか。もしそういう見方で、企画のほうで今後どういうふうに下がっていくのか、大分前私が話したような内容のものなのか、わかる範囲でいいんですが、教えてください。","respondent":"榎本企画財政課長","answer":"やはりただ、そうとはいえ、この見込みをある程度出さないと算定自体ができなくなってしまうということで、今年度につきましてもぎりぎり、いつもでしたら１２月の中旬ごろに出てくるのが、１２月下旬ぎりぎりになって出してまいりまして。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"そういう国なり、東京都もそういう財調を介しているんだということをおっしゃるんですけれども、他の区との調整の中で、どういうふうに品川区の都市開発、都市計画に要するんだからということを主張してこられている、そのあたりというのはどういうふうに、努力も含めて、していられるのか、主張しているのか、全体の一律的な考え方の中で、どういうふうにそこは品川区としては主張し。","respondent":"榎本企画財政課長","answer":"財調の中でもこの都市計画というか、再開発関係ですけれども、やはりそれは２３区によって、それぞれ事業の重点の部分が違いますし、対象も違いますけれども、そのルールをきちんと定めるという形になっておりますので、実際、今説明した投資的経費は。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"もう１回よく今のご答弁の話を議事録を持って精査しないと、理解できないんですけれども、仕組み的なところはわかりました。そういうふうに理解しているんですけれども、もう少しまた、ちょっといろいろ教えていただきながら、とりあえずそれ以上のことは今日はやめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"阿部委員","kind":"意見","question":"毎回切り捨ててそれはなしということになって、１％を超えるものが出てこないと。ズルズルと切り捨て、切り捨てが続いていくので、今回の１次も２次も、ずっと数字として、ある金額としてためていって、いずれ１％にするための数字のもとになっていくのか、その辺の取り置きはされているのかどうか。","respondent":"榎本企画財政課長","answer":"実際には、まず今回はとりあえず暫定で出ましたけれども、やがては１％になるかならないかを含めて、過去の部分をちょっと積み上げながら、最終的な協議に持っていくという方向です。","id":"exchange-022"},{"speaker":"南委員","kind":"質問","question":"さっきの件ですけれども、実績を見ていろいろとルール化もするんだけれども、しているという話のところなんですけれども、実績ってある程度、何というんでしょうか、例えば開発に関する補助金というのは、品川区の場合、この間１年間で７０億円とか、８０億円とか、平成２４年度は三十六、七億円だったと思うんですけれども、それなりの金額で、結構な額つきますよね。全然すんなりいくんですかね。","respondent":"榎本企画財政課長","answer":"その中で実際の算定が、対応補正等含めながら算定をしていますので、そのルール自体も協議もしておりますけれども、そのルール自体がどういうふうに大きく変えるだとか、例えばルールの１つの項目として、こういう項目を算定してほしい。","id":"exchange-023"},{"speaker":"南委員","kind":"意見","question":"だから一般的に人口だとか、面積だとか、事業所の数だとか、いろいろな指標で品川区だけでなくて、２３区共通で、例えば職員費についても、ほかの部分についても、遜色なくお互いが合意できるところは決めると。それはそれでわかります。それは平均的な部分での合意だと。","respondent":"榎本企画財政課長、日下部企画部長","answer":"すみません。ちょっとなかなか難しいところなんですけれども、基準財政需要額の問題だと思うんですが、やはり２３区それぞれ需要の部分というのは違うと思います。これが２３区、それと都と区の間の一番根っこの部分になっているので、ご心配は要らないです。","id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"質問","question":"防災関係というのは財調に入ってきているのかなというのがわからなかったんですけれども、例えば喫緊の課題もあるし、それから高齢化率が高くなっている、当然福祉の部分も増えてくると思うんですけれども、そこら辺が今後の財調算定していく中での課題、全体的な大きな課題って何があるのかを教えていただければと思います。","respondent":"日下部企画部長","answer":"ですから、災害対策という面でいけば、そういう１つの普通交付金とは別建てできちんと対応できるような仕組みにはなっておりますが、ただ一方で、その割合が果たして今の５％のままでいいのか。","id":"exchange-025"}]},{"id":"topic-03","title":"の行政評価委員会評価結果に基づく事務事業の見直し等","agenda":"の行政評価委員会評価結果に基づく事務事業の見直し等","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"それぞれの事業については、この場というよりも予算特別委員会ですかね。ちょっと３点ほど伺いたい。１つ目、公表なんですけれども、『広報しながわ』のほうでということなんですが、行政評価委員会のご意見をお寄せいただいた方については、別途ご連絡のようなことはされるんでしょうか。ぜひすべきだと思っています。とりあえず１個それをお願いします。","respondent":"久保田行財政改革担当課長","answer":"公表ですけれども、本日、議会にご報告した後に、今委員からいただいたような意見も、実は委員長からもいただいておりまして、指示がもう既にありまして、別途参加された区民委員の方に対しましては。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"将来、３年なら３年で、決めたところで、継続するのであれば、改めて継続を考えるというような形にしていかないと、ついついずるずる、前年並みになってしまうと思います。こうした考え方についていかがでしょうか。それから３点目です。見直し結果と。継続なら同じぐらいで、見直しなら減って、廃止はゼロというような、少しわかりやすいカテゴライズが必要ではないかと思うんですが、いかがでしょうか。","respondent":"久保田行財政改革担当課長","answer":"こうした手続を踏んでということではございませんけれども、さまざまの意見を踏まえまして、事業の廃止というものを今回持ってきたというところでございまして、こうした取り組みの成果を踏まえ、平成２４年度も。","id":"exchange-027"},{"speaker":"阿部委員","kind":"提案","question":"お伺いしたかったことと、ちょっと微妙にずれているような、そう思うんですけれども、あくまでもご提案したので、すぐに明確な答弁をということではなくて、それは検討していただければいいと思うんですけれども、それを始めた事業について見直してねということではなくて、特に啓発事業などについては、あらかじめ期間を考えておくという考え方もあるのではないでしょうかという。","respondent":"久保田行財政改革担当課長","answer":"失礼しました。私どもの今後事業を始めるに当たりましては、そうした考えも１つの視点として取り入れながら、それぞれの事業の開始に当たりましては、そういったことも含め置きながら考えていきたいというふうに思います。","id":"exchange-028"}]},{"id":"topic-04","title":"のエリアメール","agenda":"のエリアメール","exchanges":[{"speaker":"塚本委員","kind":"質問・要望","question":"今の説明の中でもう少し詳しく教えていただきたいんですけれども、今度はａｕとソフトバンクが新たにエリアメールを始めるということですが、これは区から発信をする際に当たって、ドコモ、ａｕ、ソフトバンク、３社に対して、１回で同じものが３社に出るのではなくて、多分３社それぞれ違う発信の仕方があって、端末なのかパソコンの画面などがあって、それぞれやらないとだめなものなのでしょうか。","respondent":"荒井広報広聴課長","answer":"委員おっしゃるとおり、３社別々の窓口を持っておりますので、別々の形で発信することになります。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問","question":"できれば、今は区の行政のシステム、違うんでしょうけれども、さまざまなＩＴ系の技術があるので、技術的には１つの窓口を統合して、そこから３社にポンと同じものが自動的に流れるというようなことは決してできないことではないと思うんですけれども、そういった自動化への対応みたいなものはできますでしょうか。今後は検討していただけるかということです。","respondent":"荒井広報広聴課長","answer":"３社自動化といいますか、一斉配信みたいなものができるかどうか、あくまでも品川区としてはなかなか難しいかと思いますが、こういった自治体が増えていくと思いますので、そういった自治体と手を取り合って要望をするなり。","id":"exchange-030"},{"speaker":"阿部委員","kind":"質問・要望","question":"１つお伺いします。一応確認ですが、これは利用者側からの登録というのは必要ないと考えていいんですか。それからこれ、もしご存じだったら教えていただきたいんですけれども、４月からまもるっちにかわって、たしかエリアメール受信できたような気もするんですけれども、それができるかどうか。","respondent":"荒井広報広聴課長","answer":"１点目の利用者登録ですが、特にこれは必要ありません。その場にいる方の携帯に、強制的に入ってきてしまうです。それから区外での受け取り、他区の状況ですが、すべてのところでは、ちょっとまだ把握し切れておりませんので、状況については調査をしたいと思います。","id":"exchange-031"},{"speaker":"阿部委員","kind":"意見","question":"システム等の問題もあるのかもしれないんですけれども、ぜひ品川区からの配信もまもるっちで受け取れたほうが、便利なのかなと思いますので、その辺、もしできないのであればご検討をお願いしたいと思います。","respondent":"荒井広報広聴課長","answer":"まもるっちですが、端末がａｕのものであるので、ａｕであれば、こちらのエリアメールについては受信可能だというふうに考えるところです。","id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"質問","question":"僕はエリアメール直接じゃなくて緊急速報という中で教えてもらいたかったんですけれども、以前、日にちは覚えていないですが、品川区の庁舎の中に緊急地震速報が、大きなものが入ったのが記憶にあるんですけれども、あれというのは自分のたしか携帯に来なかったと思うんですよね。庁内だけ放送が入っていたのがあるんですけれども、あれはどういう仕組みなのか。それ何かわかりますか。","respondent":"荒井広報広聴課長","answer":"ちょっと把握しておりませんので、調べてお答えするようにいたします。","id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"質問","question":"放送が突然来て、えっ何だろうと思ったんだけれども、逆に庁舎内はわかる、放送が入ったんだけれども、庁内にいる人はいいけれども、区内、防災無線はなかったので、どういう状況なのか、今思い出して急に聞いたことなので、わかったら教えてください。全部できるんだったら全部でやっておいたほうがいいんじゃないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/777073?Template=document&Id=1908#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":35170,"voices":108}},{"id":"h24-20120229-14","meetingId":"h24-cm02","date":"2012年2月29日","dateIso":"2012-02-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午後２時２３分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を67件抜き出しています。","topics":[{"id":"topic-01","title":"平成２４年請願第３号「豊葉の杜中学校（旧荏原四中）の跡施設に特養ホームなど高齢者福祉施設の設置を求める請願」","agenda":"平成２４年請願第３号「豊葉の杜中学校（旧荏原四中）の跡施設に特養ホームなど高齢者福祉施設の設置を求める請願」","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この間、特養に入れている方などの人数をお聞きしたいのですけれども。去年８月に締め切ったところでの申し込みが５９１人と聞いたのです。その方のうち、どれくらいの方が入れたのか、また、その後９月から、ちょうど今日が締め切りになるかと思うのですけれども、申し込んだ方がどのくらいいらっしゃったか、わかれば教えていただきたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"２０１０年１０月から２０１１年３月までの半年間で申し込まれた方が５９５人、入れた方が６０人ということで、１割強ということなのです。この間、区は厚生委員会などでも、一定の条件が整えばということをずっと繰り返されているのですけれども、一定の条件というのをどうお考えか、お聞きしたいのですけれども。","respondent":"久保田行財政改革担当課長","answer":"厚生委員会等の一定の条件ですが、直接の所管ではございませんが、これまでの議論の中ではやはり、例えば３,０００m2以上の敷地があるとかといった一定の規模以上のものを確保した上で、そういうものが確保できるということであれば。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間、杜松小跡地と平塚橋会館の跡に、また建設していただくということで、そこはすごく歓迎しているのですけれども、品川区内に特養ホームとしては、杜松小跡と平塚橋会館跡を合わせると１０施設目ということになるのですよね。いろいろ、防災の用地にという声も高いということですけれども、特養ホームと防災用地として一緒に活用することはどうお考えかなとお聞きしたいのですけれども。","respondent":"久保田行財政改革担当課長","answer":"私どもはこの地域につきましては、防災上の危険度の非常に高い地域と認識しています。地域の要望も、そういったものはかなり強いというところが現実です。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはりそういった際にこういった施設に入居されていれば、そこが避難所にもなりますし、そういった意味でも、一緒に活用できるのではないかと。ですので、やはり避難が困難な方々がこれから増えていくことも想定しまして、入居施設と防災施設を一緒に兼ね備えたということも必要になってくるのではないかと思うのですけれども、もう１度お伺いしてよろしいでしょうか。","respondent":"久保田行財政改革担当課長","answer":"避難の関係ですけれども、私どもにつきましては、避難誘導ができるように地域の方と連携して、要介護者の避難誘導訓練も地域の方と行ってありますので、まずは一たん、学校避難所等の避難所に行っていただきまして、その後、落ちついた後にそうした要介護の施設。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"要援護者の避難、また、その登録が進んでいない中ですので、私は本当に不安に感じます。それで先ほどもありましたように、一定の条件、３,０００m2はないですけれども、大きな施設、土地になりますので、そこを確保していく、そこに施設をつくっていくというのは、今、必要なことではないかなと私は思いますので、ぜひ、この要望に私はこたえていきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、特養ホームの整備についての区の基本的な考え方といいますか、スタンスといいますか、四中についても触れられていましたので、もう少し詳しく伺いたいと思うのですけれども、まず初めに伺いたいのは、平成２１年５月に設置された行財政改革特別委員会のまとめの中で、杜松小および四中跡地について。","respondent":"久保田行財政改革担当課長","answer":"２点目の社会的要因ですけれども、私どもも特養の整備は３つの緊急課題の１つに掲げ、大変重要な課題であると認識していますが、都市部におきましては、なかなか新たに土地を購入して施設を整備するといったところも難しい状況もあります。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、高齢者福祉等の活用について、四中での検討はどのようにしてきたのか、どう受けとめているのか、ご説明がなかったためにそこを伺いたいと思いました。最後にもう１点、住みなれた地域をどう考えているのかとご説明したのですけれども、直接、特養ホームの配置についてご説明がなかったので、改めて伺いたいと思うのです。品川区はこうしたお年寄りの気持ちがわかるか、伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"１点目ですけれども、平成２１年の行財政改革特別委員会の提言ですが、幾つかの項目をいただいていると私どもは認識していますので、そういった要望を総合的にいろいろ判断しまして、整備計画、跡地活用の検討を進めているところです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"行革の提言については、改めて読み直していただきたいと思うのですけれども、杜松と四中とを同時に求めているわけです。そういう社会的要因を考えているのであれば、どういう物差しで特養ホームの必要性を感じているのか、例えばこれくらいの人口でこれくらいのベッド数、そういう考え方をなぜ持たないのか、伺いたいと思います。そういう生活圏をなぜ見ようとしないのかを伺いたいと思います。","respondent":"日下部企画部長","answer":"そういう状況を踏まえて、これもご案内のように、厚生労働省でも、これは１自治体のレベルの話ではありませんので、例えば平成２４年度から始まる第５期の介護保険事業計画におきましても、例えば２４時間の在宅の介護、それから医療。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"実際、特養ホームをつくりますと、デイサービスやショートステイの施設も入ってきますから、それをまとめて特養ホームと僕なんかは言うのですけれども、むしろ在宅の支援のためにもそういう施設の拠点は大事だと思うのですが、その辺はどうお考えなのか伺いたいと思います。とりわけ特養ホームというのは、福祉避難所としての機能を兼ね備えるわけですから、その視点をどう考えるか、なぜ考えないのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"避難所機能の強化だけでは、とても住民の生命と財産は守り切れないと思うのです。ですから、先ほど言ったのは、避難所機能も、受け入れの拡大も必要です。あわせて住宅耐震化の支援も必要です。災害弱者だったり、お年寄りだったり、そういう支援が必要です。防災対策を総合的に、相乗的に考えていく、そういう視点をしっかりと持つべきだと私は思うのですけれども。","respondent":"日下部企画部長","answer":"有料老人ホームのお話が出ましたけれども、３５万区民というのは、やっぱりいろいろ幅広い皆さん方がいらっしゃるわけですから、それぞれの置かれたいろいろな条件に応じて、例えば要介護になったときに。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言だけ意見を言いますけれども、今、部長がおっしゃったのは、施設と在宅は対立ではないと。特養ホームと防災対策も対立ではないと。だったら、本当にこの請願に書かれているとおり、四中跡地は地域の方々の切望する特養ホームや認知症グループホーム、ショートステイ、老健施設など、高齢者福祉施設をぜひ入れていただきたい、その検討を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"西本委員","kind":"確認","question":"なので、ここは質問しようかと思ったのですけれども、区のビジョンをどう考えるのかなと思いましたら、先ほど部長がきっちりと答えられていたので、確認で今、言わせていただきました。それと質問としては、青稜高校に貸し付けた後、ほかの学校で改築する予定があるのかとか、そういうときにせっかくあるわけですから、貸し出しできるような状況として、そういうのが今挙がっていないかどうか。","respondent":"久保田行財政改革担当課長","answer":"今、豊葉の杜中学校で使っているプレハブ校舎を２棟建てているのですけれども、それを引き続き青稜高校が借りる形で学校を使ってまいりますので、そういう意味では今このタイミングですと、青稜高校はうまくプレハブ校舎も使って貸せるということではありますが。","id":"exchange-012"},{"speaker":"阿久津委員","kind":"確認","question":"会派として、第４回定例会で一般質問でも、防災系の施設の地元ニーズがあるということを、区の方針についてお伺いした経緯もあります。校庭を開放すれば本格的な避難施設になるのか。長々と意見を述べてしまいましたけれども、確認なのですが、何度もお聞きして申しわけないのですが、今、伺っている中で、どのような災害施設への地元のニーズがあるのかということで、もう１度確認をしておきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"それ以外にも、例えば、防災ではございませんけれども、防災訓練ができる多目的広場については、地域のスポーツ団体等へ開放するとともに、地域コミュニティーの活性化にも資するようなものをつくってもらいたいですので、そういう意味で避難所としての機能というもの、また。","id":"exchange-013"},{"speaker":"阿久津委員","kind":"質問","question":"何度もお伺いして申しわけなかったのですけれども、今回、理事者側の答弁、私は本当に地元の意見も請願も含めて真剣にとらえていると思いますし、限られた資源の中で、今、必死に区も考えていると私はとらえています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"渡辺委員","kind":"意見","question":"結論を出します。この請願について、願意に沿いがたいと考えています。というのも、今も質疑の中でも十分ご説明いただいたように、また、この表題についても、行政の認識、高く持っていられる、あるいは地元の意見、区分という、地元住民もあるけれども、全区的な行政需要を考えなければいけない大きな政策課題であると。以上です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"今日、結論を出したいと思います。今、阿久津委員がおっしゃったように、まさしくそのとおりで、今まで本当に区の側としてもやらないというわけではなく、ちゃんと沿った意見を持っていらっしゃる。そういう意味では、もう１度、地元のニーズ、また、区民のニーズをしっかりと両方聞いていただいて、決めていただきたいと思っています。不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"今日、結論を出すでお願いしたいと思います。私どもの意見としては、まず、今回の請願の中にもあります、議会で議論も実施していますし、また、議会からも提言や要望を出して、区としてもしっかりと受けとめていただいている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"意見","question":"今日、結論をお願いいたします。不採択でお願いいたします。ここで議論するという意味では、行政改革の視点からいうと、もっと大きな視点で考えていくべきだろうと考えていますので、特定するのではなくて、品川区全体の施策を含めた形で何をするのかということの議論の中での荏原四中の使い方という希望になるのかと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"プレハブ校舎があるところは平米的には２,０００m2ですから、区が理想とする１００名程度の特養の３,０００m2からはちょっと小さいですけれども、それでもこうした高齢者施設をつくることは十分検討の余地があると思いますし、それをおさえたとしても真ん中に校庭があきますので、消防団の方々の訓練、少年野球や地域の方々の日常的なそういう活動の場というのも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"平成２４年陳情第５号「旧第一日野小跡地は、暫定貸し付け期間終了の後は、特養ホーム、認可保育園","agenda":"平成２４年陳情第５号「旧第一日野小跡地は、暫定貸し付け期間終了の後は、特養ホーム、認可保育園","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"委員長がご指摘のとおり、この問題はこの間、たびたび議論をしてきたところですけれども、まずはじめに１点、この間の議論を確認したいのは、ＴＯＣから具体的な建て替え計画が示されなければ、暫定貸し付けの延長はもちろんのこと、本格貸し付けもあり得ないと。この立場に変更がないのか、改めて伺いたいと思います。この１０年間というのは一体どういう考え方に基づくものなのか伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"１０年間の根拠ですけれども、これにつきましては、平成１７年当時にお話をさせていただいたときに、ＴＯＣから営業を継続しながら建て替え計画を進めていきたいということでございまして、そういった中で建て替えの期間についてはおよそ１０年間。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかも、今年の９月ですから。それが区としての条件がなければ、結局、ＴＯＣが出したものを丸のみするということですか。要図なのか、公式なのか、条件なのか何なのか、ここがあいまいになると、まさに丸のみになってしまうと思うのですけれども、そこを伺いたいと思います。それもオーケーだと区は考えていらっしゃるのか、そこを改めて伺いたいと思います。そこをしっかりとご説明いただきたいと思います。","respondent":"久保田行財政改革担当課長","answer":"次の２点目ですけれども、具体的な条件につきましては、これもこの間ご説明してまいりましたように、やはり地域経済の活性化、まちのにぎわいのためにＴＯＣが果たしてきた存在というものがありますので、そうした中でＴＯＣが建て替えることによりまして。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に負担金についてだけ、もう１度伺いたいのですけれども、今の説明ですと、何について合意をし、何について協議をしているのかがわからないのです。改めて、ＴＯＣと何について合意をしているのか、そして品川区は何に対して、金額は幾ら求めているのかを伺いたいと思います。同時に、どうもこの説明はあいまいなので、お互い文書か何か交わしているのでしょうか。口約束なのでしょうか。","respondent":"久保田行財政改革担当課長","answer":"金額につきましては、大変申しわけございませんが、今の時点で公表はできないものでございまして、中身等につきましても現在ＴＯＣと協議をしています。","id":"exchange-022"},{"speaker":"中塚委員","kind":"確認","question":"ＴＯＣと区に、何か交わしたものはあるのですか。存在しているのか、いないのか。それとも口約束なのか。そこだけはしっかりと確認させてください。","respondent":"久保田行財政改革担当課長","answer":"私どもは現在、暫定貸し付けをしていますので、それにつきまして、きちんと暫定貸し付けの中での契約書は当然交わしています。そうした中で、覚書も交わしておりまして、きちんとした契約関係を結んでいるところです。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"であれば、しっかりとそれをこの委員会にも示していただきたいと思いますけれども、いかがでしょうか。あわせて、最後、意見ですけれども、結局何も決まっていないＴＯＣの建て替えに協力するよりも、今日的に切実な保育園や防災広場や特養ホームなど、地域要望を優先した活用に、私は切り替えるべきだと思いますし、この際はしっかりと説明会など、そういう場の設定もあわせて必要だと思います。","respondent":"久保田行財政改革担当課長","answer":"私どもはきちっと契約書を結んだ中で、その移転経費が例えば幾らでどこの範囲というものを結んでいるものではございません、そういうものを書いているものではございませんけれども、一時使用目的についての賃貸借契約の中で。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"その契約書の中にあると先ほど説明したのだけれども、契約書の中にはないのですか。逆に、何がそこに書かれているのですか。負担金と言わないのだけれども、協力金という名前なのか、あまりよくわからないのですが、何を合意しているのか、そこが見えてこない。","respondent":"日下部企画部長","answer":"今、課長がご説明させていただいた一時貸し付けについての具体的なその中で、例えば案文として明記しているとか、要するに移転経費について協力することについて、具体的にそういうものを明記しているものではございません。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、採択すべきだと思います。先ほども指摘しましたけれども、ＴＯＣへの建て替え支援に協力するよりも、住民要望こそ優先すべきだと思います。最後の部長の答弁でも、結局この間、説明してきた負担金についても根拠がなかったことが私は明らかになったと思います。こんな暫定貸し付けも本格貸し付けも前代未聞。根本的に見直し、白紙に戻すべきだと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"平成２４年陳情第６号「旧大崎第二地域センターを売却せず、区民のために活用することを求める陳情」","agenda":"平成２４年陳情第６号「旧大崎第二地域センターを売却せず、区民のために活用することを求める陳情」","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭の説明で、この建物ができたのは昭和４７年３月ということですけれども、古い話なので、もう少し当時の経過を伺いたいと思うのですけれども、だれから、何の目的で購入したのか、当時の経過を聞かせてください。その上で、この擁壁は現在の所有者はだれなのか。建設当時の経過も含めて、この擁壁の所有者と管理者が今現在どういう関係だと区はお考えになっていらっしゃるのか、伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"位置指定道路等の関係もありますので、現時点では私どもの所有と考えているところではありますけれども、ここにつきましてはさらに詳細な調査等が必要になる可能性はあるのかなと思っているところではあります。現在では品川区の所有であると認識しています。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"かかわり方はいろいろあるでしょうけれども、何らかの一端があると思っているのかを改めて伺いたいと思います。つまり、例えるならば本棚のブックエンドのような状態なわけですよね。建物があって、地下で擁壁を支えているわけですから。そのもととなっている建物を取り除いてしまったら、擁壁の強度といいますか、役割がどうなってしまうのかと思うのですけれども、そこはどうお考えなのか伺いたい。","respondent":"久保田行財政改革担当課長","answer":"擁壁の件ですけれども、私どもは今現在、品川区の所有との認識がありますので、例えば修繕等が必要であれば、品川区でやらなければならないと認識しています。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"陳情に書かれている区民のための活用について若干触れたいと思うのですけれども、近所の方にお話を伺ってきました。現在の運用の改善も必要だと思いますけれども、今後の検討を考えるときにそうした視点は持ちながら、旧大崎第二地域センターの跡地活用と、道を挟んだ反対側がシルバーセンターですから、一体的に考えていただけたらと思うのですけれども、その点はどうお考えなのか伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"シルバーセンターですけれども、私どもはこの跡地活用を考える上ではシルバーセンターも含めて検討しなければならないと認識はしているところではありますけれども、入浴施設云々につきましては、現時点では私どもとしましては考えは持っていないです。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"こちらについては意見だけ。１点伺いたいのは、陳情にもあります２つ目の項目ですけれども、利用方法を検討するに当たっては、地域の方々の声、要望を聞く場をぜひ設けていただきたいと思うのですけれども、いかがかということです。ご近所の方にお話を伺ってきましたけれども、そもそも品川区が跡地の活用を現在検討していることそのものを周辺の方々は知らないと。","respondent":"久保田行財政改革担当課長","answer":"私どもとしましては住民参加という場面を設けるということではなく、品川区として、ここの活用については日ごろより区民の声、また、区議会からもいろいろな意見を寄せられてありますので、そうしたものを踏まえながら検討を進めていきまして。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"いつも区が考えを示してからというご説明がありましたけれども、地域に入って思ったのは、検討されているそのものを知らないわけです。これではやっぱりよくない。やはり地域の方々に参加していただいて、一緒にこの検討を進めていこうという形を持っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"本日、結論を出したいと思います。結果は不採択です。意見といいますか、これについては、この当委員会の項目の１つになっておりますし、盛んに今議論をしている最中ですので、いろいろな意見をお聞かせいただきながら進めていきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日、「結論を出す」ということと、採択をすべきだと思います。先ほども指摘しましたが、この地域は計画からしても売却ありきではなくて、区が責任を持って、擁壁も含めて、利用方法を考えていただきたいというのと、利用方法を決定するに当たっては区民の声や要望を聞く場を設けて進めていただきたいと思います。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"の２「特定事件調査」を行います。 はじめに、(1)の「区の組織と関連団体に関すること」","agenda":"の２「特定事件調査」を行います。 はじめに、(1)の「区の組織と関連団体に関すること」","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう１つわからないのでご説明いただきたいのが、学校施設開放管理業務委託はどういう仕事の内容なのか、まずご説明いただきたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"両方やっているものです。学校施設開放管理業務委託ですけれども、こちらは小中学校の開放時における施設の管理ということで、小学校３７校、中学校１４校に対して行っているものです。","id":"exchange-034"},{"speaker":"中塚委員","kind":"質問・要望","question":"どういうことですかと言ったら、施設管理が２４時間機械対応というのですか、形が変わるので土日がなくなってしまうのだという話を伺ったのですけれども、もしよかったらどういうことなのか、できるだけ雇用の機会をつくることが大事だと思うのですけれども、伺いたいと思います。区が直接窓口になってやらないのはなぜなのかと思うのですけれども、設立の経過と理由とあわせてご説明いただきたいと思います。","respondent":"福島ものづくり・経営支援課長、原高齢者福祉課長","answer":"何らかの工夫ですけれども、事務局にこういう意見もあるので何らか工夫したらどうですかという助言はできますが、区からこうしたらどうかと言うのはなかなか難しいと思いますし、また。貸付事務そのものは、申し込みその他は学校の生徒がそのまま申し込むケースもありますので、そういった意味では学校が受付をし、事務を取り扱うほうが私どもとしては生徒の部分も含めて。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"福祉タクシー券のほうはどうなのか。今の説明ですと、歳入の多くが会員さんからの寄付でなっていて、区もたしか事業ごとに助成をしている関係があったかと思うのですけれども、福祉タクシー券は区が主体的にやるのではなく、品川区社会福祉協議会を主体としてやっている理由は何なのかと思いまして、ご説明いただきたいと思います。","respondent":"永尾障害者福祉課長","answer":"福祉タクシー券ですけれども、実施主体は区です。委託事業として社会福祉協議会に委託をしております。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"福祉タクシー券ですけれども、品川区だと敷居が高いというお話ですけれども、であれば、来やすくすることが大事だと思いますし、さまざまな高齢者にしろ、障害者にしろ、申請の関係で区役所も訪れますから、そういう理由であれば、しっかり区で改善して、区主体の仕組みに検討していくことも必要なことではないかと思いますが、改めていかがでしょうか。","respondent":"永尾障害者福祉課長","answer":"利用者サイドから言いますと、やはり敷居が高いというご説明をしたのですけれども、実際に事業費等を計算いたしますと、人件費も常勤職員１年分、アルバイトの方２人、３人とそれくらいの人件費で事業自体ができるという意味から考えると。","id":"exchange-037"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"品川区シルバー人材センターなのですが、いろいろ数字が平成２０年度から平成２２年度、出ている中で、２番の喫煙マナーアップの事業を読んで、平成２１年度と平成２２年度では１０倍になっていて、これは都の補助金の関係があるのかと思うのですが、ここは平成２１年度と平成２２年度でそれほどまでに業務の内容が大きく変わったのか教えていただきたいのと、区からの助成金が出ていますが。","respondent":"福島ものづくり・経営支援課長","answer":"やはりそう考えていきますと、なかなか会員に対する配分金を下げてまでというのはかなり厳しいだろうということで、最近のシルバー人材センターに入っている会員の方は、やはり生活費を稼ぐという面もかなり多いと伺っていますので。","id":"exchange-038"},{"speaker":"石田（慎）委員","kind":"質問","question":"わかりました。自主事業ですが、８つある中で、就業機会拡大推進事業、シルバーしながわ就業支援事業、無料職業紹介事業は、要は雇用に関係する事業だと思うのですけれども、こういった類似した事業をあえて別々にやられているのはなぜなのか。今後、どのようにしていくのか、その辺もあわせて教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"無料職業紹介事業につきましては、サポしながわと連携しまして、６０歳以上の高齢者の無料職業紹介を行うという内容ですので、３つともそれぞれ別々なので、一緒にするのはなかなか難しいと思いますが、ただ、実際にやっている事務職員の中ではちゃんとやっていますので。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"内容に触れていた場合には指摘していただきたいと思いますけれども、先ほど説明があったら重複してしまうのですが、再度確認なのですけれども、まず、シルバー人材センターの中で、区からの助成金、区からの貸付金という枠で、貸し付けということは返していただくお金という形なわけですよね。そのお金が収入、歳入という形で品川区に入ってくるという理解なのでしょうか。貸付金という役割はどうなのかなと。","respondent":"福島ものづくり・経営支援課長、原高齢者福祉課長","answer":"私から、シルバー人材センターの区からの貸付金についてご説明しますけれども、こちらは当然年度ごとの貸し付けですので、４月当初に貸し付けて、その年度内に返していただく。そのメリット・デメリットは、今までの社会福祉法人とのパートナーシップでの連携というメリットと、一方で民間の活力、新たな試み、こういったところも交えながら、両方を共存しながら進めていくというのが私どもの考え方です。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"逆に、外部団体だからということではなくて、さらに密着した形で協議を持っていかないと難しいのかなと。１点だけ、確認だけしますと、社会福祉法人、いろいろな経緯があってと。それで民間もいろいろ今後使っていきましょうという話なのですが、コストの面でいうと、運営を委託するときにあまり差がないのか、やはり区のほうがいいのか、それは現実的かどうかはどういう認識なのでしょうか。","respondent":"原高齢者福祉課長","answer":"民間と社会福祉法人のコストの関係です。在宅介護支援センターで行きますと、民間と社会福祉法人ですけれども、こちらは基本的には同じ金額で算出根拠をもとに委託をしています。","id":"exchange-041"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"すみません。障害者と高齢者、全体の事業がありますね。は社協まで入れると６つ、ここで担ってもらっている部分が何割くらい。大きく分けると、ＮＰＯ、民間、違う社福、あとはこの６つと、自分のところで自主事業もちょっとはあるのだから、一番大きいのは人件費だろうけれども、そういう部分を入れて１０をわかりやすく、割合を教えてもらえればなと。そこだけ教えてください。","respondent":"福島ものづくり・経営支援課長","answer":"こちら無利子で貸し付けをしております。","id":"exchange-042"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"いいです。後でいいのですが、５団体は多分、どれくらいのペースで回っているかわかっていると思うのだよね。５つの法人はどれくらいで回っているとわかると思うんだよね。例えば福栄会だったら多分３％くらいではないかとか、春光福祉会なら赤字ではないかとか、それは我々も何となくわかる部分もあるから、多分それは押さえられていると思うのだけれども、そこだけわかれば教えてください。","respondent":"原高齢者福祉課長","answer":"そういう中で、単年度収支で見ていきますので、利用者が多いときと少ないときといろいろありますけれども、平成２２年度の数字で見ますと、マイナスのところは２カ所。全くプラスマイナスゼロというところが１カ所。それから、少し５％に近いところが２カ所です。","id":"exchange-043"},{"speaker":"石田（秀）副委員長","kind":"確認","question":"もう１回だけ確認をさせてください。先ほど最初の説明の中で、そういう読み方をしていいのかと思ったのですが、春光福祉会に小規模多機能の補助金、助成金を出していると言ったのだけれども、やめてしまったから、そうするとこの四三十何万円はなくなるという理解でいいのかだけ教えてください。","respondent":"原高齢者福祉課長","answer":"小規模多機能につきましては、１年に４４８万円を各民間も社福も含めて助成をさせていただいているところです。平成２２年度は春光福祉会は年度途中で終わりましたので、月割で助成させていただいて、その後についてはなくなったという状況です。","id":"exchange-044"}]},{"id":"topic-05","title":"の「財政に関すること」","agenda":"の「財政に関すること」","exchanges":[{"speaker":"石田（慎）委員","kind":"確認","question":"それ以外の、例えば幾ら以上になったときは何％を区のほうにとか、そういう方式がとられているのかどうか確認をさせてください。その２点をお願いします。","respondent":"阿部経理課長","answer":"その一方で、以前は駐車場の管理費用として平成２２年度につきましては１,５００万円程度かかっていましたけれども、来年度の予算につきましては１,０００万円弱ということになりますので、そういうトータルの意味で管理も含めまして考えれば。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"やっぱりコミュニティーの場がなくなったということで、一緒になってつくれないかということもあるので何とかしてほしい、何とかならないかということも書かれていましたけれども。どうにもならない、売却だという意見ではなくて、何とかしてほしいというところなのですけれども、区民への説明はどうでしょうか。","respondent":"久保田行財政改革担当課長","answer":"活用につきましては、やはりこれまで繰り返しご説明してまいりましたけれども、区としての責任をもった主体的な活用の素案をつくった上で区民の方にご説明をして、その後、意見を求めながら、よりよい活用方策を探していくというか、一緒になって考えていくというところで。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"議員にも伝えて議会でもという話ですけれども、こういった陳情が上がって署名に回った話も聞きますと、そんな話は全然知らなかったという声もまだまだありますので、こういった跡地を活用するときに区民の声を聞くというのは、私は当然のことだと思っていますので、ぜひそこは積極的に区から進めていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点だけ、陳情の部分にも書いてあったのですけれども、議会で売却ありきの議論がされているというようなニュアンスの部分があったのですけれども、この委員会では、売却を含めてのさまざまな視点から考えていったほうがいいのではないかという議論をしていただけであって、別に売却ありきで議論しているわけではないので、それは柔軟にどうやっていったらいいのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問","question":"売却もあるかなという、議論にはそういう売却の方向性も出されたわけではないですか。売却という１つの言葉を聞いて区民の皆さんが思うではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"売却をしたほうがいいと言ったのはあなたですよね。意見の１つと言っていたのはあなたですよね。それは議論をされたという事実ではないですか。何を聞きたかったのかがさっぱりわからないのでもう一度説明してください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"売却ありきで議論をしているわけではなくて、その方法の１つとして売却も考え得るのではないですかと言っただけであって、決して売却をするべきだとも言っていないし、売却をするように議論を進めていくべきだ、検討を進めていくべきだということを言っているわけでもないので、売却ありきには当たらない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"前回の議論、もっと言うと６月ぐらいから大崎第二地域センター、いろいろ議論がありましたけれども、その中で１つ１つの言葉じりはとりません、主張の流れを聞くと、売ってしまったらどうかという意見が１人とかではなくて複数から、もっと言うと議席で言うと多くから出てきたわけですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"主に第二地域センターについては、先ほど私、主張していましたので、ぜひその方向で進めていただきたいということと、伺いたいのは庁舎の駐車場設備で７２万円の貸付料ですけれども、どのように決めたのか、その仕組みを伺いたいと思います。","respondent":"阿部経理課長","answer":"その中で４社の応募がございまして、応募の内容、提案の内容としては、どういう駐車場の管理をするかということと、貸付料をどのくらいにするか、大きく言えばその２つの提案を受けて、その提案を検討した結果。","id":"exchange-053"},{"speaker":"中塚委員","kind":"意見","question":"一番高かったけれども、内容と双方を見てということですよね。金額というのは、よくわかりやすいものなので、逆に内容についてはどういうふうに評価の軸を置いたのか、ご説明いただけますか。","respondent":"阿部経理課長","answer":"実際に実績があるのかどうか、あるいはトラブル時の対応をどうするか、こういうところが主な点です。トラブル時というのは、出庫するときに、例えば開かないとかそういうことがありますから、そういうときにはどういう対応をとるのかという点を含めまして検討したです。","id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"今回、公募型ということですけれども、一方で旧第一日野小学校みたいに、区のほうで価値を定めて金額を決めて貸す、２つ、今あるのかと思うのですけれども、今回そうしたのはなぜなのかと。","respondent":"阿部経理課長","answer":"旧第一日野小学校と違いまして、庁舎の駐車場は利用する方が来庁者の方が、８時半から１７時１５分までは主体です。","id":"exchange-055"},{"speaker":"石田（秀）副委員長","kind":"確認","question":"先ほど石田（慎）委員が聞いたのにあわせてなのですが、定額で７２万円はいいのですけれども、こういうやり方は無料の方もたくさんいらっしゃるから、非常に難しい算定をされているのだろうと思うのだけれども、当初はこれでいいけれども、５年間行きますよね。これだけ確認させてください。","respondent":"阿部経理課長","answer":"ただ、夜間になりますと、特に中小企業センターなんかはそうですけれども、大体夜間は有料の方が多いと。庁舎もそうですけれども、有料の方もいる。そういうデータはいただきます。","id":"exchange-056"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"データをいただいて、ぜひ５年間よく見ていただいて、結構この７２万円で利益が出ているようなら、やっぱり半分くらいはくれる契約に切りかえたほうがいいと思うので、それだけはお願いだけしておきます。","respondent":"武内委員長","answer":"税外収入について、もう１回、関係することなので、ご意見等いただければありがたいと思いますけれども、いかがでしょうか。","id":"exchange-057"},{"speaker":"阿久津委員","kind":"確認","question":"先ほどの擁壁の改修に２億円くらい必要だというご説明もあったのですけれども、前にお聞きしたと思うのですが、念のために確認で、シルバーセンターは、耐震の関係等もあったと思うのですが、いつまで使えるのでしたっけ。","respondent":"久保田行財政改革担当課長","answer":"私どもでは、耐震改修促進計画がありますので、区有施設等につきましても、それに合わせまして、平成２７年度末までには耐震等の必要な施設については、それらを進めていきたいと考えています。目標としては平成２７年度末までには何らかの形でです。","id":"exchange-058"},{"speaker":"阿久津委員","kind":"提案","question":"平成２７年度に何らかの改修がシルバーセンターは必要であると。すみません、具体的なご提案までは行かないのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"中塚委員","kind":"質問","question":"擁壁の改修２億円ですけれども、やるとすると区の単費になるのか、それとも補助金の関係とかはどういう感じになるのか。東五反田ケアホームをつくるときの裏側、擁壁を直していますから、いろいろあるのかとは思うのですけれども、２億円の財源はどういうことがあるのか、そこまで検討されていなければあれですけれども、状況だけ教えてください。","respondent":"久保田行財政改革担当課長","answer":"現時点では改修に合わせてやるということであれば、区の単費になると想定しています。","id":"exchange-060"}]},{"id":"topic-06","title":"事件調査を終了いたします。 ──────────────────────────────────────────── ３ その他 (1)","agenda":"事件調査を終了いたします。 ──────────────────────────────────────────── ３ その他 (1)","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"作成していただきたいと思います。これまでのまとめは非常に継続した議論のときにとても運用に役に立ったと思います。特に重複な意見を省ける、時間を大切にするという大人の会話において必要な資料だと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"山元委員","kind":"意見","question":"公明党もぜひ意見をまとめていただけると、今までにない議員同士の意見が出てきたものだと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"石田（慎）委員","kind":"提案","question":"同じく、まとめていただければと思います。本当にいろいろな、以前から継続されている審議の中でも有効と思いますし、今後、提案をするに当たっても必要だと思いますので、まとめをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"西本委員","kind":"質問・要望","question":"私どももぜひまとめていただきたいところではありますが、気になるのは、どういう形で外部に出すことになるのかというところで、例えば本当に今回の特別委員会をまとめていただいて、わかりやすくて、自分も頭の見直しができたので、非常によかったと思うのです。それは透明性を含めてやっていきたいのですけれども、そういう課題もあるよという指摘の中で、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"中塚委員","kind":"意見","question":"指定管理者の問題も、例えば官製ワーキングプアの指摘もしていましたけれども、どうやってまとめる方向をつけたらいいのかというのは、正直、議論そのものは活発だと思いますけれども、苦労がいるなとは思っているのです。ただ、こうした議論をしてきたということ、議会の意思をしっかり伝えていくことは必要なことだと思いますので、そういう方向でということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-065"},{"speaker":"中塚委員","kind":"意見","question":"案文を整理していただいて、次回、示していただけるということで結構なのですけれども、もし可能でしたら、この間の意見というのは割と早めに示していただいて、じっくり読み込む期間がありましたので、案文を示すのも、要するに２日前ではなくて、できるだけ早い時期に示していただけたらと思いますので、出来上がり次第というところもあるでしょうけれども、可能でしたら、お示しいただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"},{"speaker":"中塚委員","kind":"意見","question":"どうしても今、資料が２日前になるので。ただ、この間、主な意見ご参考にというのが割と早く来て、それ自身読み込む時間が取れたので。もし可能でしたら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/177763?Template=document&Id=5918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":62614,"voices":193}},{"id":"h24-20120301-17","meetingId":"h24-cm03","date":"2012年3月1日","dateIso":"2012-03-01","committee":"震災対策特別委員会","time":"午前１０時００分～午後２時０６分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を64件抜き出しています。","topics":[{"id":"topic-01","title":"特定事件調査と予定表２の報告事項","agenda":"特定事件調査と予定表２の報告事項","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"何点か確認といいましょうか、質問ですけれども、まず、東京都防災対応指針におけることについて確認します。だから、これは東京都の指針だから今ここで言っても始まらないんだけど、こういうものを参考にした上でやはり、品川区の昼間人口は５０万人以上と言われるし、それから瞬間的にはもっといるかもしれないときがあるわけでしょう。それからお願いいたします。","respondent":"高山防災計画担当課長","answer":"委員、ご指摘のとおりでございまして、行政、公助を前面に押し出してしまいますと、それは長い目で見ますと、当然のことながら区民の負担といったことに、税金での負担ということになりますので、まずは自助、そして共助ということで組み立ててまいりたいと。","id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"すごく型どおりでわかりやすいんですけれども、いろいろなことをずっと想定していくと、未曾有の被害と言われるわけじゃないですか、東京都の震災については。その瞬間、瞬間に自分がどういう行動を取って、自分の命を守っていく。やはりそれが実は防災の最もベースにあるべきだと私は思うんですよ。だから、そういう観点でもう少し温かい答弁をお願いしたいと思うんですが、いかがでしょうか。","respondent":"中山防災課長","answer":"自助の関係につきましては、来年度改定予定の我が家の防災ハンドブック、全戸配布の中で、もう少し中身の濃いものにして、自助のあり方というものを全面的に打ち出してまいりたいと思ってあります。","id":"exchange-002"},{"speaker":"伊藤委員","kind":"質問","question":"そのとおりだと思うんですよね。すべての区民もそうだし、それから品川区に瞬間、存在するという言葉はおかしいか、その場にいる方々、すべての方々にやはり共通に理解してもらわないといけない話じゃないですか、今の話は。","respondent":"片田防災まちづくり事業部長","answer":"そういう中で、即座に判断できるような工夫を含めて、区民の方に啓発を継続して、粘り強く伝えていかなきゃいけないと考えますので、そういう場面、場面を想定しながらどのような情報提供のあり方があるのかと。","id":"exchange-003"},{"speaker":"伊藤委員","kind":"確認","question":"あれでおもしろいことに、水面がプラス１ｍになったらどれぐらい浸水被害が出るかということの想定が出るんですよ。だから、ああいうことを考えていくと、いろいろな津波の可能性があるんだなということを痛感したわけであって、で、すみません、何度も確認しますけれども、先ほどの話の中で高潮・津波対策、平成２４年の春に新たな東京都の津波の被害想定が出るわけですよね。その後どうするんですか。","respondent":"武藤都市整備下水道課長","answer":"我々としましても、先ほど説明しましたように、想定外の対応というのは大事な教訓だと考えていますので、想定がどういうことになろうと、東京都の発表のそれがどういうことになろうと、区として待つことなく対応をとっていくべきだとまず認識しております。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろんやっていただきたいと思うんだけれども、次のステップとしてしっかりとした、区民の皆さんにためにやっていきますよ、避難計画と言ったらいいのかな、より実践的なものをつくっていかないと、標高の低い地域の方々は非常に心配のままで日々を過ごしていかなければいけないと思うので、その部分についてのもうひとつ具体的な対応をお聞かせいただければと思うんですが、いかがでしょうか。","respondent":"武藤都市整備下水道課長","answer":"あわせて、近くに、直近に標高の高いところがなければ、避難場所として例えば避難ビル等の指定の検討も進める必要があると認識しております。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大体これでまとめて言いますけれども、つまり津波に対する３月１１日のことに対していろいろな、皆さん、危機意識が高まった。となると、今度はある意味、住民の皆さんの不安が現実になってきたわけじゃないですか、目に見える形で。それから、最後に１点だけ、すみません、立会川に防潮堤がないような気がしたんですけれども、それはいかがでしょうか。確認だけお願いします。","respondent":"武藤都市整備下水道課長","answer":"そういった高潮護岸等の高潮の対策が早期に進むよう区としても東京都に強く働きかけて、またできる部分については協力して進めていきたいと認識しております。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問・要望","question":"当然、広報やホームページで本当に詳しく、わかりやすく出していただいているのは十分承知しておりますが、実際には、先ほども出たように避難所が、ここは海抜が低い、危ないぞと逆に不安をあおるだけではなくて、その浸水のシミュレーションが出た後に、私はどこまで行けばいいんだとか、本当に全員が自分で管理、自己管理できるような、そこまでの意識を一人ひとりが持ってもらうような。","respondent":"武藤都市整備下水道課長","answer":"今年の春に出る東京都の被害想定を踏まえまして、そのデータを活用してわかりやすい形でまた区民への情報提供を考えて、わかりやすい形で浸水想定を、またどういった高さまで浸水が来るのかということを公表していきたいと考えております。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"一般論でお聞かせいただきたいと思うんですけれども、地震が起きた後によくニュースなどで気象庁が津波の警報はありませんとか、津波には心配をしてくださいとか、よくニュースなどで、テレビで出るんですけれども、あの判断というのは行政の中で、国全体を考えて、あれは気象庁がやる役割で、それを聞いた上で自治体が、県レベル、市町村レベルが対応するものなのか。","respondent":"片田防災まちづくり事業部長","answer":"気象庁のほうは、広域的な観点からきちんと情報収集をした形で、東京都、あるいは各自治体に情報を提供するといった体制をとっておりますので、その情報をもとに区としても津波警報の防災行政無線での周知を図るとかいろいろな、これまでも対応をとってきたところですし。","id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"１つお聞きしたいのが、昨年３月１１日の目黒川の状況ですけれども、一度、地震後、水が一気に引いて、その後数cm水位が上がったということを聞くんですけれども、その区の防災カメラとか、そういう何か記録があるものなのかどうなのか、今後のことに生かせるデータとしてということで、そういったものは把握だとか、そのところだけお聞かせいただきたいと思います。","respondent":"岩田都市環境事業部長","answer":"立会川におきましても、最下流部で水位計を持っておりますので、こちらで把握しております。３月１１日のときの詳細なデータは区で保管しております。数十波にわたる津波が押し寄せて、１ｍ前後の潮位変動があったという記録が残っております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都防災対応指針のことでお聞きしたいんですが、ホームページから分厚い資料をとって読んだんですけれども、ここの中で、この概要の中にも出てきているんですけれども、木造密集地域の消防水利の確保と、初期消火体制の強化というところが何回か出てくるんですけれども、この中で多機能型深井戸の整備を推進していくということで書かれていたんですけれども。","respondent":"岩田都市環境事業部長","answer":"１つは、当然のことながら飲料水用の備蓄。それから、東京都が避難場所に設置しております１,５００ｔのいつでも飲める応急給水槽、こういったもので基本的には３日分の水は既に確保されておりますけれども、次には生活用水の確保をどうしていくか。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、もう一つ、ここの中で出されていたのが救急医療の耐震化というので、私はこれも決算特別委員会の中でも質問させていただいたんですけれども、医療機関の耐震化が救急医療であってもここで書かれていて、救急医療機関の耐震化率が６２％しかなっていない、これは多分、全都でそうなっていると思うんですけれども、そういうところで。","respondent":"品川防災整備担当課長、片田防災まちづくり事業部長、山口防災安全担当課長","answer":"病院施設の耐震化のほうですが、基本的には病院施設は病院独自で耐震化はやっていただくというような形で、その中で区としても助言。ちょっと補足しますと、特に病院というような防災上重要な施設については。区としての具体的な調査というのは特に行っておりませんけれども、必要な防災対策というのはやはり、東京消防庁というか。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それなのでつくり直しているところなんですが、これを見て改めて品川区でも液状化する危険のところが何カ所もあるわけなんですが、その中で特に私が心配だなと思ったのが、火力発電所が２カ所とも液状化の発生しやすい地域というところで出されているんですけれども、そういう中で、そういう状況に対しては品川区としてどう考えられているのか、そして臨海部に火力発電所、それから石油タンクですとか。","respondent":"中村建築課長、山口防災安全担当課長","answer":"そういった観点からいたしますと、火力発電所も必要な地盤の杭で支持をしていることから、想定されるところの地震におきましては、あるいは液状化におきましては安全という見解で今のところ立っております。もしも火災等が発生したときの対策としては、例えば必要な消防設備、泡消火設備だとか、そちら辺で対応するという整備がなされているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう答弁だとちょっと納得いかないですよね。この間の３月１１日の震災のときも、石油タンクのすごい火災がいろいろなところであって、それがまちのほうまで、気仙沼などはかなり起きてしまったわけですけれども、そういうところでどういうものが、どれぐらい品川区の中にそういうものがあるのかという、まず実態を教えていただきたいと思うんですが。","respondent":"山口防災安全担当課長、片田防災まちづくり事業部長","answer":"危険物の分布ということですけれども、一応やはりそれも、危険物については消防庁のほうで危険物施設について設置するに当たっての許可というものを届け出されていまして、そちらのほうで大体何基あるか。手元に資料がございませんけれども、特に危険物等については耐震改修促進計画をつくるときにおいても、逆に区の中にどの程度の、例えば一定量の危険物を貯蔵しているとか、そういう施設を想定しての話なんですけれども。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今日、液状化と津波というところでのテーマになっているわけですから、そこら辺のところではぜひそういう数というのは、把握しているというのであれば、ここでわかるような形でお知らせいただけるように準備をしてほしかったなと思うんですけれども、次の委員会でも結構ですので、どれぐらいのものが、危険のものがどれぐらいあるかというのはご報告いただきたいと思うんですが、よろしいでしょうか。","respondent":"片田防災まちづくり事業部長","answer":"詳細というと、全体の像としての件数とか、そういうところについては一応ご報告させていただきたいと思います。ただ、実際の量とかですね、そういうところについては現時点でいろいろな課題がありますので、そこのところは控えさせていただければと考えています。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"危険なものがどれぐらい、どこにどういうものがあるかというのはご報告はいただけないですか。","respondent":"片田防災まちづくり事業部長","answer":"促進計画の中で把握している数字等についてご報告します。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、火力発電所の建物は杭をきちんと打っているので安全だということだったんですけれども、いろいろと見ていましたら、これは２００９年３月に臨海部の地震被災影響検討委員会報告書というのが、国土交通省関東地方整備局が発足させた委員会でその報告書が出されて、そのところでは液状化に伴う側方流動により護岸が９ｍ以上も水平に変移し、護岸は壊滅的な被害を受けるという。","respondent":"岩田都市環境事業部長","answer":"液状化に限定してご説明しますと、液状化のシステムは前回バスの中で、瓶で実験をしたとおりです。砂地盤、品川区の場合は大体深さ地表から１０ｍぐらい掘りますとそこに非常に固い層が出てくるんです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"タンクについてもそういう耐震というところでも、耐震化が図られているということで、地震や津波、それから液状化、そういうところでは、臨海部のところでは危険なものはないということで考えられるということなんでしょうか。","respondent":"岩田都市環境事業部長","answer":"ただ、先ほど言いましたように、タンクとか、ビルは液状化の影響は受けませんけれども、それをつないでいる配管、これらは地震動によって動きますので、これの耐震化がどこまで東京電力の場合進んでいるかというのは。","id":"exchange-017"},{"speaker":"金野委員","kind":"質問","question":"この東京都防災対応指針、これに対しての先ほどのご説明で、東京都を襲う地震像の海溝型地震という、これを想定しているということなので、具体的に、では、東京都はその海溝型地震を想定しての津波対策、東京湾での具体的な津波対策みたいなのが示されていましたら、その内容を参考までにまずお聞きしたいと思います。","respondent":"武藤都市整備下水道課長","answer":"今、委員のほうからご指摘のありました津波の想定被害につきましては海溝型地震の想定を今年の春に出しますけれども、それの想定の被害に対する対応については、東京都もその想定を待ってからと聞いておりますので、今後のその状況を区としてもは注視したいと考えています。","id":"exchange-018"},{"speaker":"金野委員","kind":"質問","question":"その動きを待ってということで。そのときに、直接東京湾に面する地域の対応というのを品川区としても独自でできる対応もあるんでしょうけれども、やはり東京都がやるものに対してどこまで一緒にやるかというところですけれども、先ほど少し出ました火力発電所等々もある中で、こういったものへの具体的な対応というのが、もしも具体的にこんな形で、あるいはあるものでありましたら教えてください。","respondent":"岩田都市環境事業部長","answer":"おそらく考えられるのは、高潮、例えば伊勢湾台風級の台風が東京に来ていたときに巨大地震が発生した、いわゆる最悪の最悪のケースでの検討をするかどうかということが出てくる可能性はありますけれども、一般的に通常の。","id":"exchange-019"},{"speaker":"金野委員","kind":"質問","question":"確かに情報をいただいて、その先ですね、情報をいただいて、じゃ、どういうふうに自分で自助にしていくかといったときに、先ほどのデータ、今日からですかね、この品川区の統合型地図情報提供サービス、これが検索できて、あっ、うちはこういう高さなんだな。じゃ、避難するときはこうなんだな。","respondent":"片田防災まちづくり事業部長","answer":"逆に、正しい情報の中で区民も心配されるとか当然出てきますので、そこをきちんと区も入った形でハザードマップをつくって、実際に地震が起きたときに具体的な行動としてどこに避難するの、あるいは高台、あるいは避難ビルみたいなものを協定するのであれば。","id":"exchange-020"},{"speaker":"金野委員","kind":"意見","question":"その中で啓発をしていく、あるいは皆さんと一緒につくっていく。そうなると、今、ホームページで公開されている中に避難通路、避難経路、避難ビル等々も全部ハザードマップというか、そういうのが入ってきて検索ができるのか。","respondent":"岩田都市環境事業部長","answer":"実は資料、これ、使っていいのかわかりませんけれども、今日、差し替えていただいた資料の古い資料、これが実はハザードマップの説明が入っておったんですが、これは予算特別委員会で議論していただく内容なので、勇み足だったのでここは削除させていただいたんですが。","id":"exchange-021"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひ、今本当に、今日も朝地震があって、きのうも何回かあっての中なので、本当に皆さん、防災意識は頂点に達するぐらい、いつ、何時という、こういう状態を、よく声を聞きますし、また３月１１日、これで１年になりますし、ですので、今お示しくださったその予定でこのハザードマップはつくられるんでしょうが、なるたけ早く皆さんにこの情報を提供していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山内委員","kind":"質問","question":"液状化のほうから伺います。いただいた資料の中の対策の中の３番で、被害率の高い地域においては水道管を耐震継手管に取り替えるなどの液状化対策を進めているということで記載されています。品川区では都立公園が１カ所、そのような状況があったという報告が上がっているということなんですが、今この都の対応という中で、品川区がこういった液状化対策が進められている状況なのかを伺います。","respondent":"武藤都市整備下水道課長","answer":"２３区全部その古い、耐震性のない水道管についてはすべて取り替えるということで進められておりまして、品川区内においてもその耐震が進められております。申しわけございません、今、詳しく品川区内でどれほど耐震化率が進んでいるかというのは手元にはございません。","id":"exchange-023"},{"speaker":"山内委員","kind":"質問","question":"品川区の液状化の見直しというものが今ここに含まれて今検討されているのかということと、この土木技術支援・人材育成センターの方々が今いろいろと調査をしているとか、学識経験者も含めてということらしいんですけれども、専門アドバイザーの方々と品川区との意見交換とかいうのはされているのかということと、今どのように見直しが進められて、まあ、見直しが進められているということは。","respondent":"武藤都市整備下水道課長","answer":"液状化にかかわる東京都の検討状況ですけれども、今、東京都のほうでは、先ほどの東日本大震災を踏まえまして、今回の液状化の特徴としては、長時間の振動における液状化被害が一つ特徴であったということで、そういったことも踏まえつつ。","id":"exchange-024"},{"speaker":"山内委員","kind":"質問","question":"東京都から何の資料が出てきたら、じゃ、品川区もそれに沿ってやりましょうというんではなくて、品川区独自の、やはり品川でお勤めされている方々が品川区のことを一番状況を把握していると思うので、品川区独自のものをある程度検討というか、していかなくちゃならないのかなと思うんですが、そのあたりはどうなんですか。","respondent":"片田防災まちづくり事業部長","answer":"ただ、今回の大震災を含めて、昭和６２年に発表したものが正しかったかどうかというところを今検討しているという状況で、方法としてはＦＬ法という判定する測定のやり方があるんですけれども、それの評価が正しかったかどうかということも含めて、今。","id":"exchange-025"},{"speaker":"山内委員","kind":"質問","question":"品川区にも水門、防潮堤の耐震、特に水門に関することで伺いたいんですが、先ほど防潮堤では杭を打って護岸の部分というののあれを耐震化しているということなんですが、水門に関して例えば震度７クラスの地震が来ちゃったときですよね、建物が倒壊する危険性があるという中で、水門が仮にですよ、仮にこれが倒壊してしまったというときにどういった被害状況が考えられるのか。","respondent":"武藤都市整備下水道課長","answer":"あわせて、総務局で被害想定を見る中でも、委員会の検討結果も踏まえつつ、想定を超える対応も観点に置きつつ、仮に壊れた場合どうなるのかということも検討の視野に入れていると聞いております。","id":"exchange-026"},{"speaker":"山内委員","kind":"確認","question":"検討を視野に入れているということは、まだ何も話がされていないということなんでしょうかね。そこの確認と、それから、それこそ品川区にある水門等のそういった防ぐ、いわゆるそういう建物というかな、そういう建築物は耐震に、もちろん耐えられるというものを想定いろいろやっていると思うんですが、どれぐらいまで耐えられると考えているのかな、その２つちょっと教えてください。","respondent":"武藤都市整備下水道課長","answer":"１点目のご質問にありました視野に入れているというところの状況なんですけれども、水門が壊れた場合の被害想定なんですけれども、その辺の、どういった被害想定を出すかというやり方を含めて東京都のほうでは検討していると聞いております。","id":"exchange-027"},{"speaker":"山内委員","kind":"質問・要望","question":"という中で、私、１つ聞きたいんですけれども、高潮のメカニズムが与える被害というのは一体どういうものなのかな。どういうものなのか。その辺の、高潮の被害というものをもう一回ちゃんと我々にも教えていただきたい。それから、我々からいろいろな方々、若い世代、それからもちろん知らない方々にも教えていくということが我々の仕事だと思っているんですけれども、そのあたりをお願いします。","respondent":"岩田都市環境事業部長","answer":"高潮というのは、台風というのは低気圧ですから、伊勢湾台風の場合は上陸直前まで９００ヘクトパスカルを下回る巨大台風です。中心の気圧がですね。通常は１,０００ヘクトパスカルぐらいありますから、その間１００ヘクトパスカル低いんですね。","id":"exchange-028"},{"speaker":"山内委員","kind":"質問・要望","question":"今まさに想定外のところ、部長が力説していただいたんで、それが大事なんですよね。それが大事だということが今回一番教訓としてわかったことではないかなと思うんで、すべてにおいて想定外のところの部分をやはり理事者の方々にしっかりと認識していただいて、これからの区民の皆さんの安全を守っていただきたいと、そんなふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"渡部委員","kind":"確認","question":"逆言うと、これを下手に知ることによって、浦安とかを目の当たりにしていますから、それこそ区民の財産、地下の下落とか何だとかというのまで波及する可能性はあるんですけれども、この辺、やはりしっかり情報として出ているわけですから、今後ハザードマップとかをつくっていかれる中で、どうなんでしょう、やはりこういう発表がされているよというのはしっかり聞くべきだと思う。","respondent":"片田防災まちづくり事業部長","answer":"それで、対策も含めて考えていただきたいということを伺いますと、今、委員ご指摘のように、区としてもハザードマップ、あるいはそういう状況を、これまで持っていた情報をどうやって区民にお知らせするかといったところを含めてちょっと力点を置いていきたいなと考えております。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"今はそれについてやっていますというような、実は今本当に防災に対して地域の方々はすごく期待されているし、自分たちでもいろいろ考えて動くようになっているときですから、できれば、平成２４年度中に品川区の地域防災計画が出ると思いますが、途中の経過報告みたいなものをホームページ上でも、どこかで、町会で出します回覧板とかでも何か触れられたほうが。","respondent":"高山防災計画担当課長","answer":"委員ご指摘のいわゆるスケジュール感のようなものを区民と共有するべきでないかというご指摘、確かにそのとおりでございまして、東京都の被害想定の時期でありますとか、東京都の防災計画の改定時期なども徐々に示されてきておりますので。","id":"exchange-031"},{"speaker":"渡部委員","kind":"意見","question":"地域の防災アドバイザーを受けられている方ですとか、それのまた上級コースじゃないですけれども、されている方、本当に意識が高くて、いろいろしていらっしゃいますので、やはりみんなで自助を強めていくという部分でも、常にそれを考えてやっていくのはいいことだと思いますので、ぜひよろしく、お進めいただくようお願いいたしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問・要望","question":"帰宅困難者につきましても、東京都としては、この前、防災訓練をやられたみたいですけれども、帰宅困難者の帰宅ルートみたいなものを設定して、そのところに拠点、拠点に休めるところというか、栄養補給できるようなところみたいなことも考えているようですけれども、そういったところをどういうところでつくっていくのかというところも、これは広域の災害の対応として考えなきゃいけないと思うんですが。","respondent":"高山防災計画担当課長","answer":"区との関係というか、連携につきましては、そういった東京都との役割分担を踏まえた上で、東京都で働きかけるようなものについては引き続き働きかけるとしまして、区で対応せねばならない一時滞在場所の確保など、そういった部分については区の責務として引き続き民間事業者。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"具体的に津波避難ビルは、じゃ、どこなんだとなっていく。そういったことを、できてからまたどうのこうのと直したりとかという時間はないと思いますので、やはり最初から最善のものを検討するにはしっかりと情報を共有するとともに、対策を詰めていく段階でも共同で協議するというんですかね、そういった場というか、そういう方針というか、やり方というか、そういうのは具体的にありますか。","respondent":"高山防災計画担当課長、片田防災まちづくり事業部長","answer":"被害想定が出された後なんですが、当然、区との連携はもちろん地域も含めまして、市区町村との連携は欠かせないということで、東京都の計画の素案をつくる段階で市町村の意見を聞く。例えばツイッター等について、あるいはエリアメールとか、そういうところでの情報発信なんかについてもこれまで工夫を行ってきたところですし、あと。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問・要望","question":"東京都の２３区は特に日ごろから、ほかの基礎自治体と比べれば連携が密になっているというか、情報交換もしやすい環境にあると思いますので、本当に遺漏なくというか、情報交換をしっかりされて、防災対策、広域にということを意識されながらしっかりと立てて、詰めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"木村委員","kind":"質問","question":"これもテレビか何かのニュースだったと思うんですけれども、やはり同じような防災無線のハウリングのために聞こえないということで、改良が必要だというようなことをやっておりましたけれども、そういうことも、この品川区では今のところどういう状況であるか教えていただければ。","respondent":"高山防災計画担当課長","answer":"そういった影響もありまして、どうしても音が伝わりにくいという状況もございまして、これを補完する手段ということでエリアメールについての導入と、それからツイッターなどの補完手段、それから新年度また予算特別委員会でご審議いただく内容ではありますが。","id":"exchange-036"},{"speaker":"木村委員","kind":"質問","question":"エリアメールだとかそういう、ツイッター、高齢者の方々には絶対にそういうことは、絶対ではありませんけれども、やるわけはないと思うんですけれども、防災ラジオですか、これも最高４分の３が補助になるということ、また２分の１が補助になるというようなことも聞いておりますし、この防災ラジオについて今、これからあっせんをやるわけですけれども、この普及率というか、これから。","respondent":"中山防災課長","answer":"今、防災ラジオにつきましては、この間、説明会を設けまして、３月１９日ですか、プロポーザルをやることになってあります。それで、３月２１日に決定するということで、製品の開発とかですね、それから製造に結構時間がかかるというようなことです。","id":"exchange-037"},{"speaker":"木村委員","kind":"質問・要望","question":"課長の読みどおりいけばいいわけですけれども、なるべく本当に、各家庭に１個備えるぐらいの感じでいかなければいけないと思います。そういうことで、電話が入るというふうな、区民の皆さんにもっともっと広げていく、周知をしていくことが大事だと思いますので、ぜひ一人でも多くの方々にそれがわかる、知らせることができるように、ぜひ行政としても努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどの津波の話なんですけれども、津波、液体力学上にあって、２ｍ以内であろうという想定をなさっていると聞きましたが、先ほど山内委員からもご質問がありましたが、高潮と津波の違いのお話の中で、高さ以外に力の差と、それから時間の経過の差を教えていただきたいんですけれども、お願いします。","respondent":"武藤都市整備下水道課長","answer":"高潮と津波の違いということですけれども、先ほどご説明しましたとおり津波はあるスピードを持って陸地に押し寄せてきます。つまり、陸地側への運動エネルギーを持つような形で押し寄せてきますので、高さに加えてそういった運動エネルギーを持っています。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"違いをお伺いしたのは、時間経過によって逃げる、要するに経過ですよね、人間が逃げるに対してのどういう順序で、どうしていったらいいかということが違うと思うんですよ。それと、あと、３月１１日の津波とか、高潮とはちょっと外れるんですけれども、家具による圧死というのは何％ぐらいあったんですかね。ご存じですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問","question":"もう一つなんですけれども、将来的に、最後のところでお伺いしたんですけれども、住所リストを入れると区内の標高ですか、の地図が上がってという話、後ろにもこういう、これですが、この地図を見せていただいたんですが、ここをやると、将来的に、私は思うんですが、液状化予報図もわかり、また密度ですか、防災に対しての住宅の密集地域なども、自分がどこにどうなっているかとか。","respondent":"高山防災計画担当課長","answer":"もう一点、道路に関する情報提供ということで、それを１つの地図で、切り替えることによってすべてご自身で取りたい情報が取れるような、そんなような仕組みで運用を開始する予定でおります。","id":"exchange-041"},{"speaker":"高橋委員","kind":"確認","question":"２つお尋ねしたいんですが、１つは、私が聞き漏らしたのかもしれませんが、立会川の、ほかの委員からも質問があったんですが、河口から国道までの立会川の部分で、護岸の整備がまだかということと、あと水門の設置がされていないのかという、そこのところもう一回、立会川の整備について確認したいんですけれども。","respondent":"武藤都市整備下水道課長","answer":"具体的に立会川の高潮対策なんですけれども、東京都のほうで中心になって検討しまして、具体的には今後、高潮の対策として水門を設置していくと、いわゆる護岸、高潮護岸でまちを守るんではなくて、河口部に水門を設けることで海側から来る高潮を防ぐという計画をしておりまして。","id":"exchange-042"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、緊急性で、どれぐらいかということもあると思うんですが、東京都の平成２４年度の予算の中で具体的に今の水門について例えば調査する費用とか、項目がないとすれば何かの中でそれをやっていくかとか、そういうことが何らか出ているんですか。すみません、私が東京都の予算を詳しく見ていないので、申しわけありません。","respondent":"武藤都市整備下水道課長","answer":"もともと、先ほどもご説明しましたように、以前から立会川の計画には着手して、水門をつくるという計画を立てていますけれども、さらにそれを促進できることの検討も含め、東京都のほうでは今年度からは既に検討に入っていると聞いております。","id":"exchange-043"},{"speaker":"高橋委員","kind":"質問","question":"もう一つは、先ほどからも出ていますが、いろいろな区がやろうとしていることの提供というか、区民の方への周知なんですが、ホームページや広報やケーブルテレビというお話がいつも出てくるんですが、先日、避難所訓練に幾つか参加させていただいたときに、ちょうど時期的に、例の高さのあの話があったので、職員の方がこういうのをやっていますよという説明をしていただけたんですが。","respondent":"高山防災計画担当課長","answer":"標高図が一番象徴的だと思うんですけれども、かなり区民の反響が多いということは実感しております。一つの取り組みとしましては、防災センターの２階部分なんですが、ご覧いただくと壁面に大きく標高図のほう、拡大コピーしまして掲出しております。","id":"exchange-044"},{"speaker":"金野委員","kind":"質問","question":"先ほど、津波の件をお聞きしましたが、この防災計画の別紙の資料、防災の予報を伝達する系統図があります。具体的にお聞きしたいんですけれども、この津波対策でいわゆる予報の伝達というところのシステムが出ているわけなんですけれども……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"金野委員","kind":"質問・要望","question":"とれぐらいの高さだよ、どれぐらいでという、そういう具体的なところまでお知らせをしていくんだろうと思うんですけれども、この指示でいくと、気象庁から東京都、東京都から湾岸部の地域を含めての１０区ですかね、来て、そして品川区からは地域防災行政無線、広報車、サイレン、それから支所、出張所と書かれているんですけれども、具体的にこれ、どういう形で区民の皆さんにお知らせが行くのか。","respondent":"中山防災課長","answer":"広報車を回している時間があれば当然回せると思うんですけれども、ちょっと時間的には無理かもしれませんので、そういう場合には自主的に避難を、あらかじめ決めておきますので、そこに避難していただくということになろうかと思います。","id":"exchange-046"},{"speaker":"金野委員","kind":"確認","question":"というのは、今回の３月１１日で、ご自分のおうちの中にいたときに、ご自分が置かれている状況がわからなかったと。テレビで見ていたのは、この遠く離れた私たちは目の当たりにしていましたけれども、現場の人たちは見ていなかったといった場合、そこまでの想定をして区民の皆さんへの周知というところを考えていらっしゃるかどうか、具体的にどうされているのかを確認させてください。","respondent":"高山防災計画担当課長","answer":"しかしながら、具体的な手順についてマニュアルとして詳細に定めているかというと、この部分については若干至らぬ点もありますので、この点につきましてはマニュアル化などをしまして、広報車なども含めましてさまざま手段を組み合わせるような形で。","id":"exchange-047"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひ、そこら辺の具体的なものもお願いしたいなと思います。ですが、津波に関しては、とにかく強い揺れが感じた場合は、海沿いの方たちは逃げるということを常に頭に置いといていただかなきゃいけないという、こういう処置も大事だと思いますので、そこら辺の周知徹底というところでもやっていただきたい。そこら辺のお考えはどうですか。","respondent":"片田防災まちづくり事業部長","answer":"すぐそばの避難ビルと高台があるのであれば、すぐに行動に移していただくといったことを学校避難所連絡会議とか、区民の防災組織も含めて、いろいろな機会をとらえて区のほうとしても周知してまいりますし、あわせて今、防災ハンドブックといいましょうか。","id":"exchange-048"},{"speaker":"金野委員","kind":"質問","question":"どこでも、いつでも、起きて、それが避難所として皆さんの目に触れていかれるようなものを考えていかれる、それはどうでしょうか。","respondent":"岩田都市環境事業部長","answer":"まだこれからハザードマップについては検討していくので、具体的にこれということはまだ決まっていませんけれども、従来の地震対策、いわゆる火災からの避難所を設営して、これは区が指定して。","id":"exchange-049"},{"speaker":"金野委員","kind":"質問・要望","question":"確かにそうだと思います。区で全部を賄うというのは、これは難しい。その間をとるのは区の方がやはり主導でやっていただきたいというのもありますし、その中で決まったところには標示をしていただくという流れはもうお考えかと思いますけれども、ぜひその点、区が主導でする自助を後押しする、そういった意味での区の主導というのは必要だろうと思いますけれども、どうでしょうか。","respondent":"岩田都市環境事業部長","answer":"表現ちょっと難しいんですけれども、区はもちろんいろいろやるんですが、今回の区が地域に入っていって、企業や住民も、あるいは町会の方と手づくりでつくっていくわけですね。この過程が大事だと。","id":"exchange-050"},{"speaker":"金野委員","kind":"質問・要望","question":"おっしゃることはよくわかります。汗をかく。お互いに汗をかくんですが、そのきっかけづくりという意味です。要するにきっかけができないから、今回のきずなというところは見直されましたけれども、そのきっかけはどうやってつくるんだというところで皆さん、なかなか一歩前に踏み出せていないという状況が私はうかがえると思うんです。そのきっかけづくりをぜひしていただきたいという意味です。","respondent":"岩田都市環境事業部長","answer":"うちの職員は大変でしょうけれども、１年間、汗をかいて、まずモデル地区からやりますから、そこでどれだけうちの職員と地域が汗をかいて、標準的な手順書ができかるというのはご期待していただきたいと思います。","id":"exchange-051"},{"speaker":"向委員","kind":"意見","question":"Ｗｉ－Ｆｉの実証実験を実施と書いてあるんですが、要はこうやってＷｉ－Ｆｉで今、無線ＬＡＮとか仕組みは、結構まちなかへ行くとどこでも無線ＬＡＮでネットにつなげる環境は整っていますし、コンビニエンスストアですとか、ちょっとした店舗でも使えるようなところはかなり増えていますが、区としてはこういう環境の整備は、どのくらい整備されていこうかなとお考えなのかを。","respondent":"高山防災計画担当課長","answer":"区として整備というのはなかなか、すぐにはハードルが高いかと思うんですが、東京都のほうがこの震災を受けまして実施しております帰宅困難者の訓練などにもこういった通信訓練などを踏まえた帰宅困難者訓練を実施しているというお話も伺っておりますので。","id":"exchange-052"},{"speaker":"向委員","kind":"質問・要望","question":"実際いろいろ私も調べてみると、今、通常は例えばＮＴＴとかフレッツなどの契約をしていないと、コンビニエンスストアの無線ＬＡＮが使えないとか、そういう基本的には有料サービスでまちなかの無線というのは使えるところがほとんどだとは思うんですが、それでもソフトバンクは結構、美容室とかでも無料で設置しませんかとかいうところが増えてきていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"液状化対策のところで１点お聞きしたいんですけれども、３番の東京都の対応というところで、インフラ施設等の被害防止ということで、東京都では下水道管とか、マンホールの接続部における耐震化やマンホールの浮上抑制対策や、今回の震災を踏まえてということで液状化対策を進めているということで書かれているんですが、この対策というのは品川区では、耐震化やマンホールの浮上抑制対策。","respondent":"武藤都市整備下水道課長","answer":"インフラの東京都の対応における品川区の状況ですけれども、下水道管の耐震対策、具体的には２点ございまして、今、委員のお話にあったように、マンホールの接続部と、マンホールのそもそもが浮上抑制する対策なんですけれども、これにつきましては品川区では。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"マンホールがすごく浮き上がってしまったのは、浦安のところに視察に行ったときに目の当たりにしてきたわけですけれども、そうすると、じゃ、品川区は来年度中にはそれが完成するということで、ああいうふうな状況にはならないということで考えていいのか、それを１つ確認させてください。","respondent":"武藤都市整備下水道課長、岩田都市環境事業部長","answer":"その際、その中のマンホールにつきましては東京都で既に対策をとっておりまして、浦安市のような状況はなかったと聞いておりますので、品川区で対策をとったところにつきましてもかなりの効果を発揮するものと期待しておりますが、何分。耐震化率ですけれども、ほぼ、９８％目黒川は終わっております。ただ、終わっていないのが谷山橋、五反田大橋かな、この２橋がまだ架け替えが終わっていませんので、そこのけたの部分が耐震的に弱いと、こういうところです。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この間ＮＨＫで報道された、私はちょっと見られなかったんですけれども、りんかい線ではなくて地下鉄に津波が押し寄せてくるという、そういう報道がされていたということを聞いたんですけれども、そのりんかい線、それからあとは環状品川線、そういう地下のトンネルの高速道路のところに津波が入ってきてしまうんじゃないかという、そういう心配をしているわけですけれども、そこら辺の想定と。","respondent":"岩田都市環境事業部長","answer":"津波にしても、高潮にしても、自然災害の場合の基本なんですけれども、まず、行政体が想定を出さなきゃいけないんですね。だから、例えば津波であると今まで１.２ｍ、高潮だとＡ.Ｐ.の４.１ｍまで上がりますよという。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それが出てきてから、どういう対応がとれるかということを検討するということになるんでしょうか。そういうときに対応するすべがあるのかというところもあわせて、わかったら教えていただきたいなと。","respondent":"岩田都市環境事業部長","answer":"そういう形で今後流れていくわけです。それに対して行政体から補助を出すか出さないかというのは、またちょっとこれ、別の話なんですけれども、流れとしてはそういう形になります。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"考え方としてはわかりますけれども、例えば中央環状品川線なんかも一気に水が入っていってしまったら、どうやって助けられるのかなという思いがあるんですけれども、そういうところはどういう対策がとれるのか、今のところで考えられているところがあったら教えていただきたい。","respondent":"岩田都市環境事業部長","answer":"道路側でとめるか、それとも高潮護岸のほうのいわゆる港湾局が管理している、島を持っている、そこの高さを上げて想定津波に対応して大井埠頭の中に水が入ってこないようにするかというのは、あくまで今度は想定の結果が出て。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今年の春を目途にしてそういう被害想定が出てくるということですので、それが出たらぜひ不安のないような形での対応をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"向委員","kind":"質問","question":"先週の２月２０日、フジテレビの「とくダネ！なので、その取材の、本日お伺いしたいのは取材の経緯、書面だけであったのか、もしくはメールとか、対面、電話とかでほかにも取材を、しっかりやりとりがあった上でああいうふうな取り上げ方に結局なってしまったのかとか、番組内容を見て実際抗議する内容という判断に至ったのか、そのあたりをまずご説明いただけますでしょうか。","respondent":"中山防災課長","answer":"そのほか、防災対策については、平成２４年度には市民参加によるハザードマップの作成だとか、企業と連携して避難所の締結だとか、また区内５００カ所に海抜標示を設置する等々のご説明を申し上げたところなんですけれども、それで、じゃ。","id":"exchange-060"},{"speaker":"向委員","kind":"質問","question":"最終的に文書か何かで抗議とか、そこまではするお考えはないんですか。","respondent":"中山防災課長","answer":"それで、担当したスタッフは具申したらしいんですけれども、担当のディレクターが、要するに答え方として、高潮に津波は包含されているというような形で武藤都市整備下水道課長がお答えになったんですけれども、それをどうも、じゃ、津波はやっていないんだなというような形で。","id":"exchange-061"},{"speaker":"向委員","kind":"質問・要望","question":"なので、震災がこういうふうに起こると結構取材とか、品川かいわいに関する注目もかなり高まっているのは周知の事実で、なので、本日も自助、自助というお話と、あと正しい情報をお知らせしていくことが自助につながるというお話も皆様からたくさんありましたけれども、視聴者には取材の経緯も見えませんし、やはりテレビに出てしまうとそれが影響としてボンと印象を与えてしまうので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"伊藤委員","kind":"提案","question":"例えば個人、家庭、住宅、小中学校、それから企業、公的機関、津波と防潮堤、交通対策、いろいろな項目があるわけですよ。だから、個々のことについては間に合わないので、項目だけでもいいから、議会としてはこういうことについて平成２４年春でしたっけ、出せる東京都の被害想定に基づいて具体的な計画を立てるようになんていう表現でまとめたらどうでしょうかという提案をまずします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"本多委員","kind":"意見","question":"去年３月１１日のときに、品川区が抱えた課題というのがたくさんあると思うんですね。例えば鉄道事業者との連携がうまくいかなかった。改めてまた会派ごとに出すなりしたほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/629730?Template=document&Id=6404#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":57295,"voices":157}}]);
